local System = require("System.System")
local readonly = System.readonly
local Text_AvgVideoCaption = readonly({
  AvgVideoCaption_100284_Content_1 = {
    Text = "Zeichenbrett, Papier, Farben"
  },
  AvgVideoCaption_100284_Content_10 = {
    Text = "Es ist wirklich etwas unheimlich"
  },
  AvgVideoCaption_100284_Content_100 = {
    Text = "Wahnsinn und Gier"
  },
  AvgVideoCaption_100284_Content_101 = {
    Text = "Das ist die wahrste Gestalt der Menschheit und der Welt"
  },
  AvgVideoCaption_100284_Content_102 = {
    Text = "Alle Kunst ist dazu da, dieser Wahrheit näher zu kommen"
  },
  AvgVideoCaption_100284_Content_103 = {
    Text = "Stimmt, Mr. Matthew?"
  },
  AvgVideoCaption_100284_Content_11 = {
    Text = "Wirklich?! Danke Ihnen!"
  },
  AvgVideoCaption_100284_Content_12 = {
    Text = "Es ist schon lange her, dass mich jemand wie Sie für meine Kunst gelobt hat..."
  },
  AvgVideoCaption_100284_Content_13 = {
    Text = "Herr Pickman, deine verrückte Kunstphilosophie und dein Wesen"
  },
  AvgVideoCaption_100284_Content_14 = {
    Text = "Das ist wirklich nicht geeignet für diese Branche"
  },
  AvgVideoCaption_100284_Content_15 = {
    Text = "Bitte zeichne schneller"
  },
  AvgVideoCaption_100284_Content_16 = {
    Text = "Beende dein langweiliges symbolistisches Spiel früher"
  },
  AvgVideoCaption_100284_Content_17 = {
    Text = "Symbolismus?"
  },
  AvgVideoCaption_100284_Content_18 = {
    Text = "Ich glaube, Sie haben sich geirrt, Mr. Matthew"
  },
  AvgVideoCaption_100284_Content_19 = {
    Text = "Ich lehne die Methode der Symbolik nicht ab"
  },
  AvgVideoCaption_100284_Content_2 = {
    Text = "Seltsam, wo ist der Pinsel...?"
  },
  AvgVideoCaption_100284_Content_20 = {
    Text = "Allerdings bin ich in der Kunst ein treuer Anhänger des Realismus"
  },
  AvgVideoCaption_100284_Content_21 = {
    Text = "Ach, du verstehst nicht einmal die grundlegenden Kunsttheorien"
  },
  AvgVideoCaption_100284_Content_22 = {
    Text = "Du hast eindeutig ... gemalt."
  },
  AvgVideoCaption_100284_Content_23 = {
    Text = "Gerade eben... hat das Bild an der Wand sich bewegt?"
  },
  AvgVideoCaption_100284_Content_24 = {
    Text = "Bitte nicht bewegen, Mr. Matthew"
  },
  AvgVideoCaption_100284_Content_25 = {
    Text = "Behalte die gerade angenehme Haltung bei"
  },
  AvgVideoCaption_100284_Content_26 = {
    Text = "Ich skizziere gerade für Sie"
  },
  AvgVideoCaption_100284_Content_27 = {
    Text = "Sehr gut, der Winkel der Klaue und des Bodens"
  },
  AvgVideoCaption_100284_Content_28 = {
    Text = "Welch wunderbare Perspektive"
  },
  AvgVideoCaption_100284_Content_29 = {
    Text = "Klaue?......"
  },
  AvgVideoCaption_100284_Content_3 = {
    Text = "Ah! Gefunden!"
  },
  AvgVideoCaption_100284_Content_30 = {
    Text = "Herr Pickman, ich fühle mich etwas unwohl..."
  },
  AvgVideoCaption_100284_Content_31 = {
    Text = "Große Kunst erfordert geduldiges Warten, Herr Matthew"
  },
  AvgVideoCaption_100284_Content_32 = {
    Text = "Linien, genau, diese tanzenden Linien"
  },
  AvgVideoCaption_100284_Content_33 = {
    Text = "Die Angst, die sich allmählich in Ihrem Gesicht verzerrt, ist so passend!"
  },
  AvgVideoCaption_100284_Content_34 = {
    Text = "Nein, ich muss hier weg..."
  },
  AvgVideoCaption_100284_Content_35 = {
    Text = "Was hast du mir angetan?!"
  },
  AvgVideoCaption_100284_Content_36 = {
    Text = "Ich? Sie haben sich geirrt, Mr. Matthew"
  },
  AvgVideoCaption_100284_Content_37 = {
    Text = "Ich habe Ihnen nie etwas angetan"
  },
  AvgVideoCaption_100284_Content_38 = {
    Text = "Ihr Körper möchte hier bleiben"
  },
  AvgVideoCaption_100284_Content_39 = {
    Text = "Möchten Sie dieses wunderbare Gemälde sehen"
  },
  AvgVideoCaption_100284_Content_4 = {
    Text = "Stimmt, Mr. Matthew"
  },
  AvgVideoCaption_100284_Content_40 = {
    Text = "Das... das ist...?"
  },
  AvgVideoCaption_100284_Content_41 = {
    Text = "Mein Körper!"
  },
  AvgVideoCaption_100284_Content_42 = {
    Text = "Sieh mal, wie schön die Hundezähne und Fledermausflügel sind!"
  },
  AvgVideoCaption_100284_Content_43 = {
    Text = "Sie nähern sich der wahren Kunst!"
  },
  AvgVideoCaption_100284_Content_44 = {
    Text = "Nein... Bitte nicht!"
  },
  AvgVideoCaption_100284_Content_45 = {
    Text = "Es ist schmerzhaft, oder?"
  },
  AvgVideoCaption_100284_Content_46 = {
    Text = "Schon gut, schon gut, Mr. Matthew"
  },
  AvgVideoCaption_100284_Content_47 = {
    Text = "Beim ersten Mal, als ich mich in einen Ghul verwandelte"
  },
  AvgVideoCaption_100284_Content_48 = {
    Text = "Ich habe auch diesen bis ins Mark dringenden Schmerz erlebt"
  },
  AvgVideoCaption_100284_Content_49 = {
    Text = "Dieser Schmerz eignet sich perfekt für dieses blutrote, aus Blut gefertigte"
  },
  AvgVideoCaption_100284_Content_5 = {
    Text = "Das ist die Pose, wie perfekt die Komposition ist!"
  },
  AvgVideoCaption_100284_Content_50 = {
    Text = "Sie haben mir einmal gesagt, dass Schmerz der ewige Antrieb der Kunst ist"
  },
  AvgVideoCaption_100284_Content_51 = {
    Text = "Sie sind mein Vertrauter, nicht wahr?"
  },
  AvgVideoCaption_100284_Content_52 = {
    Text = "Halte noch ein bisschen durch"
  },
  AvgVideoCaption_100284_Content_53 = {
    Text = "Ihr vollständiger Körper wird bald fertiggestellt sein...!"
  },
  AvgVideoCaption_100284_Content_54 = {
    Text = "Das... was ist das für ein Ort?!"
  },
  AvgVideoCaption_100284_Content_55 = {
    Text = "Dies ist der Ort von Wahnsinn und Wildheit, der Tempel der höchsten Kunst"
  },
  AvgVideoCaption_100284_Content_56 = {
    Text = "Willkommen in der Königsstadt der Ghule, Mr. Matthew!"
  },
  AvgVideoCaption_100284_Content_57 = {
    Text = "Ghul... Königsstadt..."
  },
  AvgVideoCaption_100284_Content_58 = {
    Text = "Sieh mal, die Gäste, die fröhlich trinken und essen"
  },
  AvgVideoCaption_100284_Content_59 = {
    Text = "Die Bewohner, die ihre Tanzpartner fressen"
  },
  AvgVideoCaption_100284_Content_6 = {
    Text = "Lass uns anfangen!"
  },
  AvgVideoCaption_100284_Content_60 = {
    Text = "Diese barbarische Szenerie wird der perfekte Hintergrund für unser Gemälde sein"
  },
  AvgVideoCaption_100284_Content_61 = {
    Text = "Hör auf... Pickman... ich kann nicht..."
  },
  AvgVideoCaption_100284_Content_62 = {
    Text = "Die wahre Kunst zu verstehen, das ist Ihr sehnlichster Wunsch"
  },
  AvgVideoCaption_100284_Content_63 = {
    Text = "Wie könnte ich es über mein Herz bringen, Ihr edles Streben zu zerstören?"
  },
  AvgVideoCaption_100284_Content_64 = {
    Text = "Als ich zum ersten Mal hierher kam"
  },
  AvgVideoCaption_100284_Content_65 = {
    Text = "Ich habe die große Tradition der Ghule miterlebt"
  },
  AvgVideoCaption_100284_Content_66 = {
    Text = "Komm, Mr. Matthew!"
  },
  AvgVideoCaption_100284_Content_67 = {
    Text = "Ich verspreche dir, das wird ein unvergessliches Kunstfest für dich sein!"
  },
  AvgVideoCaption_100284_Content_68 = {
    Text = "Das... was ist das..."
  },
  AvgVideoCaption_100284_Content_69 = {
    Text = "Entferne diese fauligen Leichen!"
  },
  AvgVideoCaption_100284_Content_7 = {
    Text = "Ich bereue es jetzt ein wenig..."
  },
  AvgVideoCaption_100284_Content_70 = {
    Text = "Wollen Sie nicht, Mr. Matthew?"
  },
  AvgVideoCaption_100284_Content_71 = {
    Text = "Ich... Ich..."
  },
  AvgVideoCaption_100284_Content_72 = {
    Text = "Stimmt, Sie haben es bestimmt auch gespürt!"
  },
  AvgVideoCaption_100284_Content_73 = {
    Text = "Der verborgene Drang zu beißen und zu verschlingen, der in mir steckt!"
  },
  AvgVideoCaption_100284_Content_74 = {
    Text = "Der Drang, der zu den Ghule gehört!"
  },
  AvgVideoCaption_100284_Content_75 = {
    Text = "Es ist ein Sturm, der dein menschliches Inneres zerstört"
  },
  AvgVideoCaption_100284_Content_76 = {
    Text = "Ich gebe dir eine wilde, freie Welt zurück"
  },
  AvgVideoCaption_100284_Content_77 = {
    Text = "Weg... ich muss hier weg! Lass mich raus, Pickman!"
  },
  AvgVideoCaption_100284_Content_78 = {
    Text = "Probiere sie, Mr. Matthew"
  },
  AvgVideoCaption_100284_Content_79 = {
    Text = "Schmerz, Wahnsinn, Erinnerung, Hunger, Verlangen, Umkehrung..."
  },
  AvgVideoCaption_100284_Content_8 = {
    Text = "Das Geld, das du mir als Model zahlst, ist wahrscheinlich etwas zu wenig"
  },
  AvgVideoCaption_100284_Content_80 = {
    Text = "Welch wunderbarer Ausdruck, welch wunderbare Pose!"
  },
  AvgVideoCaption_100284_Content_81 = {
    Text = "Jetzt lass mich den letzten Pinselstrich für dieses Bild setzen..."
  },
  AvgVideoCaption_100284_Content_82 = {
    Text = "Nein... Ich will das nicht..."
  },
  AvgVideoCaption_100284_Content_83 = {
    Text = "Gib, gib mir... die Leiche!"
  },
  AvgVideoCaption_100284_Content_84 = {
    Text = "Leiche... Ghul... weg, weg?"
  },
  AvgVideoCaption_100284_Content_85 = {
    Text = "Entschuldigung, Mr. Matthew"
  },
  AvgVideoCaption_100284_Content_86 = {
    Text = "Meine Bilder ziehen die Menschen oft hinein"
  },
  AvgVideoCaption_100284_Content_87 = {
    Text = "Es fällt mir selbst schwer, das zu kontrollieren"
  },
  AvgVideoCaption_100284_Content_88 = {
    Text = "Also, war das gerade alles... eine Illusion?"
  },
  AvgVideoCaption_100284_Content_89 = {
    Text = "Ich bin nicht verletzt und bin nicht geworden..."
  },
  AvgVideoCaption_100284_Content_9 = {
    Text = "Diese überwältigenden Ghul-Gemälde"
  },
  AvgVideoCaption_100284_Content_90 = {
    Text = "Ich habe immer großen Respekt vor Modellen, wie könnte ich es über mein Herz bringen, ihnen weh zu tun?"
  },
  AvgVideoCaption_100284_Content_91 = {
    Text = "Diese Illusionen könnten Sie beunruhigen"
  },
  AvgVideoCaption_100284_Content_92 = {
    Text = "Aber glaub mir, es ist es wert"
  },
  AvgVideoCaption_100284_Content_93 = {
    Text = "Schau mal, Mr. Matthew!"
  },
  AvgVideoCaption_100284_Content_94 = {
    Text = "Das ist ein Gemälde, das wir gemeinsam vollendet haben"
  },
  AvgVideoCaption_100284_Content_95 = {
    Text = "Das ist... ein unvollständiger Ghul..."
  },
  AvgVideoCaption_100284_Content_96 = {
    Text = "Im Königsschloss schreien......"
  },
  AvgVideoCaption_100284_Content_97 = {
    Text = "So wahnsinnig... so... gierig..."
  },
  AvgVideoCaption_100284_Content_98 = {
    Text = "Heute ist ein so schöner Tag!"
  },
  AvgVideoCaption_100284_Content_99 = {
    Text = "Ich habe einen Freund gewonnen, und Sie haben die wahre Kunst gesehen"
  },
  AvgVideoCaption_117618_Content_1 = {
    Text = "Unbefugtes Entkommen, Widerstand gegen die Verfolgung, das Töten von Lichtwachen"
  },
  AvgVideoCaption_117618_Content_10 = {
    Text = "Pollux möchte nur die Welt da draußen sehen!"
  },
  AvgVideoCaption_117618_Content_100 = {
    Text = "So viele Worte, habe ich so viel geschrieben?"
  },
  AvgVideoCaption_117618_Content_101 = {
    Text = "Was ist das...?"
  },
  AvgVideoCaption_117618_Content_102 = {
    Text = "Castor... wer ist das?"
  },
  AvgVideoCaption_117618_Content_103 = {
    Text = "Diese Worte, warum können sie nicht klar gelesen werden..."
  },
  AvgVideoCaption_117618_Content_104 = {
    Text = "So traurig, warum fühle ich mich plötzlich wie weinen..."
  },
  AvgVideoCaption_117618_Content_105 = {
    Text = "Gut, Pollux"
  },
  AvgVideoCaption_117618_Content_106 = {
    Text = "Heute wirst du mir folgen und die heiligen Taten des Lichtträgers ernsthaft rezitieren"
  },
  AvgVideoCaption_117618_Content_107 = {
    Text = "Mit Hingabe Sein Licht und Seine Barmherzigkeit erfahren"
  },
  AvgVideoCaption_117618_Content_108 = {
    Text = "Ja, Meister Laterne"
  },
  AvgVideoCaption_117618_Content_109 = {
    Text = "„Seine Seele kehrte von nun an ins unschuldige Heiligtum zurück,“"
  },
  AvgVideoCaption_117618_Content_11 = {
    Text = "Er hatte einfach zu viel Schmerz während des Verwandlungsrituals..."
  },
  AvgVideoCaption_117618_Content_110 = {
    Text = "„Aber Sein Blick schaut weiterhin liebevoll auf diese Welt.“"
  },
  AvgVideoCaption_117618_Content_111 = {
    Text = "„Seine Seele ist nun ins sündenfreie Reine Land zurückgekehrt,“"
  },
  AvgVideoCaption_117618_Content_112 = {
    Text = "„Aber Sein Blick schaut weiterhin liebevoll auf diese Welt.“"
  },
  AvgVideoCaption_117618_Content_113 = {
    Text = "„Er wird Blut, Fleisch und Knochen den Menschen schenken,“"
  },
  AvgVideoCaption_117618_Content_114 = {
    Text = "„Um die unschuldigen Seelen ins reine Land zu geleiten,“"
  },
  AvgVideoCaption_117618_Content_115 = {
    Text = "„Teile mit Ihm das reine Himmelreich.“"
  },
  AvgVideoCaption_117618_Content_116 = {
    Text = "„Er schenkt den Menschen Blut, Fleisch und Knochen.“"
  },
  AvgVideoCaption_117618_Content_117 = {
    Text = "„Um die unschuldigen Seelen ins reine Land zu geleiten,“"
  },
  AvgVideoCaption_117618_Content_118 = {
    Text = "„Die reine Himmelswelt mit Ihm teilen.“"
  },
  AvgVideoCaption_117618_Content_119 = {Text = "Husten..."},
  AvgVideoCaption_117618_Content_12 = {
    Text = "Senke nicht den Kopf, Bruder"
  },
  AvgVideoCaption_117618_Content_120 = {
    Text = "Hey, Sünder, es ist Zeit zu essen"
  },
  AvgVideoCaption_117618_Content_121 = {
    Text = "Wie geht es heute dem Heiligen Sohn Pollux?"
  },
  AvgVideoCaption_117618_Content_122 = {
    Text = "Der Heiliger Sohn ist natürlich sehr gut, er folgt heute auch ernsthaft dem Meister Latern und übt"
  },
  AvgVideoCaption_117618_Content_123 = {
    Text = "Aber was geht dich das an?"
  },
  AvgVideoCaption_117618_Content_124 = {
    Text = "Jeden Tag muss ich fragen, du bist doch nur ein..."
  },
  AvgVideoCaption_117618_Content_125 = {
    Text = "Was für ein Mensch war das nochmal?"
  },
  AvgVideoCaption_117618_Content_126 = {
    Text = "Es ist genug, wer im Sündenteich sein kann, ist natürlich auch nur ein Sünder"
  },
  AvgVideoCaption_117618_Content_127 = {
    Text = "Frag nicht mehr so viel über die Angelegenheiten des Heiligen Sohnes"
  },
  AvgVideoCaption_117618_Content_128 = {
    Text = "Warum erinnern sie sich nicht mehr an mich?"
  },
  AvgVideoCaption_117618_Content_129 = {
    Text = "Wurde die alte Laterne durch einen neuen Wick ersetzt?"
  },
  AvgVideoCaption_117618_Content_13 = {
    Text = "Ich bin es, ich habe die Lichtwache angegriffen!"
  },
  AvgVideoCaption_117618_Content_130 = {
    Text = "Pollux... musst du auf mich warten..."
  },
  AvgVideoCaption_117618_Content_131 = {
    Text = "Egal wie lange ich durchhalten werde, ich werde warten, bis zu dem Tag, an dem wir uns wiedersehen..."
  },
  AvgVideoCaption_117618_Content_14 = {
    Text = "Wenn du mich bestrafen willst, dann tu es bitte! Nein... nein!"
  },
  AvgVideoCaption_117618_Content_15 = {
    Text = "Halte durch, für die Freiheit"
  },
  AvgVideoCaption_117618_Content_16 = {Text = "Ah—"},
  AvgVideoCaption_117618_Content_17 = {
    Text = "Pollux! Puh, hust..."
  },
  AvgVideoCaption_117618_Content_18 = {
    Text = "Oh, ich hätte fast vergessen, dass unser heiliger Sohn Castor gerade so schwer verletzt wurde"
  },
  AvgVideoCaption_117618_Content_19 = {
    Text = "Heilung? Nicht nötig, wirf Castor einfach in den „Sündenteich“"
  },
  AvgVideoCaption_117618_Content_2 = {
    Text = "Ist das das, was unser Heiliger Sohn der Kirche zurückgibt?"
  },
  AvgVideoCaption_117618_Content_20 = {
    Text = "Das Blut Gottes wird seine Sünden reinigen"
  },
  AvgVideoCaption_117618_Content_21 = {
    Text = "Lass ihn erst raus, wenn das Böse vollständig geflossen ist"
  },
  AvgVideoCaption_117618_Content_22 = {
    Text = "Bruder... Bruder..."
  },
  AvgVideoCaption_117618_Content_23 = {
    Text = "Gut, als Nächstes ist es an der Zeit, unseren Heiliger Sohn"
  },
  AvgVideoCaption_117618_Content_24 = {
    Text = "Lerne die Lehren des Lichtträgers gut auswendig"
  },
  AvgVideoCaption_117618_Content_25 = {
    Text = "Ab heute werde ich als Lehrer persönlich mit dir die Schrift verstehen"
  },
  AvgVideoCaption_117618_Content_26 = {
    Text = "Ungewöhnlich, dass Ismail von sich aus spricht."
  },
  AvgVideoCaption_117618_Content_27 = {
    Text = "Ich verstehe dich wirklich gut und bewundere deinen Mut"
  },
  AvgVideoCaption_117618_Content_28 = {
    Text = "Pollux, du bist wirklich ein kluges, braves Kind"
  },
  AvgVideoCaption_117618_Content_29 = {
    Text = "Nur diese Klugheit wurde nicht am richtigen Ort eingesetzt"
  },
  AvgVideoCaption_117618_Content_3 = {
    Text = "Sag mal, wessen Plan ist das alles?"
  },
  AvgVideoCaption_117618_Content_30 = {
    Text = "Stattdessen hast du dich vor der Mission des Dienstes an dem Lichtträger gedrückt"
  },
  AvgVideoCaption_117618_Content_31 = {
    Text = "In der Tat, diese Transformationsrituale haben dir große Schmerzen bereitet, nicht wahr?"
  },
  AvgVideoCaption_117618_Content_32 = {
    Text = "Der Lichtträger hat auf dem Weg des Lichtes ebenso unzählige Schmerzen erfahren"
  },
  AvgVideoCaption_117618_Content_33 = {
    Text = "Er hat sogar seinen eigenen Leib geopfert, um die Sünden der Menschheit zu reinigen"
  },
  AvgVideoCaption_117618_Content_34 = {
    Text = "Vielleicht kannst du noch nicht die Barmherzigkeit Ers zeigen, und das große Ziel der Hingabe nicht verstehen, das ist ganz normal"
  },
  AvgVideoCaption_117618_Content_35 = {
    Text = "Sterbliche, die versuchen, die Worte und Taten der Götter zu verstehen, sind stets voller Verwirrung und Schwäche"
  },
  AvgVideoCaption_117618_Content_36 = {
    Text = "Du brauchst nur mehr Lernen, Einsichten..."
  },
  AvgVideoCaption_117618_Content_37 = {
    Text = "Ach, um einen Schritt zurückzugehen, Castor ist immer noch schwer verletzt und in Lebensgefahr"
  },
  AvgVideoCaption_117618_Content_38 = {
    Text = "Um die Sünden deines Bruders bald zu reinigen"
  },
  AvgVideoCaption_117618_Content_39 = {
    Text = "Du musst auch schnell die Verantwortung des Heiligen Sohnes übernehmen"
  },
  AvgVideoCaption_117618_Content_4 = {Text = "Ja..."},
  AvgVideoCaption_117618_Content_40 = {
    Text = "...Entschuldigung, Herr Laterne, ich werde es lernen"
  },
  AvgVideoCaption_117618_Content_41 = {
    Text = "Gut, dann folge mir und rezitiere die heiligen Taten des Lichtträgers ernsthaft"
  },
  AvgVideoCaption_117618_Content_42 = {
    Text = "Nehmt euch die Zeit, Seine Lehren zu verstehen"
  },
  AvgVideoCaption_117618_Content_43 = {
    Text = "... ja, Herr Laterne"
  },
  AvgVideoCaption_117618_Content_44 = {
    Text = "„Er hält die unvergängliche Kerze und wandelt über die Dunkelheit der Erde.“"
  },
  AvgVideoCaption_117618_Content_45 = {
    Text = "„Er trägt die unvergängliche Kerze und wandelt über die Dunkelheit der Erde.“"
  },
  AvgVideoCaption_117618_Content_46 = {
    Text = "„Er blickte auf die vollkommene Sünde und ließ traurige Tränen fließen.“"
  },
  AvgVideoCaption_117618_Content_47 = {
    Text = "„Dann schnitt er das Fleisch auf und ließ schwarzes Blut fließen...“"
  },
  AvgVideoCaption_117618_Content_48 = {
    Text = "„Er blickte auf die ganze Sünde und ließ traurige Tränen fließen.“"
  },
  AvgVideoCaption_117618_Content_49 = {
    Text = "„Und so schnitt er das Fleisch auf und ließ schwarzes Blut fließen...“"
  },
  AvgVideoCaption_117618_Content_5 = {Text = "Es bin ich"},
  AvgVideoCaption_117618_Content_50 = {
    Text = "Ah! Bruder! Warum hast du dir den Arm aufgerissen!"
  },
  AvgVideoCaption_117618_Content_51 = {
    Text = "Es ist alles meine Schuld, ich kann dich nicht beim Umbau-Ritual ersetzen"
  },
  AvgVideoCaption_117618_Content_52 = {
    Text = "Lass mich zumindest den gleichen Schmerz erleben wie du..."
  },
  AvgVideoCaption_117618_Content_53 = {Text = "Bruder!"},
  AvgVideoCaption_117618_Content_54 = {
    Text = "Ugh...Verdammtes, mein Kopf tut weh..."
  },
  AvgVideoCaption_117618_Content_55 = {
    Text = "Diese Frau hat mir bestimmt etwas angetan"
  },
  AvgVideoCaption_117618_Content_56 = {
    Text = "Das Gesicht meines Bruders in meinem Kopf – warum wird es plötzlich so verschwommen?"
  },
  AvgVideoCaption_117618_Content_57 = {
    Text = "Schreibe es auf, erinnere dich... nein, nicht auf Papier, das wird entdeckt werden..."
  },
  AvgVideoCaption_117618_Content_58 = {
    Text = "Ja, schreib es auf, ritze es an einem versteckten Ort ein..."
  },
  AvgVideoCaption_117618_Content_59 = {
    Text = "Es ist direkt unter dem Bett! Sie werden es hier nicht finden..."
  },
  AvgVideoCaption_117618_Content_6 = {
    Text = "Sie sollten wissen, dass ein so begriffsstutziger Kerl wie Castor solche Gedanken nicht haben würde"
  },
  AvgVideoCaption_117618_Content_60 = {
    Text = "Schreibe alles auf, was wir seit unserer Geburt erlebt haben, sowie die Fluchtpläne und die kleinen Erkundungsrouten!"
  },
  AvgVideoCaption_117618_Content_61 = {
    Text = "Du wirst meinen Willen nicht brechen!"
  },
  AvgVideoCaption_117618_Content_62 = {
    Text = "Warte auf mich, Bruder, ich werde eine Chance finden, dich wieder mitzunehmen..."
  },
  AvgVideoCaption_117618_Content_63 = {
    Text = "Heute setzen wir das Gebet für die Heiligen Taten des Lichtträgers fort"
  },
  AvgVideoCaption_117618_Content_64 = {
    Text = "... ja, Herr Laterne"
  },
  AvgVideoCaption_117618_Content_65 = {
    Text = "„Sein Blut hat die Sünden weggenommen und die Sünden aller Menschen von ihren Seelen befreit.“"
  },
  AvgVideoCaption_117618_Content_66 = {
    Text = "„Sein Blut hat die Sünden weggenommen und die Sünden aller Menschen von der Seele befreit.“"
  },
  AvgVideoCaption_117618_Content_67 = {
    Text = "„Doch die Welt bleibt von endloser Dunkelheit umhüllt,“"
  },
  AvgVideoCaption_117618_Content_68 = {
    Text = "„Und so entzündete er mit diesem Licht seinen eigenen Körper...“"
  },
  AvgVideoCaption_117618_Content_69 = {
    Text = "„Aber die Welt bleibt von endloser Dunkelheit umhüllt,“"
  },
  AvgVideoCaption_117618_Content_7 = {
    Text = "Gut, sehr gut, die Vögel, die den Himmel anstreben, was für eine berührende Geschichte"
  },
  AvgVideoCaption_117618_Content_70 = {
    Text = "„Und so entzündete er mit diesem Licht seinen eigenen Körper...“"
  },
  AvgVideoCaption_117618_Content_71 = {
    Text = "Kerze? Woher hast du die genommen?"
  },
  AvgVideoCaption_117618_Content_72 = {
    Text = "Hehe, ich bin natürlich der Beste"
  },
  AvgVideoCaption_117618_Content_73 = {
    Text = "So können wir nachts heimlich in dieses handgeschriebene Manuskript schauen"
  },
  AvgVideoCaption_117618_Content_74 = {
    Text = "Wir verstecken uns, um nicht entdeckt zu werden..."
  },
  AvgVideoCaption_117618_Content_75 = {
    Text = "Ha... steh auf, wir müssen weiter schnitzen, unsere Erinnerungen schnitzen..."
  },
  AvgVideoCaption_117618_Content_76 = {
    Text = "Wo waren wir stehen geblieben, als wir zum ersten Mal heimlich geflogen sind"
  },
  AvgVideoCaption_117618_Content_77 = {
    Text = "Dann flog es weg... Wohin flog es dann?"
  },
  AvgVideoCaption_117618_Content_78 = {
    Text = "Pollux! Nutzloses Gehirn, denk nach, denk schnell nach"
  },
  AvgVideoCaption_117618_Content_79 = {
    Text = "Du darfst nicht vergessen! Du darfst auf keinen Fall..."
  },
  AvgVideoCaption_117618_Content_8 = {
    Text = "Wenn diese nutzlosen Dinge so störend sind, warum ziehen wir sie nicht einfach heraus?"
  },
  AvgVideoCaption_117618_Content_80 = {
    Text = "Heute setzen wir das Rezitieren der heiligen Taten des Lichtträgers fort"
  },
  AvgVideoCaption_117618_Content_81 = {
    Text = "Es ist ... der Laterne-Majestät"
  },
  AvgVideoCaption_117618_Content_82 = {
    Text = "„Großartiges Licht bricht aus seinem Körper hervor,“"
  },
  AvgVideoCaption_117618_Content_83 = {
    Text = "„Sein Fleisch und seine Knochen werden im Feuer zu reinem Silber geformt.“"
  },
  AvgVideoCaption_117618_Content_84 = {
    Text = "„Großartiges Licht bricht aus seinem Körper hervor,“"
  },
  AvgVideoCaption_117618_Content_85 = {
    Text = "„Sein Fleisch und seine Knochen formen sich im Feuer zu reinem Silber.“"
  },
  AvgVideoCaption_117618_Content_86 = {
    Text = "„Er nahm das silberne Fleisch und die Knochen wieder ab,“"
  },
  AvgVideoCaption_117618_Content_87 = {
    Text = "„Geschenke an die Gerechten dieser Welt, um ihre Sünden zu begleichen...“"
  },
  AvgVideoCaption_117618_Content_88 = {
    Text = "„Er nahm das silberne Fleisch und die Knochen wieder ab,“"
  },
  AvgVideoCaption_117618_Content_89 = {
    Text = "„Gesegnet seien die Gerechten auf Erden, zur Rückzahlung ihrer Sünden...“"
  },
  AvgVideoCaption_117618_Content_9 = {
    Text = "Was... warte! Herr Laterne! Bitte überlegen Sie es sich noch einmal!"
  },
  AvgVideoCaption_117618_Content_90 = {
    Text = "Pollux! Du hast so viel Blut verloren..."
  },
  AvgVideoCaption_117618_Content_91 = {
    Text = "Wie wäre es, wenn wir mit ihnen zurückgehen..."
  },
  AvgVideoCaption_117618_Content_92 = {
    Text = "Nein... Lauf schnell, halte nicht an! Wenn wir zurückgehen, werden wir nur noch mehr verlieren..."
  },
  AvgVideoCaption_117618_Content_93 = {
    Text = "Pollux... Pollux..."
  },
  AvgVideoCaption_117618_Content_94 = {Text = "Ah..."},
  AvgVideoCaption_117618_Content_95 = {
    Text = "Was soll ich tun...?"
  },
  AvgVideoCaption_117618_Content_96 = {
    Text = "Ja, ich muss aufstehen, ich muss mir etwas merken..."
  },
  AvgVideoCaption_117618_Content_97 = {
    Text = "Wo war das ursprünglich vermerkt?"
  },
  AvgVideoCaption_117618_Content_98 = {
    Text = "Nicht hier, nicht hier..."
  },
  AvgVideoCaption_117618_Content_99 = {
    Text = "Stimmt, stimmt, unter dem Bett..."
  },
  AvgVideoCaption_117956_Content_1 = {
    Text = "Lass mich sehen"
  },
  AvgVideoCaption_117956_Content_10 = {
    Text = "Hey! Kind, halt an!"
  },
  AvgVideoCaption_117956_Content_100 = {
    Text = "Es ist kein Wind, aber es ist leicht, sehr nah, immer näher"
  },
  AvgVideoCaption_117956_Content_101 = {
    Text = "Es ist, als würde jemand mit seinem Körper langsam zu deiner Tür kriechen"
  },
  AvgVideoCaption_117956_Content_102 = {
    Text = "Dongdong. Jemand klopft an deine Tür!"
  },
  AvgVideoCaption_117956_Content_103 = {
    Text = "Du ziehst dich erschrocken in die Decke zurück, zitterst am ganzen Körper und tust so, als wärst du nicht da"
  },
  AvgVideoCaption_117956_Content_104 = {
    Text = "Bald verstummte das Klopfen an der Tür"
  },
  AvgVideoCaption_117956_Content_105 = {
    Text = "Im Raum herrscht nur Stille, so still, dass es dir unbehaglich wird"
  },
  AvgVideoCaption_117956_Content_106 = {
    Text = "Du kannst nicht anders, als durch die Lücke deiner Decke nach draußen zu schauen..."
  },
  AvgVideoCaption_117956_Content_107 = {
    Text = "Die Tür hat sich einen Spalt geöffnet!"
  },
  AvgVideoCaption_117956_Content_108 = {
    Text = "Du senkst den Kopf, ein Schatten, der schwärzer ist als die Dunkelheit, steht direkt neben deinem Bett!"
  },
  AvgVideoCaption_117956_Content_109 = {
    Text = "Du möchtest schreien, aber es ist bereits zu spät"
  },
  AvgVideoCaption_117956_Content_11 = {
    Text = "Ähm, gib mir ein bisschen von den Kürbiskonfekten, die ihr gerade genommen habt!"
  },
  AvgVideoCaption_117956_Content_110 = {
    Text = "Eddies kalte Hände, die wie Eiszapfen sind, haben bereits deinen Knöchel ergriffen"
  },
  AvgVideoCaption_117956_Content_111 = {
    Text = "Er stürzte auf dich zu, so schnell wie ein schwarzes Blitz!"
  },
  AvgVideoCaption_117956_Content_112 = {
    Text = "Du riechst es! Den Geruch von Staub und Schimmel"
  },
  AvgVideoCaption_117956_Content_113 = {
    Text = "Es gibt einen Hauch von süßem, ekelhaftem Zuckergeschmack!"
  },
  AvgVideoCaption_117956_Content_114 = {
    Text = "Eddys Hände schnellen plötzlich zu dem Ort, wo du die Süßigkeiten versteckt hast!"
  },
  AvgVideoCaption_117956_Content_115 = {
    Text = "Unter dem Kissen! Im Rucksack! Egal, wie gut du dich versteckst!"
  },
  AvgVideoCaption_117956_Content_116 = {
    Text = "Klak, Schmatz, er isst! Verrückt essen!"
  },
  AvgVideoCaption_117956_Content_117 = {
    Text = "Deine Schokolade! Dein Gummibärchen! Dein Lollipop!"
  },
  AvgVideoCaption_117956_Content_118 = {
    Text = "Keiner wird verschont! Das Geräusch ist wie das Zerkauen von Knochen!"
  },
  AvgVideoCaption_117956_Content_119 = {
    Text = "Glaubst du, er wird gehen, nachdem er die Süßigkeiten gegessen hat?"
  },
  AvgVideoCaption_117956_Content_12 = {
    Text = "Warum? Wegen meiner edlen..."
  },
  AvgVideoCaption_117956_Content_120 = {
    Text = "Nein, sein Hunger und Durst... sind gerade erst geweckt worden!"
  },
  AvgVideoCaption_117956_Content_121 = {
    Text = "„Nicht genug, nicht genug... ich will es süßer, am süßesten...“"
  },
  AvgVideoCaption_117956_Content_122 = {
    Text = "Eddys gieriger Blick heftete sich auf dich"
  },
  AvgVideoCaption_117956_Content_123 = {
    Text = "Die kalte Hand, klebrig von Sirup, streckte sich nach deinem Gesicht aus!"
  },
  AvgVideoCaption_117956_Content_124 = {
    Text = "Seine Finger berührten dein Augenlid, puff!"
  },
  AvgVideoCaption_117956_Content_125 = {
    Text = "Er nahm das, was ihm am meisten wie ein Bonbon vorkam, rund und warm..."
  },
  AvgVideoCaption_117956_Content_126 = {
    Text = "Deine Augen!"
  },
  AvgVideoCaption_117956_Content_127 = {
    Text = "Dann...... Klatsch, Gluck!"
  },
  AvgVideoCaption_117956_Content_128 = {
    Text = "Er fand den „Honig“, den er für den süßesten hielt."
  },
  AvgVideoCaption_117956_Content_129 = {
    Text = "Es ist in deinem Schädel versteckt..."
  },
  AvgVideoCaption_117956_Content_13 = {
    Text = "Hey! Geht nicht weg! Unhöfliche kleine Teufel!!"
  },
  AvgVideoCaption_117956_Content_130 = {
    Text = "Am nächsten Morgen werden die Leute dich entdecken"
  },
  AvgVideoCaption_117956_Content_131 = {
    Text = "An der Stelle, wo sich ursprünglich deine Augen befanden, bleiben nur zwei leere schwarze Höhlen zurück"
  },
  AvgVideoCaption_117956_Content_132 = {
    Text = "Neben deinem Kissen liegen glänzende, sauber geleckte Bonbonpapierchen verstreut"
  },
  AvgVideoCaption_117956_Content_133 = {
    Text = "und all die Süßigkeiten, die du im Raum versteckt hast"
  },
  AvgVideoCaption_117956_Content_134 = {
    Text = "Alles ist verschwunden, kein einziges bleibt zurück"
  },
  AvgVideoCaption_117956_Content_135 = {
    Text = "Also, heute Abend, wenn ihr mit vollen Bonbongläsern umarmt"
  },
  AvgVideoCaption_117956_Content_136 = {
    Text = "zufrieden im Bett liegend"
  },
  AvgVideoCaption_117956_Content_137 = {
    Text = "Sei vorsichtig, Eddie hat dich heimlich ins Visier genommen..."
  },
  AvgVideoCaption_117956_Content_138 = {
    Text = "Tür abschließen? Zwecklos"
  },
  AvgVideoCaption_117956_Content_139 = {
    Text = "Gut versteckt, Süßigkeiten? Er kann es riechen!"
  },
  AvgVideoCaption_117956_Content_14 = {
    Text = "Verflucht, Kinder zu schlagen scheint kein Verhalten einer Dame zu sein, aber mein Kürbiskonfekt..."
  },
  AvgVideoCaption_117956_Content_140 = {
    Text = "Wie, hast du Angst"
  },
  AvgVideoCaption_117956_Content_141 = {
    Text = "Überlasst mir die Süßigkeiten... die Hexe!"
  },
  AvgVideoCaption_117956_Content_142 = {
    Text = "Die Bonbonhexe wird diese köstlichen Süßigkeiten für euch aufbewahren!"
  },
  AvgVideoCaption_117956_Content_143 = {
    Text = "Was ist eine Zuckermädchen-Hexe?"
  },
  AvgVideoCaption_117956_Content_144 = {
    Text = "Hast du den Hexenhut auf meinem Kopf nicht gesehen?"
  },
  AvgVideoCaption_117956_Content_145 = {
    Text = "Das ist kein Kostüm"
  },
  AvgVideoCaption_117956_Content_146 = {
    Text = "Sieh mal, sieh mal, das ist die Magie der Hexe!"
  },
  AvgVideoCaption_117956_Content_147 = {
    Text = "Keine Sorge, die Umarmung der Süßigkeitenhexe ist das beste Zuhause für alle Süßigkeiten!"
  },
  AvgVideoCaption_117956_Content_148 = {
    Text = "Was soll ich tun?"
  },
  AvgVideoCaption_117956_Content_149 = {
    Text = "Ich habe natürlich keine Angst vor Geistern, die gerechte Hexe wird ihn in die Flucht schlagen..."
  },
  AvgVideoCaption_117956_Content_15 = {
    Text = "Habe es! Egal, wenn ich sie erschrecke, hehe..."
  },
  AvgVideoCaption_117956_Content_150 = {
    Text = "Hm? Wer von euch hat ständig meine Knöchel berührt? Wisst ihr nicht, dass das unhöflich ist?"
  },
  AvgVideoCaption_117956_Content_151 = {Text = "Niemand?"},
  AvgVideoCaption_117956_Content_152 = {
    Text = "Wie kann das sein? Ich habe doch gerade..."
  },
  AvgVideoCaption_117956_Content_153 = {
    Text = "Wer macht einen Streich? Das ist nicht lustig!"
  },
  AvgVideoCaption_117956_Content_154 = {
    Text = "Warte, was schaut ihr da?"
  },
  AvgVideoCaption_117956_Content_155 = {
    Text = "Ist da ein Schatten hinter mir? Wo? Es ist niemand da?"
  },
  AvgVideoCaption_117956_Content_156 = {
    Text = "Wie rieche ich den Geruch von Staub und alten Kleidern..."
  },
  AvgVideoCaption_117956_Content_157 = {
    Text = "Nein, das ist unmöglich, das habe ich doch erfunden..."
  },
  AvgVideoCaption_117956_Content_158 = {
    Text = "Worüber lacht ihr? Was ist daran lustig? Ah!!!"
  },
  AvgVideoCaption_117956_Content_159 = {
    Text = "Ich kann nichts mehr sehen! Meine Augen, wer?!"
  },
  AvgVideoCaption_117956_Content_16 = {
    Text = "Warte, auch wenn ihr gierig, geizig und rücksichtslos seid"
  },
  AvgVideoCaption_117956_Content_160 = {
    Text = "Lass mich los!! Hilfe—"
  },
  AvgVideoCaption_117956_Content_161 = {
    Text = "Jenkins?! Kleine Maus?!"
  },
  AvgVideoCaption_117956_Content_162 = {
    Text = "Wann seid ihr gekommen?"
  },
  AvgVideoCaption_117956_Content_163 = {
    Text = "Gut, ihr habt mich gerade verarscht!"
  },
  AvgVideoCaption_117956_Content_164 = {
    Text = "Ich, ich habe keine Angst vor Geistern"
  },
  AvgVideoCaption_117956_Content_165 = {
    Text = "Halt den Mund! Kein Lachen!!"
  },
  AvgVideoCaption_117956_Content_166 = {
    Text = "Ahhhh, verdammte Maus!!!"
  },
  AvgVideoCaption_117956_Content_167 = {
    Text = "Lauf nicht weg, ich habe noch eine Rechnung mit euch offen!!!"
  },
  AvgVideoCaption_117956_Content_17 = {
    Text = "Habt ihr etwa keine Angst, dass der Bonbongeist euch verfolgt?"
  },
  AvgVideoCaption_117956_Content_18 = {
    Text = "Was ist der Zuckergeist?"
  },
  AvgVideoCaption_117956_Content_19 = {
    Text = "Hmhm, schnupper mal genau"
  },
  AvgVideoCaption_117956_Content_2 = {
    Text = "Auf dem Plakat zum Fest der Heiligen steht der letzte Ort für die Süßigkeitenverteilung..."
  },
  AvgVideoCaption_117956_Content_20 = {
    Text = "Neben dem Duft von Toffee in der Luft"
  },
  AvgVideoCaption_117956_Content_21 = {
    Text = "Gibt es einen Geruch, der nach Staub, alten Kleidern und einem Hauch von Schimmel riecht..."
  },
  AvgVideoCaption_117956_Content_22 = {
    Text = "Ja, so ist es, komm näher"
  },
  AvgVideoCaption_117956_Content_23 = {
    Text = "Ihr müsst eure Ohren spitzen und genau zuhören"
  },
  AvgVideoCaption_117956_Content_24 = {
    Text = "Die Geschichte dieses hungrigen Untoten..."
  },
  AvgVideoCaption_117956_Content_25 = {
    Text = "Vor langer, langer Zeit——"
  },
  AvgVideoCaption_117956_Content_26 = {
    Text = "Als eure Ur-Ur-Großväter noch kleine Jungen waren"
  },
  AvgVideoCaption_117956_Content_27 = {
    Text = "Auf dem Land von Misaq gab es einmal jemanden namens Eddie..."
  },
  AvgVideoCaption_117956_Content_28 = {
    Text = "Ja, der Schüler von Eddie Hope"
  },
  AvgVideoCaption_117956_Content_29 = {
    Text = "Armer Eddie ist ein schwacher Junge"
  },
  AvgVideoCaption_117956_Content_3 = {
    Text = "Genau hier!"
  },
  AvgVideoCaption_117956_Content_30 = {
    Text = "Die alte Schuluniform hängt leer an ihm"
  },
  AvgVideoCaption_117956_Content_31 = {
    Text = "Wie ein Vogelscheuche, die aus dürren Ästen auf den Feldern hängt"
  },
  AvgVideoCaption_117956_Content_32 = {
    Text = "Warum ist er so dünn?"
  },
  AvgVideoCaption_117956_Content_33 = {
    Text = "Äh, weil Eddie ein Waisenkind ist"
  },
  AvgVideoCaption_117956_Content_34 = {
    Text = "Und zu dieser Zeit war Mythag sicherlich klein und arm, es war ganz normal, dass die Leute nicht genug zu essen hatten!"
  },
  AvgVideoCaption_117956_Content_35 = {
    Text = "Das ist alles nicht wichtig, jedenfalls..."
  },
  AvgVideoCaption_117956_Content_36 = {
    Text = "Eddie spricht nicht gerne, er ist immer allein und geht alleine auf die gefährlichen Außeneinsätze"
  },
  AvgVideoCaption_117956_Content_37 = {
    Text = "Leider hat er sich bald mit einer schrecklichen Krankheit angesteckt"
  },
  AvgVideoCaption_117956_Content_38 = {
    Text = "Sein Fleisch wurde allmählich von schwarzem Schleim zerfressen, und in seinem Gesicht erschienen immer mehr Löcher"
  },
  AvgVideoCaption_117956_Content_39 = {
    Text = "Manchmal, wenn man nicht aufpasst, Platsch"
  },
  AvgVideoCaption_117956_Content_4 = {
    Text = "Was? Wie kommt es, dass es schon wieder eine Gruppe Kinder gibt"
  },
  AvgVideoCaption_117956_Content_40 = {
    Text = "Ein Stück Gesichtshaut wird einfach so abfallen und schlaff an seinem Gesicht hängen..."
  },
  AvgVideoCaption_117956_Content_41 = {
    Text = "Nicht nur das, er stellte fest, dass er nach und nach von den Menschen um ihn herum vergessen wurde"
  },
  AvgVideoCaption_117956_Content_42 = {
    Text = "Niemand erinnert sich an dieses Wohnheim"
  },
  AvgVideoCaption_117956_Content_43 = {
    Text = "Und da ist ein armer Wicht, der im Bett liegt"
  },
  AvgVideoCaption_117956_Content_44 = {
    Text = "Endlich hat Eddie nicht einmal mehr die Kraft zu essen"
  },
  AvgVideoCaption_117956_Content_45 = {
    Text = "Ich habe nicht einmal die Kraft, Wasser zu trinken"
  },
  AvgVideoCaption_117956_Content_46 = {
    Text = "Er ist so hungrig, dass sein Bauch an seinem Rücken klebt, und sein Hals ist so trocken wie Feuer"
  },
  AvgVideoCaption_117956_Content_47 = {
    Text = "konnte jedoch nur auf dem Bett klagend aufschreien"
  },
  AvgVideoCaption_117956_Content_48 = {
    Text = "Was hat diese Geschichte mit dem Zuckergeist zu tun?"
  },
  AvgVideoCaption_117956_Content_49 = {
    Text = "Keine Eile, hör einfach ehrlich zu, dann wirst du es wissen"
  },
  AvgVideoCaption_117956_Content_5 = {
    Text = "Gibt es normalerweise so viele Angehörige an der Misaq Universität?"
  },
  AvgVideoCaption_117956_Content_50 = {
    Text = "In der Nacht des Allerheiligentages"
  },
  AvgVideoCaption_117956_Content_51 = {
    Text = "Er hörte plötzlich ein verschwommenes Lachen von unten"
  },
  AvgVideoCaption_117956_Content_52 = {
    Text = "Die Kinder rufen: „Süßes oder Saures“"
  },
  AvgVideoCaption_117956_Content_53 = {
    Text = "Einer nach dem anderen lief unter seinem Fenster vorbei"
  },
  AvgVideoCaption_117956_Content_54 = {
    Text = "Das herzliche Lachen, der schwache Duft von Toffee"
  },
  AvgVideoCaption_117956_Content_55 = {
    Text = "Wie eine böse Klaue, die an seiner Brust kratzt und gräbt"
  },
  AvgVideoCaption_117956_Content_56 = {
    Text = "Warum, warum wurde ich vergessen?"
  },
  AvgVideoCaption_117956_Content_57 = {
    Text = "Warum kümmert sich niemand um mich?"
  },
  AvgVideoCaption_117956_Content_58 = {
    Text = "Die vergessene Angst und die Schmerzen der Krankheit quälen ihn"
  },
  AvgVideoCaption_117956_Content_59 = {
    Text = "Plötzlich überwältigte ihn ein gewaltiges Verlangen vollständig"
  },
  AvgVideoCaption_117956_Content_6 = {
    Text = "Schnell, schnell..."
  },
  AvgVideoCaption_117956_Content_60 = {
    Text = "Er traf eine Entscheidung, eine wahnsinnige Entscheidung, eine verzweifelte Entscheidung"
  },
  AvgVideoCaption_117956_Content_61 = {
    Text = "Er will ein Stück Süßigkeit suchen! Nur ein Stück!"
  },
  AvgVideoCaption_117956_Content_62 = {
    Text = "Wenn er in dieser Nacht sterben sollte, dann muss er in der süßen Erinnerung sterben"
  },
  AvgVideoCaption_117956_Content_63 = {
    Text = "Eddie kämpfte mit all seiner Kraft, um aus dem Bett zu krabbeln, während er mit beiden Händen den Boden abstützte"
  },
  AvgVideoCaption_117956_Content_64 = {
    Text = "Ein wenig, ein wenig nach vorne bewegen..."
  },
  AvgVideoCaption_117956_Content_65 = {
    Text = "Er öffnete die dünne Tür"
  },
  AvgVideoCaption_117956_Content_66 = {
    Text = "Wie ein Schatten gleitet es langsam die dunkle, kalte Treppe hinunter"
  },
  AvgVideoCaption_117956_Content_67 = {
    Text = "Er klettert und klettert"
  },
  AvgVideoCaption_117956_Content_68 = {
    Text = "Aber er ist zu schwach, zu kalt"
  },
  AvgVideoCaption_117956_Content_69 = {
    Text = "Als er den Eingang zum Wohnheim erreicht, hat er keine Kraft mehr, um die große Tür zu öffnen"
  },
  AvgVideoCaption_117956_Content_7 = {
    Text = "Ah!! Der Süßigkeitenkorb ist wirklich leer"
  },
  AvgVideoCaption_117956_Content_70 = {
    Text = "„Wer kann... mir helfen... wer kann... gib mir eine Süßigkeit...“"
  },
  AvgVideoCaption_117956_Content_71 = {
    Text = "Niemand hörte seine Stimme, niemand sah sein Erscheinungsbild"
  },
  AvgVideoCaption_117956_Content_72 = {
    Text = "Mit einem Quietschen schoben die fröhlichen Schüler die Tür des Schlafheims auf"
  },
  AvgVideoCaption_117956_Content_73 = {
    Text = "Und dann traten unzählige Schuhe auf ihn"
  },
  AvgVideoCaption_117956_Content_74 = {
    Text = "Knack, das ist das Geräusch von Eddys gebrochenem Knochen"
  },
  AvgVideoCaption_117956_Content_75 = {
    Text = "Puff, das ist das Geräusch von Eddies Fleisch, das zertrampelt wird..."
  },
  AvgVideoCaption_117956_Content_76 = {
    Text = "Die verzweifelten Schreie wurden von frohen Lachen übertönt"
  },
  AvgVideoCaption_117956_Content_77 = {
    Text = "Bis er zu einem verschwommenen Fleck wurde, streckte die begehrende Hand weiterhin in Richtung der Tür aus..."
  },
  AvgVideoCaption_117956_Content_78 = {
    Text = "Er hat bis zu seinem Tod... die Süßigkeit im Traum nicht gekostet"
  },
  AvgVideoCaption_117956_Content_79 = {
    Text = "Eddie ist tot"
  },
  AvgVideoCaption_117956_Content_8 = {
    Text = "Diese nervigen kleinen Heuschrecken!"
  },
  AvgVideoCaption_117956_Content_80 = {
    Text = "Doch sein Hunger... das herzzerreißende Verlangen nach Süßigkeiten ist nicht gestorben"
  },
  AvgVideoCaption_117956_Content_81 = {
    Text = "Es blieb, klebrig wie Sirup, und schneidend wie der kalte Winterwind"
  },
  AvgVideoCaption_117956_Content_82 = {
    Text = "Jedes Jahr, wenn die Kürbislaterne leuchtet und die Luft voller Bonbonduft ist, Eddie..."
  },
  AvgVideoCaption_117956_Content_83 = {
    Text = "Oder anders gesagt, das Verlangen, das Eddie hinterlassen hat, wird erwachen"
  },
  AvgVideoCaption_117956_Content_84 = {
    Text = "Er ist nicht mehr der arme Junge"
  },
  AvgVideoCaption_117956_Content_85 = {
    Text = "Er verwandelte sich in etwas anderes, noch Schrecklicheres"
  },
  AvgVideoCaption_117956_Content_86 = {
    Text = "Im Schatten dieses Campus umherirren"
  },
  AvgVideoCaption_117956_Content_87 = {
    Text = "Er kann den Duft von Bonbons riechen!"
  },
  AvgVideoCaption_117956_Content_88 = {
    Text = "Besonders die Schätze, die ihr in den Körben, in den Fächern eurer Rucksäcke versteckt oder in den warmen Taschen versteckt habt!"
  },
  AvgVideoCaption_117956_Content_89 = {
    Text = "Am Abend von Allerheiligen, wenn du viele Süßigkeiten bei dir hast, wenn du nach Hause gehst"
  },
  AvgVideoCaption_117956_Content_9 = {
    Text = "Nein, die hier begrenzte seltsame Kürbissüßigkeit habe ich noch nicht probiert"
  },
  AvgVideoCaption_117956_Content_90 = {
    Text = "Du wirst ein kaltes Gefühl im Nacken spüren, hu... als ob jemand kalte Atemzüge über dich bläst"
  },
  AvgVideoCaption_117956_Content_91 = {
    Text = "Wenn du dich umdrehst, wirst du feststellen, dass nichts da ist"
  },
  AvgVideoCaption_117956_Content_92 = {
    Text = "Nur der Wind und seltsame Schatten..."
  },
  AvgVideoCaption_117956_Content_93 = {
    Text = "Nein, das ist Eddie, der dir folgt!"
  },
  AvgVideoCaption_117956_Content_94 = {
    Text = "Er wird dem Duft der Süßigkeiten folgen und ganz still hinter dir hergehen"
  },
  AvgVideoCaption_117956_Content_95 = {
    Text = "Du wirst nur einen schwachen, muffigen Geruch aus Staub und alten Kleidern riechen"
  },
  AvgVideoCaption_117956_Content_96 = {
    Text = "Bis Mitternacht! Wenn der Glockenturm zum zwölften Mal schlägt"
  },
  AvgVideoCaption_117956_Content_97 = {
    Text = "Auf dem Campus ist es sehr still, selbst die Eulen haben den Mund geschlossen"
  },
  AvgVideoCaption_117956_Content_98 = {
    Text = "In diesem Moment... wirst du ein seltsames Geräusch an deiner Tür hören"
  },
  AvgVideoCaption_117956_Content_99 = {
    Text = "Schwupp... Schwupp..."
  },
  AvgVideoCaption_122450_Content_1 = {
    Text = "Ausgang, der Ausgang ist dort..."
  },
  AvgVideoCaption_122450_Content_10 = {
    Text = "Jetzt lass das verzerrte Blut und die Knochen zu Schicksal verwoben werden"
  },
  AvgVideoCaption_122450_Content_11 = {
    Text = "Durch die falsche Nabelschnur"
  },
  AvgVideoCaption_122450_Content_12 = {
    Text = "Durch meine zerbrechliche Tür..."
  },
  AvgVideoCaption_122450_Content_13 = {
    Text = "Geburt dieser Welt!"
  },
  AvgVideoCaption_122450_Content_14 = {
    Text = "Sieh mal, er hat die Augen geöffnet!"
  },
  AvgVideoCaption_122450_Content_15 = {
    Text = "Umarme mich, mein Schatz"
  },
  AvgVideoCaption_122450_Content_16 = {Text = "Mein.."},
  AvgVideoCaption_122450_Content_17 = {
    Text = "Mein.. Vater"
  },
  AvgVideoCaption_122450_Content_18 = {
    Text = "Mein.. Vater"
  },
  AvgVideoCaption_122450_Content_19 = {
    Text = "Mein Schicksal"
  },
  AvgVideoCaption_122450_Content_2 = {
    Text = "Warum sollte ich gehen?"
  },
  AvgVideoCaption_122450_Content_3 = {
    Text = "Mach dir keine Sorgen, hier ist es sicher"
  },
  AvgVideoCaption_122450_Content_4 = {
    Text = "Tu das nicht... Ich möchte nicht die göttliche Mutter sein."
  },
  AvgVideoCaption_122450_Content_5 = {
    Text = "Ich bin die Tochter Gottes"
  },
  AvgVideoCaption_122450_Content_6 = {
    Text = "Niemand kann meinem Willen widersprechen"
  },
  AvgVideoCaption_122450_Content_7 = {
    Text = "Ich spüre es"
  },
  AvgVideoCaption_122450_Content_8 = {
    Text = "Dieser perfekte Schmerz"
  },
  AvgVideoCaption_122450_Content_9 = {
    Text = "und perfekte Reifung"
  },
  AvgVideoCaption_122705_Content_1 = {
    Text = "Das ist die Geschichte von sieben Tagen nach der Geburt des Gottes"
  },
  AvgVideoCaption_122705_Content_10 = {
    Text = "Aber auf allen Gesichtern strahlt die leidenschaftliche Freude"
  },
  AvgVideoCaption_122705_Content_100 = {
    Text = "Liegend auf meiner Brust"
  },
  AvgVideoCaption_122705_Content_101 = {
    Text = "Nur eine heuchlerische Statue"
  },
  AvgVideoCaption_122705_Content_102 = {
    Text = "Ein Haufen toter, fälschlicherweise als „Gott“ bezeichneter Fleischklumpen"
  },
  AvgVideoCaption_122705_Content_103 = {Text = "Warum?"},
  AvgVideoCaption_122705_Content_104 = {
    Text = "Warum will dieses verdrehte, ungerechte Schicksal mich nicht freigeben?"
  },
  AvgVideoCaption_122705_Content_105 = {
    Text = "Gott, warum bestrafst du mich immer?"
  },
  AvgVideoCaption_122705_Content_106 = {Text = "Gott...?"},
  AvgVideoCaption_122705_Content_107 = {
    Text = "Haha, haha, ich habe es verstanden!"
  },
  AvgVideoCaption_122705_Content_108 = {
    Text = "Das hätte ich früher erkennen sollen!"
  },
  AvgVideoCaption_122705_Content_109 = {
    Text = "Du bist überhaupt keine Göttin, oder?"
  },
  AvgVideoCaption_122705_Content_11 = {
    Text = "Sollte ich Freude empfinden?"
  },
  AvgVideoCaption_122705_Content_110 = {
    Text = "Wie könnte ein wahrer Gott zulassen, dass seine Gläubigen zu solchen Wahnsinnigen werden?"
  },
  AvgVideoCaption_122705_Content_111 = {
    Text = "Wie kann ein wahrer Gott ein Haufen von verunreinigtem, verrottetem Fleisch sein?"
  },
  AvgVideoCaption_122705_Content_112 = {
    Text = "Alle betrügen mich. Miryam, die sogenannten Götter..."
  },
  AvgVideoCaption_122705_Content_113 = {
    Text = "Alle sind Betrüger, alles ist eine Lüge"
  },
  AvgVideoCaption_122705_Content_114 = {
    Text = "Haha, ich habe so lange in einer Lüge gelebt"
  },
  AvgVideoCaption_122705_Content_115 = {
    Text = "Für dieses Stück verwestes Fleisch habe ich bereits so viel bezahlt..."
  },
  AvgVideoCaption_122705_Content_116 = {
    Text = "Schicksal, Schicksal, alles ist Illusion..."
  },
  AvgVideoCaption_122705_Content_117 = {
    Text = "Du Monster... Warum entscheidest du über meine Zukunft?"
  },
  AvgVideoCaption_122705_Content_118 = {
    Text = "Ich habe all dies nicht für dich gegeben!"
  },
  AvgVideoCaption_122705_Content_119 = {
    Text = "War es nie!"
  },
  AvgVideoCaption_122705_Content_12 = {
    Text = "Soll ich darüber jubeln?"
  },
  AvgVideoCaption_122705_Content_120 = {
    Text = "Verdammtes, ekelhaftes Monster!"
  },
  AvgVideoCaption_122705_Content_121 = {
    Text = "Wo ist das hier?"
  },
  AvgVideoCaption_122705_Content_122 = {
    Text = "Bin ich zurückgekehrt... an den Tag der Geburt des heiligen Embryos?..."
  },
  AvgVideoCaption_122705_Content_123 = {
    Text = "Braves Kind, du hast ein ehrenvolles Opfer gebracht..."
  },
  AvgVideoCaption_122705_Content_124 = {
    Text = "Haha, haha, ich bin zurück, ich bin wieder zurück!"
  },
  AvgVideoCaption_122705_Content_125 = {
    Text = "Ich kann nicht entkommen, ich kann nicht entkommen!"
  },
  AvgVideoCaption_122705_Content_126 = {
    Text = "Die Spur der Bewegung der Sterne ist längst am Himmel eingraviert"
  },
  AvgVideoCaption_122705_Content_127 = {
    Text = "Jeder Abzweigung führt in denselben Abgrund..."
  },
  AvgVideoCaption_122705_Content_128 = {
    Text = "Die sogenannte Wahl ist nur..."
  },
  AvgVideoCaption_122705_Content_129 = {
    Text = "Es ist nur das Drehbuch, das das Schicksal bereits geschrieben hat"
  },
  AvgVideoCaption_122705_Content_13 = {
    Text = "Ich bin mir auch nicht sicher"
  },
  AvgVideoCaption_122705_Content_130 = {
    Text = "Es ist nur eine selbstbetrügerische Improvisation!"
  },
  AvgVideoCaption_122705_Content_131 = {
    Text = "Gott, da du darauf bestehst, dieses absurde Stück nicht zu ändern..."
  },
  AvgVideoCaption_122705_Content_132 = {
    Text = "Dann kann ich dich nur selbst sehen lassen"
  },
  AvgVideoCaption_122705_Content_133 = {
    Text = "Alles, was du geplant hast"
  },
  AvgVideoCaption_122705_Content_134 = {
    Text = "Wie man zur Treppe wird, die mir Ehre bringt!"
  },
  AvgVideoCaption_122705_Content_14 = {
    Text = "Zweiter Tag nach der Geburt Gottes"
  },
  AvgVideoCaption_122705_Content_15 = {
    Text = "Die Göttliche Mutter wünscht die Taufe des Heiligen Embryos"
  },
  AvgVideoCaption_122705_Content_16 = {
    Text = "Möge mein Herr ihr Unhöflichkeit und Nachlässigkeit vergeben"
  },
  AvgVideoCaption_122705_Content_17 = {
    Text = "Ihr schmutzigen Diener, zieht euch zurück!"
  },
  AvgVideoCaption_122705_Content_18 = {
    Text = "Nur ich bin würdig, Sein wahres Antlitz zu sehen"
  },
  AvgVideoCaption_122705_Content_19 = {
    Text = "Ich wage es nicht, irgendjemandem die Geburt des „Gottes“ zu zeigen."
  },
  AvgVideoCaption_122705_Content_2 = {
    Text = "Tag eins nach der Geburt Gottes"
  },
  AvgVideoCaption_122705_Content_20 = {
    Text = "Der getaufte „Embryo“ ist ein Chaos aus Fleisch und Blut, dem der Geist und die Intelligenz fehlen"
  },
  AvgVideoCaption_122705_Content_21 = {
    Text = "Es muss daran liegen, dass ich noch nicht vollständig genug bin..."
  },
  AvgVideoCaption_122705_Content_22 = {
    Text = "Das darf niemand entdecken"
  },
  AvgVideoCaption_122705_Content_23 = {
    Text = "Mit der Zeit, wenn Gott auf meinen Ruf antwortet, wird alles gut werden"
  },
  AvgVideoCaption_122705_Content_24 = {
    Text = "Der dritte Tag nach der Geburt Gottes"
  },
  AvgVideoCaption_122705_Content_25 = {
    Text = "Heiliger Embryo hat die Augen noch nicht geöffnet"
  },
  AvgVideoCaption_122705_Content_26 = {
    Text = "Gott, wann wirst du endlich deine Augen öffnen?"
  },
  AvgVideoCaption_122705_Content_27 = {
    Text = "Du hast Miryam nicht versprochen"
  },
  AvgVideoCaption_122705_Content_28 = {
    Text = "Wird das Göttliche Reich, das sie wiederbeleben wird, zu ihr kommen?"
  },
  AvgVideoCaption_122705_Content_29 = {
    Text = "Tag vier nach der Geburt Gottes"
  },
  AvgVideoCaption_122705_Content_3 = {
    Text = "Der göttliche Embryo wird aus dem verkohlten Körper geboren"
  },
  AvgVideoCaption_122705_Content_30 = {
    Text = "Das Ritual des Gesprächs mit dem Gott findet heute in der Kirche statt"
  },
  AvgVideoCaption_122705_Content_31 = {
    Text = "Bitte verleiht uns die Ehre"
  },
  AvgVideoCaption_122705_Content_32 = {
    Text = "Die Koordinaten des Aufstiegs des Göttlichen Reiches für die Seefahrer offenbaren"
  },
  AvgVideoCaption_122705_Content_33 = {
    Text = "Wir werden Ihre Wiederbelebung und Ihr Erscheinen feierlich begrüßen"
  },
  AvgVideoCaption_122705_Content_34 = {
    Text = "Ich frage nach der Zukunft des Göttlichen Reiches"
  },
  AvgVideoCaption_122705_Content_35 = {
    Text = "Frage nach seiner Verbindung zu mir"
  },
  AvgVideoCaption_122705_Content_36 = {
    Text = "Frage mich nach allem, was ich wissen möchte"
  },
  AvgVideoCaption_122705_Content_37 = {
    Text = "und alles, was Miryam zu erkunden versucht"
  },
  AvgVideoCaption_122705_Content_38 = {
    Text = "Gott schweigt"
  },
  AvgVideoCaption_122705_Content_39 = {
    Text = "Der fünfte Tag der Geburt Gottes"
  },
  AvgVideoCaption_122705_Content_4 = {
    Text = "Der Moment des Ausrichtens, der Moment des Ausrichtens ist gekommen!"
  },
  AvgVideoCaption_122705_Content_40 = {
    Text = "Miryam fragte mich nach dem Ergebnis des Treffens mit den Göttern"
  },
  AvgVideoCaption_122705_Content_41 = {
    Text = "Wie ist es?"
  },
  AvgVideoCaption_122705_Content_42 = {
    Text = "Es sind schon zwei Tage vergangen..."
  },
  AvgVideoCaption_122705_Content_43 = {
    Text = "Mein Herr..."
  },
  AvgVideoCaption_122705_Content_44 = {
    Text = "Hast du seine Stimme gehört?"
  },
  AvgVideoCaption_122705_Content_45 = {
    Text = "Natürlich, natürlich habe ich es gehört!"
  },
  AvgVideoCaption_122705_Content_46 = {
    Text = "Dein Zweifel ist eine Respektlosigkeit gegenüber der Göttlichen Mutter!"
  },
  AvgVideoCaption_122705_Content_47 = {
    Text = "Murphy, Murphy, mein guter Murphy"
  },
  AvgVideoCaption_122705_Content_48 = {
    Text = "Welches Orakel hat mein Herr gewährt?"
  },
  AvgVideoCaption_122705_Content_49 = {
    Text = "Er, Er sagte: “Das Göttliche Reich wird bald auftauchen.“"
  },
  AvgVideoCaption_122705_Content_5 = {
    Text = "Göttliche Geburt"
  },
  AvgVideoCaption_122705_Content_50 = {
    Text = "Wie erwartet, wie erwartet!"
  },
  AvgVideoCaption_122705_Content_51 = {
    Text = "Es hat sich gelohnt, auf den tausendfachen Moment der richtigen Position der Sterne zu warten"
  },
  AvgVideoCaption_122705_Content_52 = {
    Text = "Mein Herr, mein Herr ist schließlich gekommen, um sein Versprechen zu erfüllen!"
  },
  AvgVideoCaption_122705_Content_53 = {
    Text = "Wann ist es denn?"
  },
  AvgVideoCaption_122705_Content_54 = {
    Text = "Zusammenfassend wird das Göttliche Reich gewiss erscheinen"
  },
  AvgVideoCaption_122705_Content_55 = {
    Text = "Ist das wichtig, in welchem Moment?"
  },
  AvgVideoCaption_122705_Content_56 = {
    Text = "Nein, nein, nein, wir werden im Weihrauch baden und alle Stämme mitbringen"
  },
  AvgVideoCaption_122705_Content_57 = {
    Text = "Gehe zum Ort des Auftauchens des Göttlichen Reiches und warte auf das Erscheinen meines Herrn."
  },
  AvgVideoCaption_122705_Content_58 = {
    Text = "......“Wenn die Sterne richtig stehen“"
  },
  AvgVideoCaption_122705_Content_59 = {
    Text = "Wenn die Sterne richtig stehen?"
  },
  AvgVideoCaption_122705_Content_6 = {
    Text = "Sie haben mich gehört, Sie haben mir geantwortet!"
  },
  AvgVideoCaption_122705_Content_60 = {
    Text = "Welcher Moment der Ausrichtung der Sterne?"
  },
  AvgVideoCaption_122705_Content_61 = {
    Text = "Nächster? Oder der übernächste?"
  },
  AvgVideoCaption_122705_Content_62 = {
    Text = "Es ist so laut, ich habe gesagt, wenn die Sterne richtig stehen"
  },
  AvgVideoCaption_122705_Content_63 = {
    Text = "Woher soll ich wissen, wann der Moment der Ausrichtung der Sterne ist?!"
  },
  AvgVideoCaption_122705_Content_64 = {
    Text = "Auch richtig, auch richtig"
  },
  AvgVideoCaption_122705_Content_65 = {
    Text = "Mein Herr ist gerade aus einem langen Traum erwacht"
  },
  AvgVideoCaption_122705_Content_66 = {
    Text = "Das Bewusstsein befindet sich noch im Chaos"
  },
  AvgVideoCaption_122705_Content_67 = {
    Text = "Der gegenwärtige Moment ist bestimmt auch sehr verschwommen"
  },
  AvgVideoCaption_122705_Content_68 = {
    Text = "Egal, wann mein Herr erscheinen wird..."
  },
  AvgVideoCaption_122705_Content_69 = {
    Text = "Das ist überhaupt nicht wichtig..."
  },
  AvgVideoCaption_122705_Content_7 = {
    Text = "Ihr Wille wird bald auf Erden erneuert werden"
  },
  AvgVideoCaption_122705_Content_70 = {
    Text = "Miryam war außer sich vor Freude"
  },
  AvgVideoCaption_122705_Content_71 = {
    Text = "Das war ein Ausdruck von ekstatischer Freude, den ich noch nie zuvor gesehen habe"
  },
  AvgVideoCaption_122705_Content_72 = {
    Text = "Ich habe ihr die Holzschnitzerei nicht geschenkt"
  },
  AvgVideoCaption_122705_Content_73 = {
    Text = "Ich hatte auch nicht, als ich den heiligen Embryo gebar"
  },
  AvgVideoCaption_122705_Content_74 = {
    Text = "Tag sechs nach der Geburt Gottes"
  },
  AvgVideoCaption_122705_Content_75 = {
    Text = "Der strahlende Glanz in meinem Inneren ist von einem Schleier der Dunkelheit bedeckt"
  },
  AvgVideoCaption_122705_Content_76 = {
    Text = "Kann ich meinen Herrn fragen, wo das göttliche Reich erscheinen wird?"
  },
  AvgVideoCaption_122705_Content_77 = {
    Text = "Ich werde die Seefahrer entsenden, um in der Nähe einen Altar zur Begrüßung des Göttlichen Reiches zu errichten"
  },
  AvgVideoCaption_122705_Content_78 = {
    Text = "Er sagt, dass er sich noch nicht entschieden hat! Jedenfalls ist es von unter dem Meeresspiegel aufgestiegen!"
  },
  AvgVideoCaption_122705_Content_79 = {
    Text = "Ist das... wirklich so?"
  },
  AvgVideoCaption_122705_Content_8 = {
    Text = "Lemuria wird unter Ihrer Führung ewig bestehen!"
  },
  AvgVideoCaption_122705_Content_80 = {
    Text = "Äh... Natürlich!"
  },
  AvgVideoCaption_122705_Content_81 = {
    Text = "Was die Göttliche Mutter sagt, kann doch nicht falsch sein?"
  },
  AvgVideoCaption_122705_Content_82 = {
    Text = "Entschuldigung, ich war zu ungeduldig"
  },
  AvgVideoCaption_122705_Content_83 = {
    Text = "Ich sollte die Göttliche Mutter nicht in Frage stellen"
  },
  AvgVideoCaption_122705_Content_84 = {
    Text = "Lemuria, der König von damals"
  },
  AvgVideoCaption_122705_Content_85 = {
    Text = "Auch in dieser nachlässigen Haltung..."
  },
  AvgVideoCaption_122705_Content_86 = {
    Text = "Bitte erlauben Sie mir, Ihre Handrücken zu küssen"
  },
  AvgVideoCaption_122705_Content_87 = {
    Text = "Ich entschuldige mich für meine Unhöflichkeit"
  },
  AvgVideoCaption_122705_Content_88 = {
    Text = "...endlich durchgekommen"
  },
  AvgVideoCaption_122705_Content_89 = {
    Text = "Aber, was sollen wir morgen tun?"
  },
  AvgVideoCaption_122705_Content_9 = {
    Text = "Ich bin völlig erschöpft von der entzogenem Spiritualität"
  },
  AvgVideoCaption_122705_Content_90 = {
    Text = "Warum antwortet Gott nicht auf unsere Opfer, unsere Gebete?"
  },
  AvgVideoCaption_122705_Content_91 = {
    Text = "Miryam hat mir überhaupt nicht geglaubt"
  },
  AvgVideoCaption_122705_Content_92 = {
    Text = "Ich kann es aus ihrem Blick erkennen"
  },
  AvgVideoCaption_122705_Content_93 = {
    Text = "Sie hatte einen Gott gesehen, der noch nicht gestorben war"
  },
  AvgVideoCaption_122705_Content_94 = {
    Text = "Meine Lüge wird möglicherweise nicht erfolgreich sein"
  },
  AvgVideoCaption_122705_Content_95 = {
    Text = "Gott, bitte hilf mir"
  },
  AvgVideoCaption_122705_Content_96 = {
    Text = "Auch wenn es nur ein Satz ist, antworte meinem Gebet"
  },
  AvgVideoCaption_122705_Content_97 = {
    Text = "Tag sieben nach der Geburt Gottes"
  },
  AvgVideoCaption_122705_Content_98 = {
    Text = "Der Gott ist tot"
  },
  AvgVideoCaption_122705_Content_99 = {
    Text = "Gott wurde niemals geboren"
  },
  AvgVideoCaption_124223_Content_1 = {
    Text = "Was hat der Ermittler noch einmal gesagt"
  },
  AvgVideoCaption_124223_Content_10 = {
    Text = "Ah, richtig, während der Nebelkatastrophe verlor ich plötzlich die Fähigkeit, die \"uralten Artefakte\" zu sehen"
  },
  AvgVideoCaption_124223_Content_100 = {
    Text = "Ein Unfall? Ein Fehler? Oder etwas anderes?"
  },
  AvgVideoCaption_124223_Content_101 = {
    Text = "Komm schon, sag mir, warum bin ich hier!"
  },
  AvgVideoCaption_124223_Content_102 = {
    Text = "Wer hat mich hierher gebracht und zu welchem Zweck!"
  },
  AvgVideoCaption_124223_Content_103 = {
    Text = "Es ist in Ordnung, wenn du nichts sagst. Es ist okay, ihr habt keine Münder, ich verstehe"
  },
  AvgVideoCaption_124223_Content_104 = {
    Text = "Ich muss jemanden mit einem Mund finden"
  },
  AvgVideoCaption_124223_Content_105 = {
    Text = "Ja, es ist eine Person, kein Monster aus dichtem Nebel"
  },
  AvgVideoCaption_124223_Content_106 = {
    Text = "Ich muss zurück, ich muss zurück"
  },
  AvgVideoCaption_124223_Content_107 = {
    Text = "Dieser gottverlassene Ort... Wenn ich hier noch länger bleibe, werde ich verrückt..."
  },
  AvgVideoCaption_124223_Content_108 = {
    Text = "Am achtundzwanzigsten Tag fand ich die Menschheit"
  },
  AvgVideoCaption_124223_Content_109 = {
    Text = "Ich habe endlich den Grund für mein \"Überqueren\" herausgefunden"
  },
  AvgVideoCaption_124223_Content_11 = {
    Text = "Dennoch fühlt es sich so vertraut an wie nach Hause zu kommen"
  },
  AvgVideoCaption_124223_Content_110 = {
    Text = "Diese Gruppe von Kultisten"
  },
  AvgVideoCaption_124223_Content_111 = {
    Text = "Die Kultanhänger, die ich sah, als ich hierher \"überquerte\", haben mich herbeigerufen"
  },
  AvgVideoCaption_124223_Content_112 = {
    Text = "Diese Wahnsinnigen wollen hier weg, auf der Suche nach einer verdammten \"neuen Welt.\""
  },
  AvgVideoCaption_124223_Content_113 = {
    Text = "Aber stattdessen teleportierte es mich aus der \"Neuen Welt.\""
  },
  AvgVideoCaption_124223_Content_114 = {
    Text = "Ha, das ist wirklich schwarzer Humor"
  },
  AvgVideoCaption_124223_Content_115 = {
    Text = "Ermittler, ich wollte dieses Untersuchungsprotokoll zurückbringen, um es dir zu zeigen"
  },
  AvgVideoCaption_124223_Content_116 = {
    Text = "Aber es wird jetzt nicht benötigt"
  },
  AvgVideoCaption_124223_Content_117 = {
    Text = "Ich habe einen neuen Plan"
  },
  AvgVideoCaption_124223_Content_118 = {
    Text = "Mögen sie es nicht, Menschen zu fangen?"
  },
  AvgVideoCaption_124223_Content_119 = {
    Text = "Hier ist einer"
  },
  AvgVideoCaption_124223_Content_12 = {
    Text = "Also habe ich nicht einmal bemerkt, dass ich \"überquert\" hatte"
  },
  AvgVideoCaption_124223_Content_120 = {
    Text = "Lass mich darüber nachdenken, wie ich es ausführen kann..."
  },
  AvgVideoCaption_124223_Content_121 = {Text = "Hilf mir!"},
  AvgVideoCaption_124223_Content_122 = {
    Text = "Nein, der Geschmack reicht nicht aus; er muss furchterregender, verzweifelter sein..."
  },
  AvgVideoCaption_124223_Content_123 = {Text = "Ja"},
  AvgVideoCaption_124223_Content_124 = {
    Text = "Wie die sterbenden Schreie der Überlebenden"
  },
  AvgVideoCaption_124223_Content_125 = {
    Text = "Nun endet \"Mouchettes Aufzeichnung der Jenseitsuntersuchung\""
  },
  AvgVideoCaption_124223_Content_126 = {
    Text = "Die Show heißt \"Unschuldiges Opfer: Zerstörung des Kults Versteck.\""
  },
  AvgVideoCaption_124223_Content_127 = {
    Text = "Ermittler, ich werde mein Bestes tun, um nach Hause zu kommen"
  },
  AvgVideoCaption_124223_Content_128 = {
    Text = "Aber wenn der Plan scheitert, mach dir keine Sorgen, denn egal was passiert"
  },
  AvgVideoCaption_124223_Content_129 = {
    Text = "Mein Leben wird ein prächtiges Ende haben"
  },
  AvgVideoCaption_124223_Content_13 = {
    Text = "Ich sah nur einige vermummte Gestalten plötzlich vor mir erscheinen"
  },
  AvgVideoCaption_124223_Content_130 = {
    Text = "Die Schreie dieser Kultanhänger werden der beste Applaus sein"
  },
  AvgVideoCaption_124223_Content_14 = {
    Text = "Die Menschen, die sie menschliches Viehzeug nennen, mit silberbeschichteten Dolchen verfolgen"
  },
  AvgVideoCaption_124223_Content_15 = {
    Text = "Und diese Bestien schreien und heulen und treiben mich an den Rand des Wahnsinns"
  },
  AvgVideoCaption_124223_Content_16 = {
    Text = "Halt den Mund, es ist so laut!"
  },
  AvgVideoCaption_124223_Content_17 = {
    Text = "Niemand kümmert sich überhaupt um mich"
  },
  AvgVideoCaption_124223_Content_18 = {
    Text = "Wenn man das Messer, das in meiner Schulter steckt, nicht zählt"
  },
  AvgVideoCaption_124223_Content_19 = {
    Text = "Sieht so aus, als würdest du lieber mit Waffen begrüßen?"
  },
  AvgVideoCaption_124223_Content_2 = {
    Text = "Ein Tagebuch zu führen hilft, Erinnerungen zu organisieren und die Gelassenheit zu bewahren"
  },
  AvgVideoCaption_124223_Content_20 = {
    Text = "Was für ein Zufall, ich auch"
  },
  AvgVideoCaption_124223_Content_21 = {
    Text = "Komm, begrüße meine geliebte Axt—"
  },
  AvgVideoCaption_124223_Content_22 = {
    Text = "Shining☆Tornado!"
  },
  AvgVideoCaption_124223_Content_23 = {
    Text = "Einer nach dem anderen... In dem dichten Nebel, den niemand kennt, lasse ich meinen Gefühlen freien Lauf♪"
  },
  AvgVideoCaption_124223_Content_24 = {
    Text = "Klopf auf deinen Schädel, tauche in dein Gehirn ein, lass uns die Zeit vertreiben, während wir jagen♪"
  },
  AvgVideoCaption_124223_Content_25 = {
    Text = "Endlich ist die Welt sauber"
  },
  AvgVideoCaption_124223_Content_26 = {
    Text = "Ich warte darauf, dass der Ermittler das Durcheinander aufräumt"
  },
  AvgVideoCaption_124223_Content_27 = {
    Text = "Ich weiß nicht einmal, wie viele Worte ich für den Reflexionsbericht über diese \"impulsive Handlung\" schreiben muss"
  },
  AvgVideoCaption_124223_Content_28 = {
    Text = "Aber am zweiten, dritten und vierten Tag kam niemand, um mich zu suchen"
  },
  AvgVideoCaption_124223_Content_29 = {
    Text = "Nur die unbekannten Monster im dichten Nebel belästigen mich ständig"
  },
  AvgVideoCaption_124223_Content_3 = {
    Text = "Huh, Grund?"
  },
  AvgVideoCaption_124223_Content_30 = {
    Text = "Verdammtes, können mir diese Typen nicht etwas Zeit zum Essen geben?"
  },
  AvgVideoCaption_124223_Content_31 = {
    Text = "Ich muss auch schlafen, okay!"
  },
  AvgVideoCaption_124223_Content_32 = {
    Text = "Und diese Nebelkatastrophe, wie lange dauert es noch, bis wir hier rauskommen können!"
  },
  AvgVideoCaption_124223_Content_33 = {
    Text = "Ermittler, Ihre Mouchette verhungert, sie verdurstet."
  },
  AvgVideoCaption_124223_Content_34 = {
    Text = "Ich werde an Erschöpfung sterben in dieser Nebelkatastrophe, die nur von Nebelmonstern erfüllt ist"
  },
  AvgVideoCaption_124223_Content_35 = {
    Text = "Wo zur Hölle bist du?!"
  },
  AvgVideoCaption_124223_Content_36 = {
    Text = "So hungrig, so durstig, so müde..."
  },
  AvgVideoCaption_124223_Content_37 = {
    Text = "So zu sterben ist zu lässig"
  },
  AvgVideoCaption_124223_Content_38 = {
    Text = "Ich dachte, mein Leben würde ein cooles Ende haben..."
  },
  AvgVideoCaption_124223_Content_39 = {
    Text = "Am wichtigsten"
  },
  AvgVideoCaption_124223_Content_4 = {
    Text = "Seit ich unerklärlicherweise in diese Welt übergetreten bin, kann ich meinen Verstand nicht mehr bewahren"
  },
  AvgVideoCaption_124223_Content_40 = {
    Text = "Ich will nicht... allein sein..."
  },
  AvgVideoCaption_124223_Content_41 = {
    Text = "Hmm, an welchem Tag sind wir jetzt?"
  },
  AvgVideoCaption_124223_Content_42 = {
    Text = "Oh, der fünfte Tag"
  },
  AvgVideoCaption_124223_Content_43 = {
    Text = "Ich, Mouchette, lebe immer noch in dieser langweiligen Welt"
  },
  AvgVideoCaption_124223_Content_44 = {
    Text = "\"Die lokalen Überlebenden der Nebelkatastrophe haben mich gerettet.\""
  },
  AvgVideoCaption_124223_Content_45 = {
    Text = "Nach einem verwirrenden Gespräch"
  },
  AvgVideoCaption_124223_Content_46 = {
    Text = "Ich verstehe endlich, dass ich \"überquert\" habe"
  },
  AvgVideoCaption_124223_Content_47 = {
    Text = "Von jetzt an wird es keinen dampfenden Haselnuss-Kava-Tee und keinen duftenden Ravenloft-Eintopf mehr geben"
  },
  AvgVideoCaption_124223_Content_48 = {
    Text = "Nur hartes schwarzes Brot und trübes Wasser, vermischt mit Sand"
  },
  AvgVideoCaption_124223_Content_49 = {
    Text = "Aber ich kann mich auch über nichts beschweren"
  },
  AvgVideoCaption_124223_Content_5 = {
    Text = "Nun, da wir im Moment nicht zurückgehen können, sollten wir uns wenigstens etwas Spaß suchen, um die Zeit zu vertreiben..."
  },
  AvgVideoCaption_124223_Content_50 = {
    Text = "Schließlich hat diese Stadt den Kontakt zur Außenwelt abgebrochen"
  },
  AvgVideoCaption_124223_Content_51 = {
    Text = "Die Nebelkatastrophe hat wieder alle gefangen, und jede Person sieht von Hunger abgemagert aus"
  },
  AvgVideoCaption_124223_Content_52 = {
    Text = "Der Geist bricht allmählich unter den täglichen Qualen zusammen"
  },
  AvgVideoCaption_124223_Content_53 = {
    Text = "Ich denke, das Leben ist im Moment ziemlich interessant, abgesehen davon, dass ich meine \"Freiheit verloren habe.\""
  },
  AvgVideoCaption_124223_Content_54 = {
    Text = "Wenn mir langweilig ist, gehe ich hinaus und jage ein paar Monster"
  },
  AvgVideoCaption_124223_Content_55 = {
    Text = "Ich kann auch neue Vorräte mitbringen und dabei zwei Fliegen mit einer Klappe schlagen"
  },
  AvgVideoCaption_124223_Content_56 = {
    Text = "Lass es mich so sagen, dieser Ort ist wie ein Spielplatz"
  },
  AvgVideoCaption_124223_Content_57 = {
    Text = "Es gibt antike Relikte, um Stress abzubauen, und Gute-Nacht-Geschichten aus einer anderen Welt, die man hören kann"
  },
  AvgVideoCaption_124223_Content_58 = {
    Text = "Flüstern von jedermanns bevorstehendem Zusammenbruch wie ein Wiegenlied"
  },
  AvgVideoCaption_124223_Content_59 = {
    Text = "Es ist ziemlich unterhaltsam, gelegentlich zu sehen, wie andere in Kämpfe geraten und blutig und verletzt enden"
  },
  AvgVideoCaption_124223_Content_6 = {
    Text = "Ich hätte nie erwartet, dass ich auch Zeiten haben würde, in denen ich langweilige Dinge wie ein Tagebuch schreibe..."
  },
  AvgVideoCaption_124223_Content_60 = {
    Text = "Ich weiß nicht, worüber man sich streiten kann, wer einen zusätzlichen Schluck Wasser getrunken oder einen zusätzlichen Bissen Brot gegessen hat"
  },
  AvgVideoCaption_124223_Content_61 = {
    Text = "Vielleicht sind diese nicht mehr wichtig"
  },
  AvgVideoCaption_124223_Content_62 = {
    Text = "Sie wollen nur einen Grund, um ihre Panik abzubauen"
  },
  AvgVideoCaption_124223_Content_63 = {
    Text = "Was für ein Bedauern und Traurigkeit das ist"
  },
  AvgVideoCaption_124223_Content_64 = {
    Text = "Das ist das erste Mal, dass ich in mein Tagebuch schreibe, seit \"dieses Ereignis\" passiert ist"
  },
  AvgVideoCaption_124223_Content_65 = {
    Text = "Alex ist tot, direkt vor mir —"
  },
  AvgVideoCaption_124223_Content_66 = {
    Text = "Er wurde von der Nebelkatastrophe erodiert und verschwand vollständig im dichten Nebel, wie ein Wassertropfen, der im Ozean sich auflöst"
  },
  AvgVideoCaption_124223_Content_67 = {
    Text = "Dies ist der zweite Vorfall der Nebelkatastrophen-Erosion, der höchste Alarmbereitschaft erfordert"
  },
  AvgVideoCaption_124223_Content_68 = {
    Text = "Ich muss mehr Vorräte sammeln und die verbleibenden Überlebenden aus der Nebelkatastrophen-Zone bringen"
  },
  AvgVideoCaption_124223_Content_69 = {
    Text = "Am elften Tag fand ich etwas getrocknetes Wildbret, keimende Kartoffeln und Speck"
  },
  AvgVideoCaption_124223_Content_7 = {
    Text = "In Ordnung, betrachten wir es als einen frühen Untersuchungsbericht"
  },
  AvgVideoCaption_124223_Content_70 = {
    Text = "Bacon ist lecker, aber nicht so gut wie Ravenloft-Eintopf"
  },
  AvgVideoCaption_124223_Content_71 = {
    Text = "Es wäre sogar noch besser, eine weitere dampfende Tasse Haselnuss-Kava-Tee zu haben, was für ein Bedauern"
  },
  AvgVideoCaption_124223_Content_72 = {
    Text = "Der dreizehnte Tag"
  },
  AvgVideoCaption_124223_Content_73 = {
    Text = "Ich habe etwas Brot, getrocknetes Wildbret gefunden, aber kein Wasser"
  },
  AvgVideoCaption_124223_Content_74 = {
    Text = "Alles Brunnenwasser wurde durch dichten Nebel kontaminiert"
  },
  AvgVideoCaption_124223_Content_75 = {Text = "Later"},
  AvgVideoCaption_124223_Content_76 = {
    Text = "Anna ist tot"
  },
  AvgVideoCaption_124223_Content_77 = {
    Text = "Von der Nebelkatastrophe erodiert, vor aller Augen verschwunden"
  },
  AvgVideoCaption_124223_Content_78 = {
    Text = "Am sechzehnten Tag immer noch getrocknetes Wildbret, dazu ein kleiner Sack Haferbrei"
  },
  AvgVideoCaption_124223_Content_79 = {
    Text = "Die kleine Betty und die kleine Susan werden vermisst"
  },
  AvgVideoCaption_124223_Content_8 = {
    Text = "Nun wird \"Mouchettes Aufzeichnung der Jenseitsuntersuchung\" offiziell archiviert—"
  },
  AvgVideoCaption_124223_Content_80 = {
    Text = "Keine Gutenachtgeschichten mehr"
  },
  AvgVideoCaption_124223_Content_81 = {
    Text = "Die Kinder, die das hören mussten, sind alle weg"
  },
  AvgVideoCaption_124223_Content_82 = {
    Text = "Am siebzehnten Tag wurde nichts gefunden"
  },
  AvgVideoCaption_124223_Content_83 = {
    Text = "Charles' Nervenzusammenbruch"
  },
  AvgVideoCaption_124223_Content_84 = {Text = "Suicide"},
  AvgVideoCaption_124223_Content_85 = {
    Text = "Am achtzehnten Tag wurde nichts gefunden"
  },
  AvgVideoCaption_124223_Content_86 = {
    Text = "Am einundzwanzigsten Tag, getrocknetes Wildbret, keimende Kartoffeln..."
  },
  AvgVideoCaption_124223_Content_87 = {
    Text = "Was mache ich überhaupt? Mouchette, hast du dein Ziel vergessen? Dein Ziel ist es, nach Hause zu gehen"
  },
  AvgVideoCaption_124223_Content_88 = {
    Text = "Anstatt hier ein Schläger zu sein, getrocknetes Wildbret und keimende Kartoffeln zu sammeln"
  },
  AvgVideoCaption_124223_Content_89 = {
    Text = "Zur Hölle mit dem getrockneten Wildbret und den keimenden Kartoffeln!"
  },
  AvgVideoCaption_124223_Content_9 = {
    Text = "Lass mich über den ersten Tag des \"Überquerens\" nachdenken..."
  },
  AvgVideoCaption_124223_Content_90 = {
    Text = "Nein, beruhige dich, beruhige dich"
  },
  AvgVideoCaption_124223_Content_91 = {
    Text = "Es gibt drei Überlebende"
  },
  AvgVideoCaption_124223_Content_92 = {
    Text = "Bring sie aus der Nebelkatastrophen-Zone, dann denke darüber nach, nach Hause zu gehen"
  },
  AvgVideoCaption_124223_Content_93 = {
    Text = "So, sei nicht schwierig, werde nicht verrückt, bevor die Nebelkatastrophe eintritt"
  },
  AvgVideoCaption_124223_Content_94 = {
    Text = "Ahhhhh—spuck es aus! Spuck sie für mich aus!"
  },
  AvgVideoCaption_124223_Content_95 = {
    Text = "Du denkst, ich kann dich nicht töten? Nein, ich habe vor nichts Angst, ich kann alles überwinden"
  },
  AvgVideoCaption_124223_Content_96 = {
    Text = "Also gib sie zurück! Ich befehle dir, sie zurückzugeben!"
  },
  AvgVideoCaption_124223_Content_97 = {
    Text = "Kann nicht speichern... warum kann ich nicht einmal eins speichern..."
  },
  AvgVideoCaption_124223_Content_98 = {
    Text = "Alles, was ich getan habe, ist völlig sinnlos!"
  },
  AvgVideoCaption_124223_Content_99 = {
    Text = "Warum bin ich hier?"
  },
  AvgVideoCaption_126905_Content_1 = {
    Text = "Warum zitterst du?"
  },
  AvgVideoCaption_126905_Content_10 = {
    Text = "Was du magst, ist das, was echt ist"
  },
  AvgVideoCaption_126905_Content_100 = {
    Text = "Bin ich Mūmā oder Herr Xu?"
  },
  AvgVideoCaption_126905_Content_101 = {
    Text = "Nānnān, du hast diese Geschichte verstanden"
  },
  AvgVideoCaption_126905_Content_102 = {
    Text = "Wir haben noch eine letzte Sache zu erledigen"
  },
  AvgVideoCaption_126905_Content_103 = {
    Text = "Dad will uns daran hindern, zusammen zu sein"
  },
  AvgVideoCaption_126905_Content_104 = {
    Text = "So wie er mich damals von dir weggenommen hat"
  },
  AvgVideoCaption_126905_Content_105 = {
    Text = "Er hat mich zerbrochen, mich geopfert, um so etwas zu erlangen"
  },
  AvgVideoCaption_126905_Content_106 = {
    Text = "Verwandle das Reh in ein Pferd, mache das Falsche zu etwas Echtem"
  },
  AvgVideoCaption_126905_Content_107 = {
    Text = "Aber wir werden dir nur dieses Ding geben"
  },
  AvgVideoCaption_126905_Content_108 = {
    Text = "Wirf es weg, Ho Fong"
  },
  AvgVideoCaption_126905_Content_109 = {
    Text = "Werf diese Träume weg"
  },
  AvgVideoCaption_126905_Content_11 = {
    Text = "Was du nicht magst, kann das Falsche sein"
  },
  AvgVideoCaption_126905_Content_110 = {
    Text = "Komm vollständig, komm vollständig, zu meiner Seite.\nKomm vollständig, komm vollständig, zu Mūmās Seite"
  },
  AvgVideoCaption_126905_Content_111 = {
    Text = "Dann werde ich dafür sorgen, dass dieses süße Geschenk für immer dir gehört"
  },
  AvgVideoCaption_126905_Content_112 = {
    Text = "Wir werden immer"
  },
  AvgVideoCaption_126905_Content_113 = {
    Text = "Zusammen mit dir"
  },
  AvgVideoCaption_126905_Content_12 = {Text = "Warum?"},
  AvgVideoCaption_126905_Content_13 = {
    Text = "Du siehst aus, als würdest du gleich einschlafen, kleine Jasmin"
  },
  AvgVideoCaption_126905_Content_14 = {
    Text = "Was würde die Mutter der Menschheit in diesem Moment tun..."
  },
  AvgVideoCaption_126905_Content_15 = {
    Text = "Lass mich dir eine Gutenachtgeschichte erzählen"
  },
  AvgVideoCaption_126905_Content_16 = {
    Text = "Vor sehr, sehr langer Zeit"
  },
  AvgVideoCaption_126905_Content_17 = {
    Text = "In der wohlhabendsten Nation des Ostens"
  },
  AvgVideoCaption_126905_Content_18 = {
    Text = "Es sitzt ein kleiner König auf seinem Thron"
  },
  AvgVideoCaption_126905_Content_19 = {
    Text = "Unter seinem Thron"
  },
  AvgVideoCaption_126905_Content_2 = {
    Text = "Was für ein bedauerliches Schicksal"
  },
  AvgVideoCaption_126905_Content_20 = {
    Text = "Es gibt einen mächtigen Minister, der über allen anderen steht"
  },
  AvgVideoCaption_126905_Content_21 = {
    Text = "Sein Macht begehren"
  },
  AvgVideoCaption_126905_Content_22 = {
    Text = "Jeder in diesem Land weiß über diese Angelegenheit Bescheid"
  },
  AvgVideoCaption_126905_Content_23 = {
    Text = "Aber alle warten; sie haben nicht entschieden, ob sie neben dem König oder dem mächtigen Minister stehen sollen"
  },
  AvgVideoCaption_126905_Content_24 = {
    Text = "Warum noch?"
  },
  AvgVideoCaption_126905_Content_25 = {
    Text = "Ah... lästige menschliche Nachkommen"
  },
  AvgVideoCaption_126905_Content_26 = {
    Text = "Weil sie herausfinden wollen, auf welcher Seite mehr Menschen sind"
  },
  AvgVideoCaption_126905_Content_27 = {
    Text = "Kraft ist die Art von Dingen, die die Starken stärker und die Schwachen schwächer macht"
  },
  AvgVideoCaption_126905_Content_28 = {
    Text = "Tut dein Kopf wieder weh"
  },
  AvgVideoCaption_126905_Content_29 = {
    Text = "Bald... bald wird deine Krankheit geheilt sein"
  },
  AvgVideoCaption_126905_Content_3 = {
    Text = "Wird das besser, kleine Jasmin?"
  },
  AvgVideoCaption_126905_Content_30 = {
    Text = "Komm, ich weiß, wie ich mein liebes Baby besser fühlen lassen kann"
  },
  AvgVideoCaption_126905_Content_31 = {
    Text = "Du musst dich nur entspannen..."
  },
  AvgVideoCaption_126905_Content_32 = {Text = "So ist es"},
  AvgVideoCaption_126905_Content_33 = {
    Text = "Als Nächstes..."
  },
  AvgVideoCaption_126905_Content_34 = {
    Text = "Wo waren wir gerade eben."
  },
  AvgVideoCaption_126905_Content_35 = {
    Text = "Bald wird jeder die Möglichkeit haben, eine Wahl zu treffen"
  },
  AvgVideoCaption_126905_Content_36 = {Text = "Dieser Tag"},
  AvgVideoCaption_126905_Content_37 = {
    Text = "Der exotische Händler hat frische Waren gebracht"
  },
  AvgVideoCaption_126905_Content_38 = {
    Text = "Es hat vier agile, schlanke Hufe"
  },
  AvgVideoCaption_126905_Content_39 = {
    Text = "Gleichzeitig gibt es ein Paar lange Hörner und ein schönes Fell, das mit Flecken bedeckt ist"
  },
  AvgVideoCaption_126905_Content_4 = {
    Text = "Komm näher"
  },
  AvgVideoCaption_126905_Content_40 = {
    Text = "Mächtiger Minister spricht"
  },
  AvgVideoCaption_126905_Content_41 = {
    Text = "\"Eure Majestät, ich habe Ihnen ein Pferd von tausend Meilen mitgebracht.\""
  },
  AvgVideoCaption_126905_Content_42 = {
    Text = "Nun, das ist sicherlich kein Pferd"
  },
  AvgVideoCaption_126905_Content_43 = {
    Text = "Wang sagte das auch"
  },
  AvgVideoCaption_126905_Content_44 = {
    Text = "„Mein lieber Minister, das ist doch ein Scherz; das ist eindeutig ein Reh.“"
  },
  AvgVideoCaption_126905_Content_45 = {
    Text = "Die sitzenden Leute führten ebenfalls lebhafte Diskussionen"
  },
  AvgVideoCaption_126905_Content_46 = {
    Text = "Doch der mächtige Minister sah den König einfach ruhig an und sagte"
  },
  AvgVideoCaption_126905_Content_47 = {
    Text = "\"Mein Herr, das ist ein Pferd.\""
  },
  AvgVideoCaption_126905_Content_48 = {
    Text = "Diejenigen, die neben dem mächtigen Minister standen, äußerten sich ebenfalls"
  },
  AvgVideoCaption_126905_Content_49 = {
    Text = "„Ja, das ist ein Pferd.“"
  },
  AvgVideoCaption_126905_Content_5 = {
    Text = "Ich werde eine Wolke fangen, auf die du dich lehnen kannst..."
  },
  AvgVideoCaption_126905_Content_50 = {
    Text = "\"Ma Mingming ist genau gleich wie dieses.\""
  },
  AvgVideoCaption_126905_Content_51 = {
    Text = "„Was für ein prächtiges Ross! Herzlichen Glückwunsch, Eure Majestät, zu so einem feinen Pferd.“"
  },
  AvgVideoCaption_126905_Content_52 = {
    Text = "Vielleicht ist es die Angst vor der Macht der mächtigen Minister, oder vielleicht sind die Stimmen der Zustimmung zu zahlreich"
  },
  AvgVideoCaption_126905_Content_53 = {
    Text = "Einige Menschen sagten, es sei das Geräusch von Rehen, aber sie wurden bald von dem Lärm übertönt"
  },
  AvgVideoCaption_126905_Content_54 = {
    Text = "In der Schallwelle, vor allen, beginnt der Hirsch sich zu verändern"
  },
  AvgVideoCaption_126905_Content_55 = {
    Text = "Die Pflaumenblüten reißen und trocknen Stück für Stück von ihrem Körper, die Blütenblätter erweichen und welken, bevor sie schließlich abfallen"
  },
  AvgVideoCaption_126905_Content_56 = {
    Text = "Seine Knochen knacken, während sie sich dehnen"
  },
  AvgVideoCaption_126905_Content_57 = {
    Text = "Das Plasma, das aus dem zerrissenen Körper sickert, bleibt zwischen den Zehen kleben und bildet sein Hufeisen"
  },
  AvgVideoCaption_126905_Content_58 = {
    Text = "Dieses blutgetränkte Monster steht in der Halle"
  },
  AvgVideoCaption_126905_Content_59 = {
    Text = "Lass ein komisches und unbeholfenes Zischen los"
  },
  AvgVideoCaption_126905_Content_6 = {
    Text = "Ja, im traumlosen Land ist das keine überraschende Sache"
  },
  AvgVideoCaption_126905_Content_60 = {
    Text = "Der mächtige Minister streichelte es ruhig"
  },
  AvgVideoCaption_126905_Content_61 = {
    Text = "Der König stand aus Angst regungslos da"
  },
  AvgVideoCaption_126905_Content_62 = {
    Text = "Die Menschen verstanden, wo sie stehen sollten"
  },
  AvgVideoCaption_126905_Content_63 = {
    Text = "Von jetzt an"
  },
  AvgVideoCaption_126905_Content_64 = {
    Text = "Der unheimliche Schatten, der sich von einem Reh in ein Pferd verwandelt hat, folgt dem König schon die ganze Zeit"
  },
  AvgVideoCaption_126905_Content_65 = {
    Text = "Niemand kümmert sich mehr um seine Autorität"
  },
  AvgVideoCaption_126905_Content_66 = {
    Text = "Niemand kümmert sich mehr um seine Gedanken"
  },
  AvgVideoCaption_126905_Content_67 = {
    Text = "Niemand schenkte den Heulern Beachtung, die seiner Kehle entglitten, während er vom Monster gequält wurde"
  },
  AvgVideoCaption_126905_Content_68 = {
    Text = "Weil es aus Verlangen, Angst, Abwägung oder etwas anderem kommt"
  },
  AvgVideoCaption_126905_Content_69 = {
    Text = "Menschen stehen neben dem mächtigen Minister"
  },
  AvgVideoCaption_126905_Content_7 = {
    Text = "Es hat einen Duft, sanft und kühl"
  },
  AvgVideoCaption_126905_Content_70 = {
    Text = "Er sagte, es ist ein Pferd, es ist ein Pferd, und ein Reh ist auch ein Pferd"
  },
  AvgVideoCaption_126905_Content_71 = {
    Text = "Also, ein König ist immer noch ein König"
  },
  AvgVideoCaption_126905_Content_72 = {
    Text = "Es liegt nur daran, dass er nicht sprach, dass der König kein König ist"
  },
  AvgVideoCaption_126905_Content_73 = {
    Text = "Kleine Jasmin, was hast du in der Geschichte gekostet?"
  },
  AvgVideoCaption_126905_Content_74 = {
    Text = "Hehehe... Hahahahaha!"
  },
  AvgVideoCaption_126905_Content_75 = {
    Text = "Mein Schatz"
  },
  AvgVideoCaption_126905_Content_76 = {
    Text = "Mein teuerstes, geliebtes Baby"
  },
  AvgVideoCaption_126905_Content_77 = {
    Text = "Ja, es ist süß"
  },
  AvgVideoCaption_126905_Content_78 = {
    Text = "Solange die meisten Menschen an deiner Seite stehen"
  },
  AvgVideoCaption_126905_Content_79 = {
    Text = "Solange die Macht in meinen Händen liegt"
  },
  AvgVideoCaption_126905_Content_8 = {
    Text = "Das ist richtig, mein liebes Baby, er ist natürlich die Wolke"
  },
  AvgVideoCaption_126905_Content_80 = {
    Text = "Wahrheit, Falschheit, richtig oder falsch, alles liegt in den Gedanken deines Geistes"
  },
  AvgVideoCaption_126905_Content_81 = {
    Text = "Der Wille der Könige und der Schrecken, dem die einfachen Leute gegenüberstehen"
  },
  AvgVideoCaption_126905_Content_82 = {
    Text = "Es ist irrelevant"
  },
  AvgVideoCaption_126905_Content_83 = {
    Text = "Shencheng wird dein Spielzeug sein"
  },
  AvgVideoCaption_126905_Content_84 = {
    Text = "Die Welt... wird auch dein Spielzeug sein"
  },
  AvgVideoCaption_126905_Content_85 = {
    Text = "Du bist schon zu müde"
  },
  AvgVideoCaption_126905_Content_86 = {
    Text = "Was ist falsch daran, sich an etwas Bestimmtem festhalten zu wollen?"
  },
  AvgVideoCaption_126905_Content_87 = {
    Text = "Macht ist sicher, Macht ist süß, mein kleines Jasmin"
  },
  AvgVideoCaption_126905_Content_88 = {
    Text = "Du glaubst, dass er die Wolke ist, er ist die Wolke"
  },
  AvgVideoCaption_126905_Content_89 = {
    Text = "Wer auch immer du an deiner Seite haben möchtest, wird immer, für immer, an deiner Seite sein"
  },
  AvgVideoCaption_126905_Content_9 = {Text = "Shh—"},
  AvgVideoCaption_126905_Content_90 = {Text = "Hm?"},
  AvgVideoCaption_126905_Content_91 = {
    Text = "Ah... Ist das zu kompliziert?"
  },
  AvgVideoCaption_126905_Content_92 = {
    Text = "Winzig, weich, zerbrechlich kleines Ding"
  },
  AvgVideoCaption_126905_Content_93 = {
    Text = "Nur für einen Ort zum Niederlassen"
  },
  AvgVideoCaption_126905_Content_94 = {
    Text = "Nur um einsam zu vermeiden"
  },
  AvgVideoCaption_126905_Content_95 = {
    Text = "Ich würde alles tun"
  },
  AvgVideoCaption_126905_Content_96 = {
    Text = "Komm her, in meine Arme"
  },
  AvgVideoCaption_126905_Content_97 = {
    Text = "Diejenigen im traumlosen Land müssen nicht träumen"
  },
  AvgVideoCaption_126905_Content_98 = {
    Text = "Du wirst die verborgene Wahrheit erlangen"
  },
  AvgVideoCaption_126905_Content_99 = {
    Text = "Woran glaubst du, kleine Jasmin?"
  },
  AvgVideoCaption_131662_Content_1 = {
    Text = "Kalt, so kalt..."
  },
  AvgVideoCaption_131662_Content_10 = {
    Text = "Verdächtiges Bewusstsein hat den @3 Bewusstseinsraum noch nicht verlassen"
  },
  AvgVideoCaption_131662_Content_100 = {
    Text = "Katastrophe... Katastrophe... Katastrophe..."
  },
  AvgVideoCaption_131662_Content_101 = {
    Text = "Flieh, flieh"
  },
  AvgVideoCaption_131662_Content_102 = {
    Text = "Schnell weg, schnell weg"
  },
  AvgVideoCaption_131662_Content_103 = {
    Text = "Feuerball......"
  },
  AvgVideoCaption_131662_Content_104 = {
    Text = "Dreißigste Mal..."
  },
  AvgVideoCaption_131662_Content_105 = {
    Text = "Vierzig Mal?"
  },
  AvgVideoCaption_131662_Content_106 = {
    Text = "Schnell lauf... Verzerrung"
  },
  AvgVideoCaption_131662_Content_107 = {
    Text = "Es ist kalt... Es ist kalt..."
  },
  AvgVideoCaption_131662_Content_108 = {
    Text = "Freund...Kohleball..."
  },
  AvgVideoCaption_131662_Content_109 = {
    Text = "Entschuldigung... Entschuldigung"
  },
  AvgVideoCaption_131662_Content_11 = {
    Text = "@3 Tage später zeigt dieser Erwecker eine Vernunft, die eine gewisse Sprache verstehen kann"
  },
  AvgVideoCaption_131662_Content_110 = {
    Text = "Wirbel, wir müssen gehen, Wirbel"
  },
  AvgVideoCaption_131662_Content_111 = {
    Text = "Wirbel, wir müssen gehen, um zu retten"
  },
  AvgVideoCaption_131662_Content_112 = {
    Text = "Mosk, hilf, Menschen zu retten..."
  },
  AvgVideoCaption_131662_Content_113 = {Text = "Kalt, kalt"},
  AvgVideoCaption_131662_Content_114 = {
    Text = "Der Lärm ist so laut"
  },
  AvgVideoCaption_131662_Content_115 = {Text = "Aber..."},
  AvgVideoCaption_131662_Content_116 = {
    Text = "Mosk, mach! Hilf den Leuten"
  },
  AvgVideoCaption_131662_Content_117 = {
    Text = "O-1841 Erwecker"
  },
  AvgVideoCaption_131662_Content_118 = {
    Text = "O-1841 Erwecker"
  },
  AvgVideoCaption_131662_Content_119 = {
    Text = "Kannst du meine Stimme hören?"
  },
  AvgVideoCaption_131662_Content_12 = {
    Text = "Die Misa-Akademie beginnt, mit dem Erweckungssystem Kontakt aufzunehmen"
  },
  AvgVideoCaption_131662_Content_120 = {
    Text = "Obwohl ich nicht wahrnehmen kann"
  },
  AvgVideoCaption_131662_Content_121 = {
    Text = "Aber durch die Messung mit dem Instrument @4 wurde festgestellt, dass deine Stärke unbewusst alles um dich herum verzerren kann"
  },
  AvgVideoCaption_131662_Content_122 = {
    Text = "Danke, dass du versucht hast, uns zu erinnern"
  },
  AvgVideoCaption_131662_Content_123 = {
    Text = "Wenn du bereit bist, mitzuarbeiten"
  },
  AvgVideoCaption_131662_Content_124 = {
    Text = "Misaq kann dir helfen"
  },
  AvgVideoCaption_131662_Content_125 = {
    Text = "Durch ständige Verbesserung der Fesselvorrichtung"
  },
  AvgVideoCaption_131662_Content_126 = {
    Text = "Du kannst die Stärke des Wirbels auf ein begrenztes Gebiet übertragen und freigeben"
  },
  AvgVideoCaption_131662_Content_127 = {
    Text = "Unschädlich machen"
  },
  AvgVideoCaption_131662_Content_128 = {
    Text = "Wirbel... übertragen?"
  },
  AvgVideoCaption_131662_Content_129 = {
    Text = "Aber die verschobenen Koordinaten können nur um dich herum zentriert sein"
  },
  AvgVideoCaption_131662_Content_13 = {
    Text = "Ah, ah... ah————"
  },
  AvgVideoCaption_131662_Content_130 = {
    Text = "Deshalb musst du ständig darauf achten, die Fesselvorrichtung gut zu kontrollieren"
  },
  AvgVideoCaption_131662_Content_131 = {
    Text = "Wirbel, Übertragung"
  },
  AvgVideoCaption_131662_Content_132 = {
    Text = "Nein, es könnte Schaden verursachen..."
  },
  AvgVideoCaption_131662_Content_133 = {
    Text = "Nein, Schaden, Freund... Kohleball"
  },
  AvgVideoCaption_131662_Content_134 = {Text = "Wirbel"},
  AvgVideoCaption_131662_Content_135 = {
    Text = "Übertragung"
  },
  AvgVideoCaption_131662_Content_136 = {Text = "Selbst"},
  AvgVideoCaption_131662_Content_137 = {Text = "Warte"},
  AvgVideoCaption_131662_Content_138 = {
    Text = "O-1841 Erwecker, du..."
  },
  AvgVideoCaption_131662_Content_139 = {
    Text = "Wirbel, übertragen, selbst"
  },
  AvgVideoCaption_131662_Content_14 = {
    Text = "Ruhig, bleib ruhig"
  },
  AvgVideoCaption_131662_Content_140 = {
    Text = "Nein, es könnte Schaden verursachen..."
  },
  AvgVideoCaption_131662_Content_141 = {
    Text = "Alle Wellenformen sind verschwunden..."
  },
  AvgVideoCaption_131662_Content_142 = {
    Text = "Hast du die Kraft des Wirbels in deinen Körper übertragen?"
  },
  AvgVideoCaption_131662_Content_143 = {Text = "Aber..."},
  AvgVideoCaption_131662_Content_144 = {
    Text = "So wirst du unmenschlichen Schmerz ertragen müssen..."
  },
  AvgVideoCaption_131662_Content_145 = {Text = "Mosk"},
  AvgVideoCaption_131662_Content_146 = {
    Text = "Keine Angst"
  },
  AvgVideoCaption_131662_Content_147 = {
    Text = "Kohleball, umarmen"
  },
  AvgVideoCaption_131662_Content_148 = {
    Text = "Kohleball, umarmen, glücklich"
  },
  AvgVideoCaption_131662_Content_149 = {
    Text = "Mosk, glücklich"
  },
  AvgVideoCaption_131662_Content_15 = {
    Text = "Ich werde dir keinen Schaden zufügen"
  },
  AvgVideoCaption_131662_Content_16 = {
    Text = "Du kannst verstehen, was ich sage, oder?"
  },
  AvgVideoCaption_131662_Content_17 = {
    Text = "Mach dir keine Sorgen, hier ist es sicher"
  },
  AvgVideoCaption_131662_Content_18 = {
    Text = "Wir kommen von der Misa-Akademie, ich bin die Forscherin Erin Caldwell des Erweckungssystems"
  },
  AvgVideoCaption_131662_Content_19 = {
    Text = "Was hast du in diesem Wirbel erlebt?"
  },
  AvgVideoCaption_131662_Content_2 = {
    Text = "Geräusche, Geräusche, so still..."
  },
  AvgVideoCaption_131662_Content_20 = {
    Text = "Wir benötigen dringend deine Informationen, um den Fall wiederherzustellen"
  },
  AvgVideoCaption_131662_Content_21 = {
    Text = "Bitte sprich in dieses Mikrofon mit dem Silberkern der Festung"
  },
  AvgVideoCaption_131662_Content_22 = {
    Text = "Später werden wir versuchen, die Inhalte der Aufzeichnung mit @1 Technologie zu analysieren"
  },
  AvgVideoCaption_131662_Content_23 = {
    Text = "Was ist dort passiert...?"
  },
  AvgVideoCaption_131662_Content_24 = {Text = "Schiff"},
  AvgVideoCaption_131662_Content_25 = {Text = "Meerwasser"},
  AvgVideoCaption_131662_Content_26 = {
    Text = "Das Schiff im Meer..."
  },
  AvgVideoCaption_131662_Content_27 = {
    Text = "Fouetté..."
  },
  AvgVideoCaption_131662_Content_28 = {
    Text = "Fallen, niemals fallen, kein Oben, kein Unten, links und rechts... nichts mehr"
  },
  AvgVideoCaption_131662_Content_29 = {
    Text = "Alles dreht sich..."
  },
  AvgVideoCaption_131662_Content_3 = {
    Text = "Stillstand Stillstand Stillstand Stillstand Stillstand Stillstand"
  },
  AvgVideoCaption_131662_Content_30 = {
    Text = "...Ich will mich nicht mehr erinnern, ich bin nicht mehr da"
  },
  AvgVideoCaption_131662_Content_31 = {
    Text = "Großartig..."
  },
  AvgVideoCaption_131662_Content_32 = {
    Text = "Aber, aber... in meinen Ohren, das Geräusch ist noch da..."
  },
  AvgVideoCaption_131662_Content_33 = {Text = "Warum?"},
  AvgVideoCaption_131662_Content_34 = {
    Text = "Kein Geräusch...Wirbel...kein Geräusch"
  },
  AvgVideoCaption_131662_Content_35 = {
    Text = "Aber, Mosk, in deinen Ohren, da ist ein Geräusch, ein sehr, sehr lautes Geräusch"
  },
  AvgVideoCaption_131662_Content_36 = {
    Text = "Mosk... Mosk hofft... dass es nicht die Stimmen in Mosks Kopf sind..."
  },
  AvgVideoCaption_131662_Content_37 = {
    Text = "Seltsam, aber warum? Kohleball, weißt du?"
  },
  AvgVideoCaption_131662_Content_38 = {
    Text = "Ah... ah... richtig"
  },
  AvgVideoCaption_131662_Content_39 = {
    Text = "Ich habe schon..."
  },
  AvgVideoCaption_131662_Content_4 = {
    Text = "Wo ist das, wo bin ich, das Geräusch... die Temperatur... gib mir..."
  },
  AvgVideoCaption_131662_Content_40 = {
    Text = "Nicht mehr dort"
  },
  AvgVideoCaption_131662_Content_41 = {
    Text = "Nein, kein Kohleball mehr"
  },
  AvgVideoCaption_131662_Content_42 = {
    Text = "Wasser, Wasser, aber Wasser..."
  },
  AvgVideoCaption_131662_Content_43 = {
    Text = "Ohr, Wasser, Ohr..."
  },
  AvgVideoCaption_131662_Content_44 = {
    Text = "Ich bin Mi, Sa, Ge"
  },
  AvgVideoCaption_131662_Content_45 = {
    Text = "Aber die Sonne, die Sonne, grell......"
  },
  AvgVideoCaption_131662_Content_46 = {
    Text = "Die Sonne ist wieder hell geworden"
  },
  AvgVideoCaption_131662_Content_47 = {
    Text = "Mama und Papa sagen, die Sonne scheint, Schatten, Position"
  },
  AvgVideoCaption_131662_Content_48 = {
    Text = "Fouetté, Fouetté, Schatten, Fouetté"
  },
  AvgVideoCaption_131662_Content_49 = {
    Text = "Nein, nein! Nein!! Der Schatten dreht sich nicht!!"
  },
  AvgVideoCaption_131662_Content_5 = {
    Text = "Kohleball... Nautila..."
  },
  AvgVideoCaption_131662_Content_50 = {
    Text = "Oben! Unten! Alle drehen sich! Alle drehen sich!!!"
  },
  AvgVideoCaption_131662_Content_51 = {
    Text = "Nein! Nein!! Warum! Warum!!"
  },
  AvgVideoCaption_131662_Content_52 = {
    Text = "Ich bin entkommen! Ich bin entkommen"
  },
  AvgVideoCaption_131662_Content_53 = {
    Text = "Ich... entkommen..."
  },
  AvgVideoCaption_131662_Content_54 = {Text = "Missaga..."},
  AvgVideoCaption_131662_Content_55 = {Text = "Raum..."},
  AvgVideoCaption_131662_Content_56 = {
    Text = "Die Sonne scheint......"
  },
  AvgVideoCaption_131662_Content_57 = {
    Text = "Dreizehn Mal..."
  },
  AvgVideoCaption_131662_Content_58 = {
    Text = "Nein, nein, im Raum gibt es kein Fenster"
  },
  AvgVideoCaption_131662_Content_59 = {
    Text = "Feuerball......"
  },
  AvgVideoCaption_131662_Content_6 = {
    Text = "O-1841 Erwecker"
  },
  AvgVideoCaption_131662_Content_60 = {
    Text = "Wird nicht leuchten! Wird nicht leuchten"
  },
  AvgVideoCaption_131662_Content_61 = {
    Text = "Aaaaaaah——————————"
  },
  AvgVideoCaption_131662_Content_62 = {
    Text = "Wirbel! Wirbel! Wasser! Wasser"
  },
  AvgVideoCaption_131662_Content_63 = {
    Text = "Im Körper! Wasser! Er! Wasser"
  },
  AvgVideoCaption_131662_Content_64 = {
    Text = "Noch da! Noch da! Mosk weiß"
  },
  AvgVideoCaption_131662_Content_65 = {
    Text = "Mosk weiß, dass er noch da ist"
  },
  AvgVideoCaption_131662_Content_66 = {
    Text = "Hilf mir, hilf Mosk..."
  },
  AvgVideoCaption_131662_Content_67 = {
    Text = "Nein, Mosk ist verloren..."
  },
  AvgVideoCaption_131662_Content_68 = {
    Text = "Ich... bin verloren..."
  },
  AvgVideoCaption_131662_Content_69 = {Text = "Ah!"},
  AvgVideoCaption_131662_Content_7 = {
    Text = "Ihr Silberkern wurde im Fusionsriss unter dem Wirbel M-Merskis gefunden"
  },
  AvgVideoCaption_131662_Content_70 = {
    Text = "Ah, ahhhhhh!!!!!"
  },
  AvgVideoCaption_131662_Content_71 = {
    Text = "Puh, puh..."
  },
  AvgVideoCaption_131662_Content_72 = {
    Text = "Flieh, Flucht..."
  },
  AvgVideoCaption_131662_Content_73 = {
    Text = "Gib mich zurück... wirf mich weg... wirf mich weg..."
  },
  AvgVideoCaption_131662_Content_74 = {
    Text = "Mosk... ich will niemandem schaden..."
  },
  AvgVideoCaption_131662_Content_75 = {
    Text = "Mosk hat Angst... eine Person..."
  },
  AvgVideoCaption_131662_Content_76 = {
    Text = "Aber... alle sind gestorben..."
  },
  AvgVideoCaption_131662_Content_77 = {
    Text = "Lachen, essen, wird mir geben..."
  },
  AvgVideoCaption_131662_Content_78 = {
    Text = "Kann nicht haben"
  },
  AvgVideoCaption_131662_Content_79 = {
    Text = "Weg, wir müssen weg! Sonst..."
  },
  AvgVideoCaption_131662_Content_8 = {
    Text = "In der frühen Erwachensphase ist der Erwecker O-1841 die meiste Zeit geistig völlig verloren und zeigt eine starke Zerstörungstendenz"
  },
  AvgVideoCaption_131662_Content_80 = {
    Text = "Ertrinken..."
  },
  AvgVideoCaption_131662_Content_81 = {
    Text = "Kohleball, ich möchte dich sehen"
  },
  AvgVideoCaption_131662_Content_82 = {
    Text = "Freund, ich möchte dich sehen..."
  },
  AvgVideoCaption_131662_Content_83 = {
    Text = "Kohleball, nicht......"
  },
  AvgVideoCaption_131662_Content_84 = {
    Text = "Freund... nein..."
  },
  AvgVideoCaption_131662_Content_85 = {
    Text = "Nein... Bitte nicht..."
  },
  AvgVideoCaption_131662_Content_86 = {
    Text = "Bitte bleib ruhig, Mosk"
  },
  AvgVideoCaption_131662_Content_87 = {
    Text = "Du befindest dich jetzt im Erwecker-Forschungszentrum von Misaq"
  },
  AvgVideoCaption_131662_Content_88 = {
    Text = "Hier ist es sehr sicher"
  },
  AvgVideoCaption_131662_Content_89 = {
    Text = "Wir haben deine Sprache vorläufig analysiert"
  },
  AvgVideoCaption_131662_Content_9 = {
    Text = "Nur in wenigen Momenten spreche ich mit @2 und gerate in einen schweren Deliriumzustand"
  },
  AvgVideoCaption_131662_Content_90 = {
    Text = "Aber es gibt immer noch viele schwer verständliche Wörter"
  },
  AvgVideoCaption_131662_Content_91 = {
    Text = "Deshalb müssen wir......"
  },
  AvgVideoCaption_131662_Content_92 = {
    Text = "Nein... nein, Gesicht, Gesicht"
  },
  AvgVideoCaption_131662_Content_93 = {
    Text = "Kein Gesicht! Ich kann nichts sehen"
  },
  AvgVideoCaption_131662_Content_94 = {
    Text = "Wasser bedeckt, Verzerrung! Ich kann nichts sehen"
  },
  AvgVideoCaption_131662_Content_95 = {
    Text = "Monster! Monster! Nein!!!!"
  },
  AvgVideoCaption_131662_Content_96 = {
    Text = "Ihr, gute Leute..."
  },
  AvgVideoCaption_131662_Content_97 = {
    Text = "Monster... Monster..."
  },
  AvgVideoCaption_131662_Content_98 = {
    Text = "Normal, Gesicht..."
  },
  AvgVideoCaption_131662_Content_99 = {
    Text = "Verzerrung...Wirbel..."
  },
  AvgVideoCaption_134291_Content_1 = {Text = "Schicksal"},
  AvgVideoCaption_134291_Content_10 = {
    Text = "Sie alle wurden von meiner Hand gewoben"
  },
  AvgVideoCaption_134291_Content_11 = {
    Text = "Sie alle ..."
  },
  AvgVideoCaption_134291_Content_12 = {
    Text = "Hehehehe ..."
  },
  AvgVideoCaption_134291_Content_13 = {
    Text = "Niemand kann sich dem Schicksal widersetzen, liebe Schwester"
  },
  AvgVideoCaption_134291_Content_14 = {
    Text = "Wir werden letztlich zu einem weiteren Faden zerfallen"
  },
  AvgVideoCaption_134291_Content_15 = {
    Text = "Alle Schicksalspfade sind bereits vorherbestimmt"
  },
  AvgVideoCaption_134291_Content_16 = {Text = "Richterin"},
  AvgVideoCaption_134291_Content_17 = {Text = "Erlöserin"},
  AvgVideoCaption_134291_Content_18 = {Text = "Herrin"},
  AvgVideoCaption_134291_Content_19 = {
    Text = "Gefangene ..."
  },
  AvgVideoCaption_134291_Content_2 = {
    Text = "Eine kleine und zerbrechliche Gottheit"
  },
  AvgVideoCaption_134291_Content_20 = {
    Text = "Die Rolle, die mir zusteht"
  },
  AvgVideoCaption_134291_Content_21 = {
    Text = "war längst nicht mehr meine Wahl"
  },
  AvgVideoCaption_134291_Content_22 = {
    Text = "Doch auch du hast keine Wahl ..."
  },
  AvgVideoCaption_134291_Content_23 = {
    Text = "Liebes Schicksal"
  },
  AvgVideoCaption_134291_Content_24 = {
    Text = "Betritt mit mir gemeinsam"
  },
  AvgVideoCaption_134291_Content_25 = {
    Text = "die Bühne, die uns vorherbestimmt ist"
  },
  AvgVideoCaption_134291_Content_3 = {
    Text = "Sie ließ unzählige Fäden herab"
  },
  AvgVideoCaption_134291_Content_4 = {
    Text = "um der Welt vorbestimmte Bahnen zu schaffen"
  },
  AvgVideoCaption_134291_Content_5 = {
    Text = "um den Kindern die weichste Wiege zu weben"
  },
  AvgVideoCaption_134291_Content_6 = {Text = "Dichtung"},
  AvgVideoCaption_134291_Content_7 = {Text = "Tanzen"},
  AvgVideoCaption_134291_Content_8 = {Text = "Krieg ..."},
  AvgVideoCaption_134291_Content_9 = {Text = "Der Alltag"},
  AvgVideoCaption_134292_Content_1 = {
    Text = "Komm zu mir, Nefraea."
  },
  AvgVideoCaption_134292_Content_10 = {
    Text = "Die dort auf der Bühne sieht so traurig aus..."
  },
  AvgVideoCaption_134292_Content_100 = {
    Text = "Selbst wenn dieser Preis..."
  },
  AvgVideoCaption_134292_Content_101 = {
    Text = "von unerträglicher Schwere ist."
  },
  AvgVideoCaption_134292_Content_102 = {
    Text = "Du würdest also lieber den Webstuhl für alle Ewigkeit hüten,"
  },
  AvgVideoCaption_134292_Content_103 = {
    Text = "nur um die Welt vor dem Fall in die Dunkelheit zu bewahren..."
  },
  AvgVideoCaption_134292_Content_104 = {
    Text = "Manchmal frage ich mich..."
  },
  AvgVideoCaption_134292_Content_105 = {
    Text = "Glaubst du, ich bin zu stur?"
  },
  AvgVideoCaption_134292_Content_106 = {
    Text = "Ich verstehe dich, Schwester..."
  },
  AvgVideoCaption_134292_Content_107 = {
    Text = "Ich will nur — ich will nicht, dass du so leidest."
  },
  AvgVideoCaption_134292_Content_108 = {
    Text = "Das sollte nicht etwas sein, das du allein trägst..."
  },
  AvgVideoCaption_134292_Content_109 = {Text = "Schwester,"},
  AvgVideoCaption_134292_Content_11 = {
    Text = "Wurde sie von jemandem verlassen, den sie liebte?"
  },
  AvgVideoCaption_134292_Content_110 = {
    Text = "du hast mich heute hierhergebracht, um diese Oper zu sehen..."
  },
  AvgVideoCaption_134292_Content_111 = {
    Text = "war es das, was du mir sagen wolltest?"
  },
  AvgVideoCaption_134292_Content_112 = {
    Text = "Schicksal ist mein langer Käfig, Nefraea."
  },
  AvgVideoCaption_134292_Content_113 = {
    Text = "Worum ich letztlich bitte, ist nur, dass du meine Einsamkeit siehst..."
  },
  AvgVideoCaption_134292_Content_114 = {
    Text = "als die eine Seele, der ich wahrhaft vertraue."
  },
  AvgVideoCaption_134292_Content_115 = {Text = "Vertrauen?"},
  AvgVideoCaption_134292_Content_116 = {
    Text = "Aber... ich scheine deine Fäden immer durcheinanderzubringen."
  },
  AvgVideoCaption_134292_Content_117 = {
    Text = "Ich tue es nicht absichtlich..."
  },
  AvgVideoCaption_134292_Content_118 = {
    Text = "aber jedes Mal, wenn ich dir nahekomme, störe ich etwas..."
  },
  AvgVideoCaption_134292_Content_119 = {
    Text = "Diese ordentlichen, glänzenden Fäden—"
  },
  AvgVideoCaption_134292_Content_12 = {
    Text = "Menschliches Leid"
  },
  AvgVideoCaption_134292_Content_120 = {
    Text = "sie lösen sich, wann immer ich in der Nähe bin..."
  },
  AvgVideoCaption_134292_Content_121 = {
    Text = "Es tut mir leid, Schwester. Ich weiß nicht, warum das geschieht..."
  },
  AvgVideoCaption_134292_Content_122 = {
    Text = "Deine Schönheit war nie deine Schuld,"
  },
  AvgVideoCaption_134292_Content_123 = {
    Text = "Weil du wunderbar bist, Nefraea."
  },
  AvgVideoCaption_134292_Content_124 = {
    Text = "Und dieser Käfig des Schicksals ist eifersüchtig auf schöne Dinge."
  },
  AvgVideoCaption_134292_Content_125 = {
    Text = "Ha... haha... hahaha..."
  },
  AvgVideoCaption_134292_Content_126 = {
    Text = "liebe Schwester."
  },
  AvgVideoCaption_134292_Content_127 = {
    Text = "Meine Liebe zu dir, meine Fürsorge für dich—nichts davon hat je nachgelassen, ganz gleich, wie sehr wir uns unterscheiden mögen."
  },
  AvgVideoCaption_134292_Content_128 = {
    Text = "Ich liebe zutiefst all die Leben, über die ich wache,"
  },
  AvgVideoCaption_134292_Content_129 = {
    Text = "so wie ich dich liebe—die Einzige, die mich jemals wahrhaft verstanden hat..."
  },
  AvgVideoCaption_134292_Content_13 = {
    Text = "reicht tiefer als Liebe und Verlassenwerden,"
  },
  AvgVideoCaption_134292_Content_130 = {
    Text = "Danke, Schwester..."
  },
  AvgVideoCaption_134292_Content_131 = {
    Text = "...So schlafe nun, im Tode, liebe Schwester."
  },
  AvgVideoCaption_134292_Content_132 = {
    Text = "Schwe-Schwester?"
  },
  AvgVideoCaption_134292_Content_133 = {
    Text = "Warum... <Italic:warum?>"
  },
  AvgVideoCaption_134292_Content_134 = {
    Text = "Es tut mir leid, Nefraea..."
  },
  AvgVideoCaption_134292_Content_135 = {
    Text = "Um das Netz des Schicksals zu bewahren,"
  },
  AvgVideoCaption_134292_Content_136 = {
    Text = "muss ich abtrennen, was den falschen Weg genommen hat."
  },
  AvgVideoCaption_134292_Content_137 = {
    Text = "Der unerträgliche Preis... also dann..."
  },
  AvgVideoCaption_134292_Content_138 = {
    Text = "Ich bin der Preis, den du zahlen musstest, nicht wahr?"
  },
  AvgVideoCaption_134292_Content_139 = {
    Text = "Heh... Hehehe..."
  },
  AvgVideoCaption_134292_Content_14 = {
    Text = "Liebe Nefraea."
  },
  AvgVideoCaption_134292_Content_140 = {
    Text = "Wähle, was zur Größe führt,"
  },
  AvgVideoCaption_134292_Content_141 = {
    Text = "verwirf, was schmutzig und bedeutungslos ist —"
  },
  AvgVideoCaption_134292_Content_142 = {
    Text = "das bist du, nicht wahr... das war schon immer deine Wahl..."
  },
  AvgVideoCaption_134292_Content_143 = {
    Text = "Heuchlerin. Verräterin... Du hast mich verraten..."
  },
  AvgVideoCaption_134292_Content_144 = {
    Text = "Du hast mich verraten..."
  },
  AvgVideoCaption_134292_Content_145 = {
    Text = "Du hast dich selbst verraten, Schwester..."
  },
  AvgVideoCaption_134292_Content_146 = {
    Text = "Verachte mich."
  },
  AvgVideoCaption_134292_Content_147 = {
    Text = "Verlasse mich."
  },
  AvgVideoCaption_134292_Content_148 = {
    Text = "Geh an einen Ort, wo du nicht leiden musst für das, was dir lieb ist,"
  },
  AvgVideoCaption_134292_Content_149 = {Text = "Nefraea..."},
  AvgVideoCaption_134292_Content_15 = {Text = "Sie..."},
  AvgVideoCaption_134292_Content_150 = {
    Text = "Dies — <Italic:all dies> — ist das Schicksal, dem ich nicht entkommen kann."
  },
  AvgVideoCaption_134292_Content_151 = {
    Text = "Heuchlerin. Verräterin... Du hast mich verraten..."
  },
  AvgVideoCaption_134292_Content_152 = {
    Text = "Du hast mich verraten..."
  },
  AvgVideoCaption_134292_Content_153 = {
    Text = "Du hast dich selbst verraten!"
  },
  AvgVideoCaption_134292_Content_154 = {
    Text = "Eines Tages wirst du alles zerstören, was dir je lieb war..."
  },
  AvgVideoCaption_134292_Content_155 = {
    Text = "zusammen mit diesem Schicksal, über das du dich selbst belogen hast... Schwester..."
  },
  AvgVideoCaption_134292_Content_156 = {
    Text = "Hass mich, Nefraea."
  },
  AvgVideoCaption_134292_Content_157 = {
    Text = "Doch jede Gnade, die diese Welt bereithält,"
  },
  AvgVideoCaption_134292_Content_158 = {
    Text = "wird am Ende durch ein Schicksal vergolten, das keine Gnade kennt."
  },
  AvgVideoCaption_134292_Content_159 = {
    Text = "Das Rad dreht sich. Es hat sich schon immer gedreht."
  },
  AvgVideoCaption_134292_Content_16 = {
    Text = "Sie weint... über ihre eigene Hilflosigkeit gegenüber dem Schicksal."
  },
  AvgVideoCaption_134292_Content_160 = {
    Text = "Mir bleibt keine Wahl, als dich gehen zu lassen — wieder und wieder und wieder."
  },
  AvgVideoCaption_134292_Content_161 = {
    Text = "Und doch, solange ich mich noch erinnere, warum ich webe..."
  },
  AvgVideoCaption_134292_Content_162 = {
    Text = "selbst ohne dein Verständnis,"
  },
  AvgVideoCaption_134292_Content_163 = {
    Text = "selbst nachdem ich alles aufgegeben habe —"
  },
  AvgVideoCaption_134292_Content_164 = {
    Text = "würde ich es dennoch tun."
  },
  AvgVideoCaption_134292_Content_165 = {
    Text = "Das ist die Last, die ich als Weberin trage."
  },
  AvgVideoCaption_134292_Content_166 = {
    Text = "Das ist die Einsamkeit, in der ich wandeln muss."
  },
  AvgVideoCaption_134292_Content_167 = {
    Text = "Lass das Schicksal..."
  },
  AvgVideoCaption_134292_Content_168 = {
    Text = "uns beide für immer und gänzlich aneinander binden."
  },
  AvgVideoCaption_134292_Content_17 = {
    Text = "Sie klingt nicht besonders klug."
  },
  AvgVideoCaption_134292_Content_18 = {
    Text = "Sie müsste nur zu jemandem wie dir beten — jemandem, der das Schicksal ändern kann."
  },
  AvgVideoCaption_134292_Content_19 = {
    Text = "Nicht wahr, Schwester?"
  },
  AvgVideoCaption_134292_Content_2 = {
    Text = "Schwester, das ist das erste Mal, dass du mich in dein Theater mitgenommen hast!"
  },
  AvgVideoCaption_134292_Content_20 = {
    Text = "Das Schicksal hat mir die Macht zu weben verliehen."
  },
  AvgVideoCaption_134292_Content_21 = {
    Text = "Doch jeder Seele ihren Frieden zu schenken... das übersteigt selbst meine Kraft."
  },
  AvgVideoCaption_134292_Content_22 = {
    Text = "Es gibt wunderschöne Schicksale auf dieser Welt."
  },
  AvgVideoCaption_134292_Content_23 = {
    Text = "Und doch gibt es immer jene, die an eines anderen Stelle den Wahnsinn und das Verderben ertragen müssen, das eigentlich anderswo hätte niedergehen sollen."
  },
  AvgVideoCaption_134292_Content_24 = {
    Text = "Ich hüte dieses Netz des Schicksals,"
  },
  AvgVideoCaption_134292_Content_25 = {
    Text = "spinne die Freuden und Leiden unzähliger Leben zu Fäden."
  },
  AvgVideoCaption_134292_Content_26 = {
    Text = "Und doch, wenn alles gesagt ist..."
  },
  AvgVideoCaption_134292_Content_27 = {
    Text = "bin ich nichts weiter als eine unbeholfene Darstellerin in meinem eigenen Stück."
  },
  AvgVideoCaption_134292_Content_28 = {
    Text = "Das kann nicht sein —"
  },
  AvgVideoCaption_134292_Content_29 = {
    Text = "du bist jemand, der über das Schicksal gebietet, Schwester!"
  },
  AvgVideoCaption_134292_Content_3 = {
    Text = "Was sehen wir uns an? Ein Theaterstück? Ein Ballett?"
  },
  AvgVideoCaption_134292_Content_30 = {
    Text = "Am Ende eines jeden Fadens liegt die chaotische Leere."
  },
  AvgVideoCaption_134292_Content_31 = {
    Text = "Die Herrin des Schicksals"
  },
  AvgVideoCaption_134292_Content_32 = {
    Text = "ist am Ende nur dessen Dienerin..."
  },
  AvgVideoCaption_134292_Content_33 = {Text = "Nefraea"},
  AvgVideoCaption_134292_Content_34 = {Text = "Nefraea,"},
  AvgVideoCaption_134292_Content_35 = {
    Text = "vielleicht..."
  },
  AvgVideoCaption_134292_Content_36 = {
    Text = "kannst du, und nur du, diese Einsamkeit wahrhaft verstehen."
  },
  AvgVideoCaption_134292_Content_37 = {
    Text = "Selbst du also... hast Dinge, die du nicht tun kannst..."
  },
  AvgVideoCaption_134292_Content_38 = {
    Text = "Ich verstehe das alles nicht wirklich..."
  },
  AvgVideoCaption_134292_Content_39 = {
    Text = "aber ganz gleich, was geschieht,"
  },
  AvgVideoCaption_134292_Content_4 = {
    Text = "Sag es mir!"
  },
  AvgVideoCaption_134292_Content_40 = {
    Text = "ich werde immer an deiner Seite sein, Schwester!"
  },
  AvgVideoCaption_134292_Content_41 = {
    Text = "Ich glaube, ich beginne zu verstehen, Schwester..."
  },
  AvgVideoCaption_134292_Content_42 = {
    Text = "Schwester..."
  },
  AvgVideoCaption_134292_Content_43 = {
    Text = "Diese Sängerin —"
  },
  AvgVideoCaption_134292_Content_44 = {
    Text = "ein welkes Blatt ohne Zuflucht,"
  },
  AvgVideoCaption_134292_Content_45 = {
    Text = "geworfen, wohin das Schicksal es für richtig hält..."
  },
  AvgVideoCaption_134292_Content_46 = {
    Text = "Wie furchtbar traurig..."
  },
  AvgVideoCaption_134292_Content_47 = {Text = "Nefraea"},
  AvgVideoCaption_134292_Content_48 = {
    Text = "Wenn es an dir wäre, es zu schreiben,"
  },
  AvgVideoCaption_134292_Content_49 = {
    Text = "welches Schicksal würdest du ihr geben?"
  },
  AvgVideoCaption_134292_Content_5 = {
    Text = "Pst. Es fängt gleich an."
  },
  AvgVideoCaption_134292_Content_50 = {
    Text = "Hmm. Ich glaube, ich würde ihr die grandioseste Tragödie von allen schreiben!"
  },
  AvgVideoCaption_134292_Content_51 = {
    Text = "Eine Frau, die verstoßen wurde."
  },
  AvgVideoCaption_134292_Content_52 = {
    Text = "Eine Nebendarstellerin, dazu geschrieben, im Schatten einer anderen zu stehen..."
  },
  AvgVideoCaption_134292_Content_53 = {
    Text = "Wenn ich ihre Geschichte umschreiben könnte, würde ich alles in Flammen setzen—"
  },
  AvgVideoCaption_134292_Content_54 = {
    Text = "alles, was sie quält, alles, was sie fesselt,"
  },
  AvgVideoCaption_134292_Content_55 = {
    Text = "jede einzelne Ungerechtigkeit—alles zu Asche verbrennen!"
  },
  AvgVideoCaption_134292_Content_56 = {
    Text = "Etwas Qualvolles, etwas Wildes—voller Lärm und Zusammenbruch..."
  },
  AvgVideoCaption_134292_Content_57 = {
    Text = "Diese Art von Schönheit, die Art, die sich selbst zu nichts verbrennt,"
  },
  AvgVideoCaption_134292_Content_58 = {
    Text = "das ist das einzige Ende, das zu ihr passt!"
  },
  AvgVideoCaption_134292_Content_59 = {
    Text = "Ja, Nefraea."
  },
  AvgVideoCaption_134292_Content_6 = {
    Text = "Heute Abend... ist eine Oper."
  },
  AvgVideoCaption_134292_Content_60 = {
    Text = "Du glaubst immer noch,"
  },
  AvgVideoCaption_134292_Content_61 = {
    Text = "dass das Schicksal in Zerstörung enden sollte."
  },
  AvgVideoCaption_134292_Content_62 = {
    Text = "Dass um eines schönen Bildes willen, das du im Herzen trägst—"
  },
  AvgVideoCaption_134292_Content_63 = {
    Text = "um eines perfekten Abschlusses willen—"
  },
  AvgVideoCaption_134292_Content_64 = {
    Text = "es sich lohnt, die Welt im Verderben enden zu lassen..."
  },
  AvgVideoCaption_134292_Content_65 = {
    Text = "Was—das habe ich überhaupt nicht gemeint!"
  },
  AvgVideoCaption_134292_Content_66 = {
    Text = "Ich liebe einfach die Bitterkeit, die kommt, nachdem die Leidenschaft verglüht ist..."
  },
  AvgVideoCaption_134292_Content_67 = {
    Text = "Genauso wie du ein vollkommenes und perfektes Ende liebst!"
  },
  AvgVideoCaption_134292_Content_68 = {
    Text = "Aber Schwester,"
  },
  AvgVideoCaption_134292_Content_69 = {
    Text = "wenn das Schicksal ohnehin zur Zerstörung bestimmt ist, warum sich dagegen wehren?"
  },
  AvgVideoCaption_134292_Content_7 = {
    Text = "Eine Frau, gefangen vom Schicksal,"
  },
  AvgVideoCaption_134292_Content_70 = {
    Text = "Sie dem Untergang entgegengehen zu lassen, der für sie geschrieben steht... liegt darin nicht eine gewisse Schönheit?"
  },
  AvgVideoCaption_134292_Content_71 = {
    Text = "Das Rad des Schicksals dreht sich ohne Erbarmen,"
  },
  AvgVideoCaption_134292_Content_72 = {
    Text = "und selbst du kannst nicht ändern, wo es endet."
  },
  AvgVideoCaption_134292_Content_73 = {
    Text = "Warum das Netz weiter pflegen? Warum an etwas so Undankbarem festhalten?"
  },
  AvgVideoCaption_134292_Content_74 = {
    Text = "Das Rad des Schicksals ist in der Tat ohne Erbarmen."
  },
  AvgVideoCaption_134292_Content_75 = {
    Text = "Doch es dreht sich nicht, um zu zerstören."
  },
  AvgVideoCaption_134292_Content_76 = {
    Text = "Es dreht sich, damit das Leben in seiner Ordnung fortbestehen kann."
  },
  AvgVideoCaption_134292_Content_77 = {
    Text = "Sieh dir jene auf der Bühne an."
  },
  AvgVideoCaption_134292_Content_78 = {
    Text = "Vom Schicksal verlassen,"
  },
  AvgVideoCaption_134292_Content_79 = {
    Text = "vom Leid zermahlen,"
  },
  AvgVideoCaption_134292_Content_8 = {
    Text = "die auf ihre Erlösung wartet."
  },
  AvgVideoCaption_134292_Content_80 = {
    Text = "weinend über ihre eigene Hilflosigkeit und ihren Untergang..."
  },
  AvgVideoCaption_134292_Content_81 = {
    Text = "Und doch hat sie niemals losgelassen,"
  },
  AvgVideoCaption_134292_Content_82 = {
    Text = "selbst als sie aufhörte, an ein schönes Ende zu glauben."
  },
  AvgVideoCaption_134292_Content_83 = {
    Text = "Wenn sie loslassen würde —"
  },
  AvgVideoCaption_134292_Content_84 = {
    Text = "dann würde all das, jedes Schicksal, das sie je getragen hat, jegliche Bedeutung verlieren."
  },
  AvgVideoCaption_134292_Content_85 = {
    Text = "Inmitten all der Trostlosigkeit"
  },
  AvgVideoCaption_134292_Content_86 = {
    Text = "muss es immer jemanden geben, der die verbliebene Hoffnung beschützt,"
  },
  AvgVideoCaption_134292_Content_87 = {
    Text = "liebe Schwester."
  },
  AvgVideoCaption_134292_Content_88 = {
    Text = "Ich glaube, ich verstehe jetzt, Schwester..."
  },
  AvgVideoCaption_134292_Content_89 = {
    Text = "Diejenige, die auf jener Bühne weint — das bist du, nicht wahr?"
  },
  AvgVideoCaption_134292_Content_9 = {
    Text = "<Italic:„Cruda sorte,\"> grausames Schicksal..."
  },
  AvgVideoCaption_134292_Content_90 = {
    Text = "Ich habe zugesehen, wie die Welt unter Leid zermalmt wurde,"
  },
  AvgVideoCaption_134292_Content_91 = {
    Text = "Tag für Tag — jede Seele mitgezogen in jenem stillen, sich wiederholenden Sog hin zu ihrem Ende."
  },
  AvgVideoCaption_134292_Content_92 = {
    Text = "Diese endlose Dunkelheit. Diese grenzenlose Einsamkeit..."
  },
  AvgVideoCaption_134292_Content_93 = {
    Text = "Den Lebenden eine solche Zukunft zurückzugeben,"
  },
  AvgVideoCaption_134292_Content_94 = {
    Text = "wäre nichts Geringeres als ein Verrat am Leben selbst."
  },
  AvgVideoCaption_134292_Content_95 = {
    Text = "Gerade weil mir jeder Herzschlag kostbar ist,"
  },
  AvgVideoCaption_134292_Content_96 = {
    Text = "jede fallende Träne..."
  },
  AvgVideoCaption_134292_Content_97 = {
    Text = "kann ich es nicht über mich bringen, die Welt in die Leere gleiten zu lassen."
  },
  AvgVideoCaption_134292_Content_98 = {
    Text = "Dies ist meine Entscheidung."
  },
  AvgVideoCaption_134292_Content_99 = {
    Text = "Und ich werde ihren Preis bezahlen."
  },
  AvgVideoCaption_139854_Content_1 = {
    Text = "Erster Brief"
  },
  AvgVideoCaption_139854_Content_10 = {
    Text = "Das ist wohl das, was man „Liebe\" nennt"
  },
  AvgVideoCaption_139854_Content_11 = {
    Text = "Jede Zeit hat ihren Moment des Endes."
  },
  AvgVideoCaption_139854_Content_12 = {
    Text = "Geschichten sind nicht ewig."
  },
  AvgVideoCaption_139854_Content_13 = {
    Text = "Das gegenwärtige Ich scheint genau hier zu sein, in diesem Moment."
  },
  AvgVideoCaption_139854_Content_14 = {
    Text = "Ich empfinde es immer wieder zutiefst,"
  },
  AvgVideoCaption_139854_Content_15 = {
    Text = "Das ist wohl ein Universum ohne @3"
  },
  AvgVideoCaption_139854_Content_16 = {
    Text = "Dritter Brief"
  },
  AvgVideoCaption_139854_Content_17 = {
    Text = "Die Dinge über „Ich\" kommen mir langsam wieder in Erinnerung."
  },
  AvgVideoCaption_139854_Content_18 = {
    Text = "Ich habe das Gefühl, auch über die gegenwärtigen Dinge viel mehr zu verstehen."
  },
  AvgVideoCaption_139854_Content_19 = {
    Text = "Die Zivilisation hier wirkt ziemlich rückständig."
  },
  AvgVideoCaption_139854_Content_2 = {
    Text = "In diesem Moment ist mein Bewusstsein genau hier."
  },
  AvgVideoCaption_139854_Content_20 = {
    Text = "Aber auch das hat seine eigenen interessanten Seiten. Ich mag es nicht unbedingt nicht."
  },
  AvgVideoCaption_139854_Content_21 = {
    Text = "Ich dachte, die Technologie wäre etwas weiter entwickelt..."
  },
  AvgVideoCaption_139854_Content_22 = {
    Text = "Verglichen damit habe ich das Gefühl, dass es etwas Wichtigeres gibt. Was könnte das nur sein?"
  },
  AvgVideoCaption_139854_Content_23 = {
    Text = "Etwas sehr Wichtiges. Eine sehr kostbare Person."
  },
  AvgVideoCaption_139854_Content_24 = {
    Text = "Wenn ich es nicht verstehe, werde ich von Unruhe erfasst, aber ich möchte trotzdem mehr erfahren."
  },
  AvgVideoCaption_139854_Content_25 = {
    Text = "Ich möchte es schnell wissen. Ich möchte schnell treffen. Was ist das nur?"
  },
  AvgVideoCaption_139854_Content_26 = {
    Text = "Allein der Gedanke daran macht mich sehr glücklich."
  },
  AvgVideoCaption_139854_Content_27 = {
    Text = "Es wäre so schön, wenn du mich finden könntest..."
  },
  AvgVideoCaption_139854_Content_28 = {
    Text = "Der vierte Brief"
  },
  AvgVideoCaption_139854_Content_29 = {
    Text = "Allerlei Erinnerungen strömten herein."
  },
  AvgVideoCaption_139854_Content_3 = {
    Text = "Hier ist es fremd und weit."
  },
  AvgVideoCaption_139854_Content_30 = {
    Text = "Als würde man von einer gewaltigen Stärke überwältigt"
  },
  AvgVideoCaption_139854_Content_31 = {
    Text = "Eisig kalt, als würde der Körper zerrissen werden"
  },
  AvgVideoCaption_139854_Content_32 = {
    Text = "Überglücklich, als würde der ganze Körper glühen"
  },
  AvgVideoCaption_139854_Content_33 = {
    Text = "Erinnerungen voller Horror, Erinnerungen voller Freude, Erinnerungen voller Glück, Erinnerungen voller Trauer"
  },
  AvgVideoCaption_139854_Content_34 = {
    Text = "Doch die wichtigste Erinnerung ist nur eine einzige."
  },
  AvgVideoCaption_139854_Content_35 = {
    Text = "Die Erinnerung, die ich gemeinsam mit dir, der mir so wichtig bist, geteilt habe."
  },
  AvgVideoCaption_139854_Content_36 = {
    Text = "Wo mag diese Erinnerung wohl sein..."
  },
  AvgVideoCaption_139854_Content_37 = {
    Text = "Der fünfte Brief"
  },
  AvgVideoCaption_139854_Content_38 = {
    Text = "Ein Ort, so weit und offen wie eine Wüste."
  },
  AvgVideoCaption_139854_Content_39 = {
    Text = "Ringsum kein einziger Grashalm, kein einziger Baum."
  },
  AvgVideoCaption_139854_Content_4 = {
    Text = "Bist du auch irgendwo auf diesem Planeten?"
  },
  AvgVideoCaption_139854_Content_40 = {
    Text = "Wenn ein Löwenzahnsamen in eine solche Wüste fallen würde."
  },
  AvgVideoCaption_139854_Content_41 = {
    Text = "Vom Wind getragen, weit, weit weg von der Heimat,"
  },
  AvgVideoCaption_139854_Content_42 = {
    Text = "was mag dieses kleine Samenkorn wohl denken?"
  },
  AvgVideoCaption_139854_Content_43 = {
    Text = "Wenn in jener Wüste — auch nur ein einziger Mensch"
  },
  AvgVideoCaption_139854_Content_44 = {
    Text = "wüsste, dass jemand die Blumen liebt,"
  },
  AvgVideoCaption_139854_Content_45 = {
    Text = "die Löwenzahnblüten sind so wunderschön, so sagend,"
  },
  AvgVideoCaption_139854_Content_46 = {
    Text = "wenn man immer an meiner Seite bleiben könnte,"
  },
  AvgVideoCaption_139854_Content_47 = {
    Text = "für immer, an meiner Seite,"
  },
  AvgVideoCaption_139854_Content_48 = {
    Text = "wenn du da wärst......"
  },
  AvgVideoCaption_139854_Content_49 = {
    Text = "Vielen Dank..."
  },
  AvgVideoCaption_139854_Content_5 = {
    Text = "Zweiter Brief"
  },
  AvgVideoCaption_139854_Content_50 = {
    Text = "Ich werde es nicht vergessen......"
  },
  AvgVideoCaption_139854_Content_6 = {
    Text = "Ich erinnere mich an die Begegnung mit jemandem, der mir wichtig war."
  },
  AvgVideoCaption_139854_Content_7 = {
    Text = "In diesem Blick lag nur ein Hauch von Überraschung..."
  },
  AvgVideoCaption_139854_Content_8 = {
    Text = "Keine Angst, keine Gier"
  },
  AvgVideoCaption_139854_Content_9 = {
    Text = "Immer so sanft zu mir"
  },
  AvgVideoCaption_139855_Content_1 = {
    Text = "Erinnerst du dich an mich?"
  },
  AvgVideoCaption_139855_Content_2 = {
    Text = "Wenn die Liebe Caro wachsen lässt"
  },
  AvgVideoCaption_139855_Content_3 = {
    Text = "Das ist die unsere"
  },
  AvgVideoCaption_139855_Content_4 = {Text = "Schöne"},
  AvgVideoCaption_139855_Content_5 = {
    Text = "und doch grausame Welt"
  },
  AvgVideoCaption_139855_Content_6 = {
    Text = "Hehe, hehehehe"
  },
  AvgVideoCaption_139855_Content_7 = {Text = "Und noch"},
  AvgVideoCaption_139855_Content_8 = {
    Text = "das kleine Wunder"
  },
  AvgVideoCaption_139855_Content_9 = {
    Text = "namens Wiedersehen"
  },
  AvgVideoCaption_143591_Content_1 = {
    Text = "Zeig nicht dieses Emoji"
  },
  AvgVideoCaption_143591_Content_10 = {
    Text = "Vielleicht hättest du von mir, der ich noch in Wut war, wirklich Befriedigung erhalten"
  },
  AvgVideoCaption_143591_Content_11 = {
    Text = "Glaub mir, ich habe Dunkelheit, Schmerz und die Trennung von Blutsverwandten ausprobiert"
  },
  AvgVideoCaption_143591_Content_12 = {
    Text = "Ich habe auch versucht, Sanga zusammen mit euren Knochen wachsen zu lassen"
  },
  AvgVideoCaption_143591_Content_13 = {
    Text = "Das Meerwasser eure Haut verfallt zu lassen"
  },
  AvgVideoCaption_143591_Content_14 = {
    Text = "Seepocken euer Caro zermürben zu lassen"
  },
  AvgVideoCaption_143591_Content_15 = {
    Text = "Ich dachte, je mehr ihr leidet"
  },
  AvgVideoCaption_143591_Content_16 = {
    Text = "Desto mehr würde mein Schmerz nachlassen"
  },
  AvgVideoCaption_143591_Content_17 = {
    Text = "Doch dem war nicht so"
  },
  AvgVideoCaption_143591_Content_18 = {
    Text = "Ich habe einen Fehler gemacht"
  },
  AvgVideoCaption_143591_Content_19 = {
    Text = "Mein Fehler"
  },
  AvgVideoCaption_143591_Content_2 = {
    Text = "Ich kenne eure armseligen und lächerlichen absurden Gedanken"
  },
  AvgVideoCaption_143591_Content_20 = {
    Text = "Er rührt daher, dass eure Dummheit und euer blinder Glaube unbegreifliche Horror-Katastrophen verbreitet haben"
  },
  AvgVideoCaption_143591_Content_21 = {
    Text = "hat alles in diesen Zustand gebracht"
  },
  AvgVideoCaption_143591_Content_22 = {
    Text = "Ich betrachte euch immer noch als Menschen"
  },
  AvgVideoCaption_143591_Content_23 = {
    Text = "Je unreiner der Schmerz"
  },
  AvgVideoCaption_143591_Content_24 = {
    Text = "desto mehr wird er zur Belohnung für euch dreckiges Gesindel"
  },
  AvgVideoCaption_143591_Content_25 = {
    Text = "Ob körperlicher Schmerz"
  },
  AvgVideoCaption_143591_Content_26 = {
    Text = "oder seelische Qual"
  },
  AvgVideoCaption_143591_Content_27 = {
    Text = "all das lässt euch glauben, eure Opfergabe sei unermesslich erhaben"
  },
  AvgVideoCaption_143591_Content_28 = {
    Text = "dass euer widerlicher und niederträchtiger Gott euch nach dem Tod in die sogenannte neue Welt führen wird"
  },
  AvgVideoCaption_143591_Content_29 = {Text = "Also..."},
  AvgVideoCaption_143591_Content_3 = {
    Text = "Ich verstehe es"
  },
  AvgVideoCaption_143591_Content_30 = {
    Text = "Ah, genau wie Du es siehst"
  },
  AvgVideoCaption_143591_Content_31 = {
    Text = "Séverine, Tristan, Cyril, Nash... jeder Einzelne"
  },
  AvgVideoCaption_143591_Content_32 = {
    Text = "Die Menschen, von denen Du glaubtest, sie seien gemeinsam mit Dir für euren erhabenen Glauben gestorben"
  },
  AvgVideoCaption_143591_Content_33 = {
    Text = "Sie alle sind hier"
  },
  AvgVideoCaption_143591_Content_34 = {
    Text = "Séverine, die frommere Hingabe und den Wahnsinn als Du besaß und einen würdigen Tod fand"
  },
  AvgVideoCaption_143591_Content_35 = {
    Text = "Der schüchterne, entschlossene Cyril, der seinen eigenen Darm aufgelöst hat..."
  },
  AvgVideoCaption_143591_Content_36 = {
    Text = "Ihr wisst nichts über den Abgrund"
  },
  AvgVideoCaption_143591_Content_37 = {
    Text = "Komm, atme tief durch"
  },
  AvgVideoCaption_143591_Content_38 = {Text = "Entspannen"},
  AvgVideoCaption_143591_Content_39 = {
    Text = "Willkommen zurück"
  },
  AvgVideoCaption_143591_Content_4 = {
    Text = "Ihr wollt ein wenig Schmerz"
  },
  AvgVideoCaption_143591_Content_40 = {
    Text = "Jetzt verstehst Du es, Beute"
  },
  AvgVideoCaption_143591_Content_41 = {
    Text = "Der Abgrund... bringt kein wildes Gemetzel"
  },
  AvgVideoCaption_143591_Content_42 = {
    Text = "Kein Blut und Feuer, wie Du es Dir vorgestellt hast"
  },
  AvgVideoCaption_143591_Content_43 = {
    Text = "Nur Milliarden Tonnen Meerwasser"
  },
  AvgVideoCaption_143591_Content_44 = {
    Text = "uralte Materie, die mit diesem Planeten erwacht ist"
  },
  AvgVideoCaption_143591_Content_45 = {
    Text = "werden euch für ewig niederhalten"
  },
  AvgVideoCaption_143591_Content_46 = {
    Text = "euch einhüllen"
  },
  AvgVideoCaption_143591_Content_47 = {
    Text = "in der grenzenlosen azurblauen Dunkelheit"
  },
  AvgVideoCaption_143591_Content_48 = {Text = "Außer mir"},
  AvgVideoCaption_143591_Content_49 = {
    Text = "kann euch kein Gott an irgendeinen anderen Ort retten"
  },
  AvgVideoCaption_143591_Content_5 = {
    Text = "Eine Strafe, die euch in Ekstase versetzt"
  },
  AvgVideoCaption_143591_Content_50 = {
    Text = "Ihr werdet keine Möglichkeit mehr haben zu fliehen"
  },
  AvgVideoCaption_143591_Content_51 = {
    Text = "Selbst wenn ihr unzählige Male sterbt"
  },
  AvgVideoCaption_143591_Content_52 = {
    Text = "ob wie Tristan"
  },
  AvgVideoCaption_143591_Content_53 = {
    Text = "der sich die eigene Kehle zerriss"
  },
  AvgVideoCaption_143591_Content_54 = {
    Text = "oder ob ihr es dem klugen Nash gleichtut"
  },
  AvgVideoCaption_143591_Content_55 = {
    Text = "und versucht, eure eigene Zunge zu zerkauen"
  },
  AvgVideoCaption_143591_Content_56 = {
    Text = "Probiert es ruhig aus"
  },
  AvgVideoCaption_143591_Content_57 = {
    Text = "Ihr könnt nicht fliehen"
  },
  AvgVideoCaption_143591_Content_58 = {
    Text = "Ihr werdet nur allmählich verfallen"
  },
  AvgVideoCaption_143591_Content_59 = {
    Text = "und wieder erwachen"
  },
  AvgVideoCaption_143591_Content_6 = {
    Text = "Und schließlich mit eurem bedeutungslosen Tod"
  },
  AvgVideoCaption_143591_Content_60 = {
    Text = "Bis ich dessen überdrüssig bin"
  },
  AvgVideoCaption_143591_Content_61 = {
    Text = "wird selbst das Empfinden von Schmerz für euch zum Luxus werden"
  },
  AvgVideoCaption_143591_Content_62 = {
    Text = "In Ebwynnos gilt nur ein Gesetz"
  },
  AvgVideoCaption_143591_Content_63 = {
    Text = "Euer erbärmlicher Retter wird nicht kommen, Beute"
  },
  AvgVideoCaption_143591_Content_64 = {
    Text = "Ich bin die einzige Gottheit"
  },
  AvgVideoCaption_143591_Content_65 = {
    Text = "Kniet nieder und opfert euch dem Ozean"
  },
  AvgVideoCaption_143591_Content_66 = {
    Text = "Und leidet dann ewig im Abgrund"
  },
  AvgVideoCaption_143591_Content_7 = {
    Text = "Ein frommes Selbst-Opferritual vollziehen"
  },
  AvgVideoCaption_143591_Content_8 = {
    Text = "Was für ein Bedauer"
  },
  AvgVideoCaption_143591_Content_9 = {
    Text = "Du hättest früher kommen sollen"
  },
  AvgVideoCaption_148014_Content_1 = {
    Text = "Jemand rezitiert die Gebete des Astralen Cetus."
  },
  AvgVideoCaption_148014_Content_10 = {
    Text = "Ich kann diese manische Energie spüren..."
  },
  AvgVideoCaption_148014_Content_100 = {
    Text = "Ich werde jede Seele an diesem Ort beschützen."
  },
  AvgVideoCaption_148014_Content_101 = {
    Text = "Ich werde dieser Stadt Frieden bringen."
  },
  AvgVideoCaption_148014_Content_102 = {
    Text = "Ich werde das liebevolle Flüstern des Astralen Cetus an diesen Ort bringen..."
  },
  AvgVideoCaption_148014_Content_103 = {
    Text = "Du... du..."
  },
  AvgVideoCaption_148014_Content_104 = {
    Text = "Diese Frau..."
  },
  AvgVideoCaption_148014_Content_105 = {
    Text = "Die, die du gerade..."
  },
  AvgVideoCaption_148014_Content_106 = {
    Text = "Sie war Mutter von drei Kindern!"
  },
  AvgVideoCaption_148014_Content_107 = {
    Text = "Ist das so?"
  },
  AvgVideoCaption_148014_Content_108 = {
    Text = "Dann herzlichen Glückwunsch an sie,"
  },
  AvgVideoCaption_148014_Content_109 = {
    Text = "sie werden vor viel Leid bewahrt."
  },
  AvgVideoCaption_148014_Content_11 = {
    Text = "Alle Gläubigen, die an Ihn glauben,"
  },
  AvgVideoCaption_148014_Content_110 = {
    Text = "Du... aber du hast versprochen..."
  },
  AvgVideoCaption_148014_Content_111 = {
    Text = "Dir Erlösung zu bringen und diesem Ort Heil."
  },
  AvgVideoCaption_148014_Content_112 = {
    Text = "Ich habe mein Versprechen gehalten, nicht wahr?"
  },
  AvgVideoCaption_148014_Content_113 = {
    Text = "Warte! Warte!"
  },
  AvgVideoCaption_148014_Content_114 = {
    Text = "Wir können gemeinsam an der Auslese teilnehmen!"
  },
  AvgVideoCaption_148014_Content_115 = {
    Text = "Ich kann dir helfen, ich kann—"
  },
  AvgVideoCaption_148014_Content_116 = {
    Text = "Ein verlockendes Angebot,"
  },
  AvgVideoCaption_148014_Content_117 = {
    Text = "schade, dass ich dir bereits mein Wort gegeben habe."
  },
  AvgVideoCaption_148014_Content_118 = {
    Text = "Und ich breche mein Wort nie."
  },
  AvgVideoCaption_148014_Content_119 = {
    Text = "Diese Köpfe sollten als Opfergaben genügen..."
  },
  AvgVideoCaption_148014_Content_12 = {
    Text = "werden von dieser Macht verschlungen."
  },
  AvgVideoCaption_148014_Content_120 = {
    Text = "sie sollten reichen..."
  },
  AvgVideoCaption_148014_Content_121 = {
    Text = "Sie wussten nichts von Macht,"
  },
  AvgVideoCaption_148014_Content_122 = {
    Text = "noch von deinem wahren Begehren."
  },
  AvgVideoCaption_148014_Content_123 = {
    Text = "Aber ich schon."
  },
  AvgVideoCaption_148014_Content_124 = {
    Text = "Ich habe dir den Beweis meiner Macht erbracht."
  },
  AvgVideoCaption_148014_Content_125 = {
    Text = "Ich sehe deine Freude, Astraler Cetus..."
  },
  AvgVideoCaption_148014_Content_126 = {
    Text = "So öffnen sich also die Tore der Auslese..."
  },
  AvgVideoCaption_148014_Content_127 = {
    Text = "Bald wirst du mich sehen."
  },
  AvgVideoCaption_148014_Content_128 = {
    Text = "Warte auf mich... Leviathan."
  },
  AvgVideoCaption_148014_Content_13 = {
    Text = "Krieg, Plünderung, Gemetzel, Blut..."
  },
  AvgVideoCaption_148014_Content_14 = {
    Text = "Der Hunger des Astralen Cetus kennt kein Ende."
  },
  AvgVideoCaption_148014_Content_15 = {
    Text = "Ihr... wollt Ihr die Gnade des Vatergottes ablehnen?"
  },
  AvgVideoCaption_148014_Content_16 = {
    Text = "Ich? Heh. Nein."
  },
  AvgVideoCaption_148014_Content_17 = {
    Text = "Ich schwelge darin, Hierophant."
  },
  AvgVideoCaption_148014_Content_18 = {
    Text = "Genau deshalb bin ich hier."
  },
  AvgVideoCaption_148014_Content_19 = {
    Text = "Schade, dass"
  },
  AvgVideoCaption_148014_Content_2 = {
    Text = "Ist dies der Tempel, in dem die Infizierten untergebracht sind?"
  },
  AvgVideoCaption_148014_Content_20 = {
    Text = "nicht jeder Gläubige Seiner überwältigenden Gnade standhalten kann."
  },
  AvgVideoCaption_148014_Content_21 = {
    Text = "Ah, ja, ja."
  },
  AvgVideoCaption_148014_Content_22 = {
    Text = "Diese bemitleidenswerten und doch gesegneten Gläubigen,"
  },
  AvgVideoCaption_148014_Content_23 = {
    Text = "erfüllt von Freude über die Macht des Vatergotts,"
  },
  AvgVideoCaption_148014_Content_24 = {
    Text = "dann von eben dieser Freude in den Wahnsinn getrieben..."
  },
  AvgVideoCaption_148014_Content_25 = {
    Text = "Deshalb brauchen wir einen Gläubigen wie Euch,"
  },
  AvgVideoCaption_148014_Content_26 = {
    Text = "um den Geist unseres Vaters zu besänftigen,"
  },
  AvgVideoCaption_148014_Content_27 = {
    Text = "um diese armen Gläubigen zu retten. Nur Ihr..."
  },
  AvgVideoCaption_148014_Content_28 = {
    Text = "Liebe Gläubige,"
  },
  AvgVideoCaption_148014_Content_29 = {
    Text = "ich vertraue darauf, dass Ihr Euer Versprechen noch im Gedächtnis habt."
  },
  AvgVideoCaption_148014_Content_3 = {
    Text = "Das stimmt!"
  },
  AvgVideoCaption_148014_Content_30 = {
    Text = "Ich habe Euch versprochen, jene zu retten, die zu schwach sind, um die Gunst des Gottes zu ertragen,"
  },
  AvgVideoCaption_148014_Content_31 = {
    Text = "und Euch zu helfen, diese Stadt zu befreien."
  },
  AvgVideoCaption_148014_Content_32 = {
    Text = "Ich breche niemals mein Wort."
  },
  AvgVideoCaption_148014_Content_33 = {
    Text = "Die Stadt ist tief geehrt, liebe Dame."
  },
  AvgVideoCaption_148014_Content_34 = {
    Text = "Ihr spracht von einigen Leidenden."
  },
  AvgVideoCaption_148014_Content_35 = {
    Text = "Doch mindestens dreihundert stehen jetzt vor mir."
  },
  AvgVideoCaption_148014_Content_36 = {
    Text = "Dies ist eine fromme Stadt,"
  },
  AvgVideoCaption_148014_Content_37 = {
    Text = "der Vatergott hat unsere Gebete erhört..."
  },
  AvgVideoCaption_148014_Content_38 = {
    Text = "Die Stimme des Astralen Cetus hat uns auserwählt!"
  },
  AvgVideoCaption_148014_Content_39 = {
    Text = "Dies ist unsere Ehre!"
  },
  AvgVideoCaption_148014_Content_4 = {
    Text = "Willkommen im ergebensten Heiligtum des Astralen Cetus."
  },
  AvgVideoCaption_148014_Content_40 = {
    Text = "Sie scheinen mir wohlauf zu sein."
  },
  AvgVideoCaption_148014_Content_41 = {
    Text = "Nur für jetzt..."
  },
  AvgVideoCaption_148014_Content_42 = {
    Text = "Wenn das so weitergeht, werden wir alle zu Gefäßen des Willens des Astralen Cetus."
  },
  AvgVideoCaption_148014_Content_43 = {
    Text = "Sie werden Seine Flüstertöne anstimmen,"
  },
  AvgVideoCaption_148014_Content_44 = {
    Text = "und Seine Male werden auf ihrer Haut erscheinen..."
  },
  AvgVideoCaption_148014_Content_45 = {
    Text = "Am Ende wird unser Wille mit Ihm zu einem verschmelzen."
  },
  AvgVideoCaption_148014_Content_46 = {
    Text = "Ist das nicht genau das, was Ihr wollt?"
  },
  AvgVideoCaption_148014_Content_47 = {
    Text = "Natürlich!"
  },
  AvgVideoCaption_148014_Content_48 = {
    Text = "Wir würden dem Vatergott gerne alles opfern!"
  },
  AvgVideoCaption_148014_Content_49 = {
    Text = "Aber... noch nicht."
  },
  AvgVideoCaption_148014_Content_5 = {
    Text = "Aber sie sind nicht \"die Infizierten\"."
  },
  AvgVideoCaption_148014_Content_50 = {
    Text = "Wir wünschen uns noch mehr Offenbarungen des Vaters..."
  },
  AvgVideoCaption_148014_Content_51 = {
    Text = "Und ich — mit dem Segen des Vatergottes — werde an Seiner Auslese teilnehmen,"
  },
  AvgVideoCaption_148014_Content_52 = {
    Text = "und Sein einziger und einzigartiger Executor werden!"
  },
  AvgVideoCaption_148014_Content_53 = {
    Text = "Also muss davor"
  },
  AvgVideoCaption_148014_Content_54 = {
    Text = "jemand den ersten Schritt für uns tun..."
  },
  AvgVideoCaption_148014_Content_55 = {
    Text = "Kommt, meine eifrigen Gläubigen,"
  },
  AvgVideoCaption_148014_Content_56 = {
    Text = "fesselt diese Dame und bringt sie vor den Altar!"
  },
  AvgVideoCaption_148014_Content_57 = {
    Text = "Das war nicht Teil unserer Abmachung."
  },
  AvgVideoCaption_148014_Content_58 = {
    Text = "Meine liebe Dame, Ihr habt mir einst versprochen,"
  },
  AvgVideoCaption_148014_Content_59 = {
    Text = "dass Ihr sie um jeden Preis retten würdet,"
  },
  AvgVideoCaption_148014_Content_6 = {
    Text = "Werte Dame."
  },
  AvgVideoCaption_148014_Content_60 = {
    Text = "diese arme Stadt und diese unglückseligen Gläubigen retten."
  },
  AvgVideoCaption_148014_Content_61 = {Text = "Ich kann"},
  AvgVideoCaption_148014_Content_62 = {
    Text = "die immense Kraft spüren, die in Euch brodelt."
  },
  AvgVideoCaption_148014_Content_63 = {
    Text = "Genau das ist es, was der Vatergott schätzt!"
  },
  AvgVideoCaption_148014_Content_64 = {
    Text = "Du wirst das köstlichste Opfer für den Astralen Cetus sein!"
  },
  AvgVideoCaption_148014_Content_65 = {
    Text = "Sobald ich dich dem Vatergott darbringe..."
  },
  AvgVideoCaption_148014_Content_66 = {
    Text = "werde ich Seinen Segen empfangen..."
  },
  AvgVideoCaption_148014_Content_67 = {
    Text = "Ich werde an jenem heiligen Wettkampf teilnehmen!"
  },
  AvgVideoCaption_148014_Content_68 = {
    Text = "Opfere dich..."
  },
  AvgVideoCaption_148014_Content_69 = {
    Text = "Gib dich hin und lass mich deine Kraft nehmen!"
  },
  AvgVideoCaption_148014_Content_7 = {
    Text = "Der Astrale Cetus, unser großer Vatergott."
  },
  AvgVideoCaption_148014_Content_70 = {
    Text = "Rettet diese armen Seelen!"
  },
  AvgVideoCaption_148014_Content_71 = {
    Text = "Opfere dich,"
  },
  AvgVideoCaption_148014_Content_72 = {
    Text = "und der Astrale Cetus wird Seinen gnädigen Blick auf mich richten!"
  },
  AvgVideoCaption_148014_Content_73 = {
    Text = "Die Runen, die der Astrale Cetus verliehen hat,"
  },
  AvgVideoCaption_148014_Content_74 = {
    Text = "können die verborgenste Kraft in euren Körpern erwecken,"
  },
  AvgVideoCaption_148014_Content_75 = {
    Text = "bis sie euch vollständig verschlingt."
  },
  AvgVideoCaption_148014_Content_76 = {
    Text = "Diese Beschwörung ist eine lange."
  },
  AvgVideoCaption_148014_Content_77 = {
    Text = "Hehehehe ..."
  },
  AvgVideoCaption_148014_Content_78 = {
    Text = "Hättet ihr es etwas früher bemerkt,"
  },
  AvgVideoCaption_148014_Content_79 = {
    Text = "hättet ihr vielleicht eine Chance gehabt."
  },
  AvgVideoCaption_148014_Content_8 = {
    Text = "Vor jeder Auswahl"
  },
  AvgVideoCaption_148014_Content_80 = {
    Text = "Aber jetzt ist es zu spät."
  },
  AvgVideoCaption_148014_Content_81 = {
    Text = "Der Astrale Cetus beobachtet uns."
  },
  AvgVideoCaption_148014_Content_82 = {
    Text = "Meine Brüder und Schwestern,"
  },
  AvgVideoCaption_148014_Content_83 = {
    Text = "Zieht eure Klingen"
  },
  AvgVideoCaption_148014_Content_84 = {
    Text = "und nehmt dieses Opfer entgegen—"
  },
  AvgVideoCaption_148014_Content_85 = {
    Text = "Euer Beschwörungsspruch hat also sein Ende erreicht,"
  },
  AvgVideoCaption_148014_Content_86 = {
    Text = "und Eure Zahl ist durchaus ausreichend... Gut."
  },
  AvgVideoCaption_148014_Content_87 = {Text = "Gut?"},
  AvgVideoCaption_148014_Content_88 = {
    Text = "Hätte ich nicht auf euch alle gewartet,"
  },
  AvgVideoCaption_148014_Content_89 = {
    Text = "hätte ich solch langweiliges Geschwätz nicht geduldet."
  },
  AvgVideoCaption_148014_Content_9 = {
    Text = "erweckt Seine Macht jene mit schwächerem Willen..."
  },
  AvgVideoCaption_148014_Content_90 = {
    Text = "Es ist meine Gewohnheit, dem Gegner den ersten Zug zu überlassen."
  },
  AvgVideoCaption_148014_Content_91 = {
    Text = "Nun sind alle Vorbereitungen abgeschlossen..."
  },
  AvgVideoCaption_148014_Content_92 = {
    Text = "Was?! ...Diese Ketten..."
  },
  AvgVideoCaption_148014_Content_93 = {
    Text = "Macht und Reichtum, das ist alles, was ihr wollt..."
  },
  AvgVideoCaption_148014_Content_94 = {
    Text = "Ihr versteht nicht einmal, was Stärke ist. Kaum ein würdiger Gegner."
  },
  AvgVideoCaption_148014_Content_95 = {Text = "Dennoch,"},
  AvgVideoCaption_148014_Content_96 = {
    Text = "hungert meine Klinge schon viel zu lange nach einem würdigen Kampf."
  },
  AvgVideoCaption_148014_Content_97 = {
    Text = "Ich hoffe, Ihr könnt sie sättigen."
  },
  AvgVideoCaption_148014_Content_98 = {
    Text = "Tötet sie!"
  },
  AvgVideoCaption_148014_Content_99 = {
    Text = "Ich habe euch einst versprochen..."
  },
  AvgVideoCaption_149925_Content_1 = {
    Text = "Der Gipfel des höchsten Schneebergs der Welt..."
  },
  AvgVideoCaption_149925_Content_10 = {
    Text = "Komm mit mir..."
  },
  AvgVideoCaption_149925_Content_11 = {
    Text = "Opfere deine Schätze, deine Wünsche... alles!"
  },
  AvgVideoCaption_149925_Content_12 = {
    Text = "Dein Wunsch wurde empfangen"
  },
  AvgVideoCaption_149925_Content_13 = {
    Text = "Nun denn..."
  },
  AvgVideoCaption_149925_Content_14 = {
    Text = "überlass den Rest der Berggöttin, hmm?"
  },
  AvgVideoCaption_149925_Content_2 = {
    Text = "dort ist es, wo die Götter wohnen."
  },
  AvgVideoCaption_149925_Content_3 = {
    Text = "Komm mit mir."
  },
  AvgVideoCaption_149925_Content_4 = {
    Text = "Die Herrin der Schneeberge wird dir jeden Wunsch erfüllen"
  },
  AvgVideoCaption_149925_Content_5 = {
    Text = "und bringe zurück, was du verloren hast..."
  },
  AvgVideoCaption_149925_Content_6 = {
    Text = "Siebenfacher Ritus"
  },
  AvgVideoCaption_149925_Content_7 = {
    Text = "Dreifaches Gelübde"
  },
  AvgVideoCaption_149925_Content_8 = {
    Text = "die Opfergaben des Pilgers sind vollständig"
  },
  AvgVideoCaption_149925_Content_9 = {
    Text = "Der Gipfel liegt direkt vor dir. Komm mit mir..."
  },
  AvgVideoCaption_149926_Content_1 = {
    Text = "Ngh... Herr..."
  },
  AvgVideoCaption_149926_Content_10 = {
    Text = "Papa war immer betrunken"
  },
  AvgVideoCaption_149926_Content_100 = {
    Text = "Weinen hilft nicht."
  },
  AvgVideoCaption_149926_Content_101 = {
    Text = "Komm, lass uns über dich reden."
  },
  AvgVideoCaption_149926_Content_102 = {
    Text = "Du bist mir drei ganze Straßen lang gefolgt, nicht wahr?"
  },
  AvgVideoCaption_149926_Content_103 = {
    Text = "Du hast meine dünnen kleinen Handgelenke gesehen, meinen blassen Hals,"
  },
  AvgVideoCaption_149926_Content_104 = {
    Text = "und wie langsam ich mit meiner Tasche gelaufen bin."
  },
  AvgVideoCaption_149926_Content_105 = {
    Text = "In deinem Kopf hat es schon eifrig gearbeitet."
  },
  AvgVideoCaption_149926_Content_106 = {
    Text = "So ein kleines Mädchen wie dieses"
  },
  AvgVideoCaption_149926_Content_107 = {
    Text = "würde auf dem Schwarzmarkt einen hübschen Preis erzielen."
  },
  AvgVideoCaption_149926_Content_108 = {
    Text = "Als du mich in diesen Keller hinuntergezogen hast,"
  },
  AvgVideoCaption_149926_Content_109 = {
    Text = "hast du da nicht gedacht – was für ein Glück?"
  },
  AvgVideoCaption_149926_Content_11 = {
    Text = "Mama weinte immer"
  },
  AvgVideoCaption_149926_Content_110 = {
    Text = "...Aber mein Herr, findest du nicht..."
  },
  AvgVideoCaption_149926_Content_111 = {
    Text = "...dass es hier unten ein wenig kälter ist als draußen?"
  },
  AvgVideoCaption_149926_Content_112 = {
    Text = "Hehe, hehehehe~"
  },
  AvgVideoCaption_149926_Content_113 = {
    Text = "Macht nichts."
  },
  AvgVideoCaption_149926_Content_114 = {
    Text = "Bald wirst du dich wärmer fühlen als an jedem Kaminfeuer."
  },
  AvgVideoCaption_149926_Content_115 = {
    Text = "Die letzte Zeile der Geschichte"
  },
  AvgVideoCaption_149926_Content_116 = {
    Text = "gehört der Überlieferung nach demjenigen, der gefressen wird."
  },
  AvgVideoCaption_149926_Content_117 = {Text = "Hehe~"},
  AvgVideoCaption_149926_Content_118 = {
    Text = "Hihihi~ Na dann, mein Herr, sag mir."
  },
  AvgVideoCaption_149926_Content_119 = {
    Text = "Ist dir kalt?"
  },
  AvgVideoCaption_149926_Content_12 = {
    Text = "Kein Feuer im Herd"
  },
  AvgVideoCaption_149926_Content_13 = {
    Text = "kein Brot auf dem Tisch."
  },
  AvgVideoCaption_149926_Content_14 = {
    Text = "Einen Winter"
  },
  AvgVideoCaption_149926_Content_15 = {
    Text = "lag der Schnee so hoch wie die Fensterbank"
  },
  AvgVideoCaption_149926_Content_16 = {
    Text = "und ich wurde aus dem Haus geworfen..."
  },
  AvgVideoCaption_149926_Content_17 = {
    Text = "...nur weil ich Tante Rosa von nebenan erzählt hatte"
  },
  AvgVideoCaption_149926_Content_18 = {
    Text = "dass Papa derjenige war, der mich geschlagen hatte."
  },
  AvgVideoCaption_149926_Content_19 = {
    Text = "Ich lief und lief durch den Schnee"
  },
  AvgVideoCaption_149926_Content_2 = {Text = "Bitte..."},
  AvgVideoCaption_149926_Content_20 = {
    Text = "bis meine Schuhe völlig durchnässt waren"
  },
  AvgVideoCaption_149926_Content_21 = {
    Text = "und meine Zehen wurden taub."
  },
  AvgVideoCaption_149926_Content_22 = {
    Text = "Es war so..."
  },
  AvgVideoCaption_149926_Content_23 = {Text = "so kalt..."},
  AvgVideoCaption_149926_Content_24 = {Text = "...Und du?"},
  AvgVideoCaption_149926_Content_25 = {
    Text = "Frierst du schon?"
  },
  AvgVideoCaption_149926_Content_26 = {
    Text = "Der Wind hier unten im Keller"
  },
  AvgVideoCaption_149926_Content_27 = {
    Text = "fühlt sich an, als würde er einem direkt in die Knochen fahren..."
  },
  AvgVideoCaption_149926_Content_28 = {
    Text = "nicht wahr?"
  },
  AvgVideoCaption_149926_Content_29 = {
    Text = "Lass mich dir erzählen."
  },
  AvgVideoCaption_149926_Content_3 = {
    Text = "Lasst mich gehen"
  },
  AvgVideoCaption_149926_Content_30 = {
    Text = "Damals war es so viel kälter als jetzt—"
  },
  AvgVideoCaption_149926_Content_31 = {
    Text = "Ich lief immer weiter"
  },
  AvgVideoCaption_149926_Content_32 = {Text = "und weiter"},
  AvgVideoCaption_149926_Content_33 = {
    Text = "und die Tränen auf meinem Gesicht froren zu Eis."
  },
  AvgVideoCaption_149926_Content_34 = {
    Text = "Und gerade als ich einzuschlafen drohte—"
  },
  AvgVideoCaption_149926_Content_35 = {
    Text = "hörte ich eine Stimme"
  },
  AvgVideoCaption_149926_Content_36 = {
    Text = "tief unter dem Schnee, die mich rief."
  },
  AvgVideoCaption_149926_Content_37 = {
    Text = "„Kleines Mädchen, warum weinst du?“"
  },
  AvgVideoCaption_149926_Content_38 = {
    Text = "„Ist es, weil du die Wahrheit gesagt hast?“"
  },
  AvgVideoCaption_149926_Content_39 = {
    Text = "„Weil du zu ehrlich warst...“"
  },
  AvgVideoCaption_149926_Content_4 = {
    Text = "Ich werde niemandem davon erzählen..."
  },
  AvgVideoCaption_149926_Content_40 = {
    Text = "„...und sie dich deshalb wie Abfall weggeworfen haben?“"
  },
  AvgVideoCaption_149926_Content_41 = {
    Text = "Ich antwortete nicht."
  },
  AvgVideoCaption_149926_Content_42 = {
    Text = "Ich konnte nicht einmal die Lippen öffnen."
  },
  AvgVideoCaption_149926_Content_43 = {
    Text = "Aber es sagte:"
  },
  AvgVideoCaption_149926_Content_44 = {
    Text = "„Ist schon gut.“"
  },
  AvgVideoCaption_149926_Content_45 = {
    Text = "„Ich bringe dir einen Zauberspruch bei—“"
  },
  AvgVideoCaption_149926_Content_46 = {
    Text = "„sprich ihn aus, und dir wird nie wieder kalt sein.“"
  },
  AvgVideoCaption_149926_Content_47 = {
    Text = "Und so lernte ich"
  },
  AvgVideoCaption_149926_Content_48 = {
    Text = "meine erste Lüge."
  },
  AvgVideoCaption_149926_Content_49 = {
    Text = "Mit dieser Lüge"
  },
  AvgVideoCaption_149926_Content_5 = {
    Text = "Ich gebe Euch alles, was ich habe"
  },
  AvgVideoCaption_149926_Content_50 = {
    Text = "klopfte ich an die erste Bauernhaustür"
  },
  AvgVideoCaption_149926_Content_51 = {
    Text = "und erschwindelte mir einen Apfel."
  },
  AvgVideoCaption_149926_Content_52 = {
    Text = "Ich nahm nur einen einzigen Bissen"
  },
  AvgVideoCaption_149926_Content_53 = {
    Text = "und gab den ganzen Rest"
  },
  AvgVideoCaption_149926_Content_54 = {
    Text = "dieser Stimme."
  },
  AvgVideoCaption_149926_Content_55 = {Text = "Weißt du"},
  AvgVideoCaption_149926_Content_56 = {
    Text = "wenn ein Mensch erfriert"
  },
  AvgVideoCaption_149926_Content_57 = {
    Text = "brennt sein ganzer Körper vor Hitze."
  },
  AvgVideoCaption_149926_Content_58 = {
    Text = "Wärmer als jedes Kaminfeuer auf der Welt."
  },
  AvgVideoCaption_149926_Content_59 = {
    Text = "Von diesem Moment an"
  },
  AvgVideoCaption_149926_Content_6 = {
    Text = "verkauft mich nicht, ja?"
  },
  AvgVideoCaption_149926_Content_60 = {
    Text = "fror ich nie wieder."
  },
  AvgVideoCaption_149926_Content_61 = {Text = "Es sagte,"},
  AvgVideoCaption_149926_Content_62 = {
    Text = "es würde mich nur „unterrichten“."
  },
  AvgVideoCaption_149926_Content_63 = {
    Text = "Ich lernte schnell."
  },
  AvgVideoCaption_149926_Content_64 = {
    Text = "Die Dinge, die ich ergaunert hatte, stapelten sich"
  },
  AvgVideoCaption_149926_Content_65 = {
    Text = "immer höher"
  },
  AvgVideoCaption_149926_Content_66 = {
    Text = "und füllten das ganze Haus."
  },
  AvgVideoCaption_149926_Content_67 = {
    Text = "Doch später"
  },
  AvgVideoCaption_149926_Content_68 = {
    Text = "wurde mir klar—"
  },
  AvgVideoCaption_149926_Content_69 = {
    Text = "jedes Mal, wenn ich log,"
  },
  AvgVideoCaption_149926_Content_7 = {Text = "Bitte"},
  AvgVideoCaption_149926_Content_70 = {
    Text = "erinnerte ich mich ein wenig weniger daran, wer ich einmal war."
  },
  AvgVideoCaption_149926_Content_71 = {
    Text = "Das Erste, was ich vergaß,"
  },
  AvgVideoCaption_149926_Content_72 = {
    Text = "war das Geräusch, wie Papa auf den Tisch schlug."
  },
  AvgVideoCaption_149926_Content_73 = {
    Text = "Dann war es Mamas weinendes Gesicht."
  },
  AvgVideoCaption_149926_Content_74 = {
    Text = "Und danach—"
  },
  AvgVideoCaption_149926_Content_75 = {
    Text = "mein eigener Name."
  },
  AvgVideoCaption_149926_Content_76 = {
    Text = "Es gab eine Zeit, da fragte ich mich,"
  },
  AvgVideoCaption_149926_Content_77 = {
    Text = "ob vielleicht irgendetwas an all dem nicht ganz stimmte."
  },
  AvgVideoCaption_149926_Content_78 = {
    Text = "Doch jedes Mal, wenn ich anfing, so zu denken,"
  },
  AvgVideoCaption_149926_Content_79 = {
    Text = "flüsterte es mir sanft ins Ohr—"
  },
  AvgVideoCaption_149926_Content_8 = {
    Text = "habt Erbarmen mit mir..."
  },
  AvgVideoCaption_149926_Content_80 = {
    Text = "„Frierst du? Willst du dich ein bisschen aufwärmen?“"
  },
  AvgVideoCaption_149926_Content_81 = {
    Text = "Und so lernte ich"
  },
  AvgVideoCaption_149926_Content_82 = {
    Text = "noch eine erzählt."
  },
  AvgVideoCaption_149926_Content_83 = {
    Text = "Noch eine, und noch eine, und noch eine..."
  },
  AvgVideoCaption_149926_Content_84 = {
    Text = "Eine Lüge nach der anderen."
  },
  AvgVideoCaption_149926_Content_85 = {
    Text = "So einfach. So leicht."
  },
  AvgVideoCaption_149926_Content_86 = {
    Text = "Sie stiegen so mühelos aus dem Schnee empor,"
  },
  AvgVideoCaption_149926_Content_87 = {
    Text = "so warm und süß."
  },
  AvgVideoCaption_149926_Content_88 = {
    Text = "Wer bin ich wirklich?"
  },
  AvgVideoCaption_149926_Content_89 = {
    Text = "Bin ich überhaupt ich selbst?"
  },
  AvgVideoCaption_149926_Content_9 = {
    Text = "Ich wurde nie geliebt"
  },
  AvgVideoCaption_149926_Content_90 = {
    Text = "Diese Stimme unter dem Schnee—"
  },
  AvgVideoCaption_149926_Content_91 = {
    Text = "es war meine eigene Stimme"
  },
  AvgVideoCaption_149926_Content_92 = {
    Text = "die ganze Zeit, nicht wahr?"
  },
  AvgVideoCaption_149926_Content_93 = {
    Text = "Oh nein—laufen Sie nicht weg, mein Herr."
  },
  AvgVideoCaption_149926_Content_94 = {
    Text = "Es ist sowieso zu spät zum Weglaufen."
  },
  AvgVideoCaption_149926_Content_95 = {
    Text = "Ihre Hände, Ihre Füße..."
  },
  AvgVideoCaption_149926_Content_96 = {
    Text = "Sie sind schon lange vor Kälte erstarrt."
  },
  AvgVideoCaption_149926_Content_97 = {
    Text = "Sollen WIR Ihnen helfen, sich aufzuwärmen?"
  },
  AvgVideoCaption_149926_Content_98 = {Text = "Na, na."},
  AvgVideoCaption_149926_Content_99 = {
    Text = "Ich habe es versucht—"
  },
  AvgVideoCaption_18618_Content_1 = {
    Text = "In den Tiefen der Kammer steht ein reinweißes Monster in Stille."
  },
  AvgVideoCaption_18619_Content_1 = {
    Text = "Der frenetische Glanz in Lotans Augen verblasst allmählich und wird durch einen trüben silbernen Schimmer ersetzt."
  },
  AvgVideoCaption_18619_Content_2 = {
    Text = "Das Bewusstsein zurückerlangend, scheint Lotan an einem schweren Kopfschmerz zu leiden, hält sich eine Seite ihrer Stirn und hat den Kopf gesenkt."
  },
  AvgVideoCaption_18620_Content_1 = {
    Text = "Als ihre Worte fielen, verschwanden alle Wesen jenseits der Vernunft in einem Augenblick."
  },
  AvgVideoCaption_18621_Content_1 = {
    Text = "Sie hob ihre Hand und wischte das Glas vor ihr sauber."
  },
  AvgVideoCaption_18622_Content_1 = {
    Text = "Die goldenen Strahlen der untergehenden Sonne durchdringen das riesige transparente Zifferblatt und baden das Mädchen im Licht."
  },
  AvgVideoCaption_18623_Content_1 = {
    Text = "Einmal mehr bin ich der Einzige, der übrig bleibt."
  },
  AvgVideoCaption_18624_Content_1 = {
    Text = "Im nächsten Moment verblasste das unheimliche Erscheinungsbild."
  },
  AvgVideoCaption_18625_Content_1 = {
    Text = "In der Gegenwart dieser riesigen und unbekannten Wesen..."
  },
  AvgVideoCaption_18625_Content_10 = {
    Text = "In dem Moment, in dem dieses Wort gehört wird, schießt ein stechender, summender Schmerz tief ins Gehirn."
  },
  AvgVideoCaption_18625_Content_11 = {
    Text = "Übelkeit drehte sich in meinem Magen, und der stechende Gestank von Erbrochenem überfiel meine Nasenlöcher."
  },
  AvgVideoCaption_18625_Content_2 = {
    Text = "Menschen, so unbedeutend."
  },
  AvgVideoCaption_18625_Content_3 = {
    Text = "Ist das ein Traum?"
  },
  AvgVideoCaption_18625_Content_4 = {
    Text = "Ein starkes Gefühl der Unruhe steigt in meiner Brust auf."
  },
  AvgVideoCaption_18625_Content_5 = {
    Text = "—Mythag Universität Schlüsselgrab, Zeremonie zur Verleihung des Silbernen Schlüssels—"
  },
  AvgVideoCaption_18625_Content_6 = {
    Text = "\"... Die Mythag-Universität ist ein Pionier im Kampf gegen @2...\""
  },
  AvgVideoCaption_18625_Content_7 = {
    Text = "\"...werde ein Ermittler an der Mythag-Universität,\""
  },
  AvgVideoCaption_18625_Content_8 = {
    Text = "„Es bedeutet, dass der Rest eures Lebens von Tod und Wahnsinn begleitet wird...“"
  },
  AvgVideoCaption_18625_Content_9 = {
    Text = "\"In den letzten zehn Jahren, verbreite @2...\""
  },
  AvgVideoCaption_18626_Content_1 = {
    Text = "Wenn es jetzt alle Sicherheit bringen kann, bin ich zufrieden."
  },
  AvgVideoCaption_18626_Content_10 = {
    Text = "Ein Gefühl von Feuchtigkeit prickelt an meinen Fingerspitzen, doch es gibt kein wirkliches Tastsinn."
  },
  AvgVideoCaption_18626_Content_11 = {
    Text = "Ein kleiner Fragment der Realität zerrann an ihren Fingerspitzen und verschwand für immer aus der Welt."
  },
  AvgVideoCaption_18626_Content_2 = {
    Text = "Ich werde nicht länger kontrolliert."
  },
  AvgVideoCaption_18626_Content_3 = {
    Text = "Wird nicht wieder jemandem schaden."
  },
  AvgVideoCaption_18626_Content_4 = {
    Text = "Ich werde nicht zulassen, dass meine Freunde wegen mir wieder sterben."
  },
  AvgVideoCaption_18626_Content_5 = {
    Text = "Unter dem Klang der Glocke gelang es Aigis auf irgendeine Weise, mühelos das Glas zu öffnen, das vor ihr versiegelt gewesen sein sollte."
  },
  AvgVideoCaption_18626_Content_6 = {
    Text = "Sag Jenkin, es tut mir leid."
  },
  AvgVideoCaption_18626_Content_7 = {
    Text = "Sag ihr von mir, wir werden immer Freunde sein."
  },
  AvgVideoCaption_18626_Content_8 = {
    Text = "Aigis schloss die Augen und fühlte sich immer leichter werden. Hinter ihr streckte Ramona verzweifelt ihre Hand zum Nachthimmel aus."
  },
  AvgVideoCaption_18626_Content_9 = {
    Text = "Nimm Kontakt auf, halte dich fest."
  },
  AvgVideoCaption_22146_Content_1 = {
    Text = "Eine schreckliche Katastrophe ist angekommen"
  },
  AvgVideoCaption_22146_Content_2 = {
    Text = "\"Auflösung\""
  },
  AvgVideoCaption_22146_Content_3 = {
    Text = "Es verschlingt alles"
  },
  AvgVideoCaption_22146_Content_4 = {
    Text = "Selbst Erinnerungen können seinem Griff nicht entkommen."
  },
  AvgVideoCaption_22146_Content_5 = {
    Text = "Nach Jahrhunderten haben wir endlich einen Durchbruch gefunden —"
  },
  AvgVideoCaption_22146_Content_6 = {Text = "\"Silber\""},
  AvgVideoCaption_22146_Content_7 = {
    Text = "Es kann die verstorbenen Seelen erwecken"
  },
  AvgVideoCaption_22146_Content_8 = {
    Text = "Diese Geister sind unsere letzte Hoffnung."
  },
  AvgVideoCaption_22146_Content_9 = {
    Text = "Das hoffen wir zumindest..."
  },
  AvgVideoCaption_24281_Content_1 = {
    Text = "Der Moment des Blühens ist endlich angekommen."
  },
  AvgVideoCaption_24724_Content_1 = {
    Text = "Die Anzahl der Fehlschläge spielt keine Rolle."
  },
  AvgVideoCaption_24724_Content_2 = {
    Text = "Egal wie oft ich zurückkomme, ich werde es definitiv finden."
  },
  AvgVideoCaption_24724_Content_3 = {
    Text = "Speichere diese Welt"
  },
  AvgVideoCaption_24724_Content_4 = {
    Text = "Speichern Ihrer Methode"
  },
  AvgVideoCaption_36151_Content_1 = {
    Text = "Der Ausgang, der Ausgang ist direkt dort..."
  },
  AvgVideoCaption_36151_Content_10 = {
    Text = "Höre meinen Herrn!"
  },
  AvgVideoCaption_36151_Content_11 = {
    Text = "Warum sollte ich gehorchen?!"
  },
  AvgVideoCaption_36151_Content_12 = {
    Text = "Meinem Herrn unterwerfen"
  },
  AvgVideoCaption_36151_Content_13 = {
    Text = "Warum sollte ich nachgeben!"
  },
  AvgVideoCaption_36151_Content_14 = {
    Text = "Opfer! Gestalte das Gottesreich neu—"
  },
  AvgVideoCaption_36151_Content_15 = {
    Text = "Welches Reich Gottes, welcher Gott... Was hat das mit mir zu tun!"
  },
  AvgVideoCaption_36151_Content_16 = {
    Text = "Opfer! Kehre zu meinem Meister zurück—"
  },
  AvgVideoCaption_36151_Content_17 = {
    Text = "Verlasse diesen Ort. Lass uns... diesen Ort gemeinsam verlassen!"
  },
  AvgVideoCaption_36151_Content_2 = {
    Text = "Mutter der Götter, warum bist du abgereist?"
  },
  AvgVideoCaption_36151_Content_3 = {
    Text = "Tu das nicht... Ich möchte nicht die göttliche Mutter sein."
  },
  AvgVideoCaption_36151_Content_4 = {
    Text = "Ich möchte kein Opfer sein..."
  },
  AvgVideoCaption_36151_Content_5 = {
    Text = "Das Reich Gottes wird dich gebären."
  },
  AvgVideoCaption_36151_Content_6 = {
    Text = "Wie viel weiter? Wie viel länger?"
  },
  AvgVideoCaption_36151_Content_7 = {
    Text = "Der Moment des Ausrichtens ist gekommen—"
  },
  AvgVideoCaption_36151_Content_8 = {
    Text = "Ist es... schon zu spät?"
  },
  AvgVideoCaption_36151_Content_9 = {
    Text = "Aber... warum?!"
  },
  AvgVideoCaption_45044_Content_1 = {
    Text = "Eine unsichtbare Plage ist angekommen"
  },
  AvgVideoCaption_45044_Content_10 = {
    Text = "\"Wirst du dein Caro für uns opfern?\""
  },
  AvgVideoCaption_45044_Content_11 = {
    Text = "\"Wirst du dein Leben für uns opfern?\""
  },
  AvgVideoCaption_45044_Content_12 = {
    Text = "\"Der Vater weint um uns, Seine Kinder.\""
  },
  AvgVideoCaption_45044_Content_13 = {
    Text = "\"Er möchte, dass die Edlen unter uns als Seine Gesandten dienen.\""
  },
  AvgVideoCaption_45044_Content_14 = {
    Text = "„Lindere das Leiden aus diesem Land.“"
  },
  AvgVideoCaption_45044_Content_15 = {
    Text = "Ich diene als Stellvertreter für den Vater Gott"
  },
  AvgVideoCaption_45044_Content_16 = {
    Text = "Mit aller Kraft"
  },
  AvgVideoCaption_45044_Content_17 = {
    Text = "\"Warum, Bischof, warum kein Segen heute?\""
  },
  AvgVideoCaption_45044_Content_18 = {
    Text = "\"Warum machst du nicht weiter? Warum rettest du uns nicht!\""
  },
  AvgVideoCaption_45044_Content_19 = {
    Text = "\"Wie kannst du ohnmächtig sein?\""
  },
  AvgVideoCaption_45044_Content_2 = {
    Text = "Es bringt Tod und Verzweiflung."
  },
  AvgVideoCaption_45044_Content_20 = {
    Text = "\"Du hast uns im Stich gelassen und den Schmerz verbreitet!\""
  },
  AvgVideoCaption_45044_Content_21 = {
    Text = "\"Ich will Segnungen, ich will leben, ich will überleben!\""
  },
  AvgVideoCaption_45044_Content_22 = {
    Text = "\"Nicht genug, nicht genug, nicht genug!\""
  },
  AvgVideoCaption_45044_Content_23 = {Text = "Mein Leben"},
  AvgVideoCaption_45044_Content_24 = {
    Text = "Alle sind der Befreiung von deinem Leiden gewidmet."
  },
  AvgVideoCaption_45044_Content_25 = {
    Text = "Seelenhirte"
  },
  AvgVideoCaption_45044_Content_26 = {
    Text = "Alles dient deinem Wohl."
  },
  AvgVideoCaption_45044_Content_3 = {
    Text = "Kinder des Vaters"
  },
  AvgVideoCaption_45044_Content_4 = {
    Text = "Meine Brüder und Schwester"
  },
  AvgVideoCaption_45044_Content_5 = {
    Text = "Ich fühle mit deinem Leiden."
  },
  AvgVideoCaption_45044_Content_6 = {
    Text = "Ich bin bereit, alles zu geben."
  },
  AvgVideoCaption_45044_Content_7 = {
    Text = "Nur damit du keinen Schmerz mehr fühlst"
  },
  AvgVideoCaption_45044_Content_8 = {
    Text = "\"Bischof Salvador, wirst du uns heute deinen Segen erteilen?\""
  },
  AvgVideoCaption_45044_Content_9 = {
    Text = "\"Bischof Salvador, wirst du uns retten?\""
  },
  AvgVideoCaption_50040_Content_1 = {
    Text = "Proliferate, in dieser urzeitlichen Wüste"
  },
  AvgVideoCaption_50040_Content_10 = {
    Text = "Werde eins mit mir"
  },
  AvgVideoCaption_50040_Content_11 = {
    Text = "Trage mein Kind"
  },
  AvgVideoCaption_50040_Content_12 = {
    Text = "Lass unser Blut und unsere Saat"
  },
  AvgVideoCaption_50040_Content_13 = {
    Text = "Ertränke dieses Sandmeer!"
  },
  AvgVideoCaption_50040_Content_14 = {
    Text = "Opfer dein Fleisch und Blut"
  },
  AvgVideoCaption_50040_Content_15 = {
    Text = "Um zum Stamm des Mutterbaums zu werde"
  },
  AvgVideoCaption_50040_Content_16 = {
    Text = "Opfere deine Blutlinie"
  },
  AvgVideoCaption_50040_Content_17 = {
    Text = "Quelle des Heiligen Flusses"
  },
  AvgVideoCaption_50040_Content_18 = {
    Text = "Nähre das neue Yalan!"
  },
  AvgVideoCaption_50040_Content_19 = {
    Text = "Proliferation erfolgt mit dem Eintreffen der schwarzen Apokalypse."
  },
  AvgVideoCaption_50040_Content_2 = {
    Text = "Der einzige Weg zu überleben"
  },
  AvgVideoCaption_50040_Content_20 = {
    Text = "Der einzige Weg zu überleben"
  },
  AvgVideoCaption_50040_Content_21 = {Text = "Du musst"},
  AvgVideoCaption_50040_Content_22 = {Text = "Beitreten?"},
  AvgVideoCaption_50040_Content_23 = {
    Text = "Mutter von Tausenden Nachkommen"
  },
  AvgVideoCaption_50040_Content_3 = {
    Text = "Möchtest du mitmachen?"
  },
  AvgVideoCaption_50040_Content_4 = {Text = "Komm schon"},
  AvgVideoCaption_50040_Content_5 = {
    Text = "Ich kann nicht mehr länger durchhalten."
  },
  AvgVideoCaption_50040_Content_6 = {
    Text = "Komm schon, komm herüber"
  },
  AvgVideoCaption_50040_Content_7 = {
    Text = "Bleib in meiner Nähe"
  },
  AvgVideoCaption_50040_Content_8 = {
    Text = "Berühre mich"
  },
  AvgVideoCaption_50040_Content_9 = {Text = "Geh hinein"},
  AvgVideoCaption_56358_Content_1 = {
    Text = "Regen ist der Abschied der Wolken vom Himmel."
  },
  AvgVideoCaption_56358_Content_10 = {
    Text = "Du bist Frühling"
  },
  AvgVideoCaption_56358_Content_11 = {
    Text = "Gewähre mir ein Lied"
  },
  AvgVideoCaption_56358_Content_12 = {
    Text = "Ein Gedicht, das dem Garten im Frühling gewidmet ist"
  },
  AvgVideoCaption_56358_Content_13 = {
    Text = "In unseren trostlosen Leben wohnen Rosen in tiefem Rot."
  },
  AvgVideoCaption_56358_Content_14 = {
    Text = "\"Halt meine Hand,\" sagtest du."
  },
  AvgVideoCaption_56358_Content_15 = {
    Text = "Wenn sich unsere Finger berühren, wirst du mir einen Garten geben"
  },
  AvgVideoCaption_56358_Content_16 = {
    Text = "In unserem bescheidenen Königreich"
  },
  AvgVideoCaption_56358_Content_17 = {
    Text = "Du wirst all die Dornen für mich tragen."
  },
  AvgVideoCaption_56358_Content_18 = {
    Text = "Nehmt dieses Gedicht, ein Frühlingsgeschenk für den Garten."
  },
  AvgVideoCaption_56358_Content_19 = {
    Text = "In unseren trostlosen Leben wohnen Rosen in tiefem Rot."
  },
  AvgVideoCaption_56358_Content_2 = {
    Text = "Wenn wir uns wieder treffen, werde ich Blumen mitbringen."
  },
  AvgVideoCaption_56358_Content_20 = {
    Text = "Regen ist der Abschied des Frühlings vom Garten."
  },
  AvgVideoCaption_56358_Content_21 = {
    Text = "Wenn wir uns wiedersehen"
  },
  AvgVideoCaption_56358_Content_22 = {
    Text = "Wirst du einen Blumenstrauß mitbringen?"
  },
  AvgVideoCaption_56358_Content_23 = {
    Text = "Ein Blumenstrauß für den Frühling"
  },
  AvgVideoCaption_56358_Content_24 = {
    Text = "Austausch mit mir, das letzte Versmaß"
  },
  AvgVideoCaption_56358_Content_3 = {
    Text = "Austausch mit dir, die erste Strophe"
  },
  AvgVideoCaption_56358_Content_4 = {
    Text = "Halte meine Hand."
  },
  AvgVideoCaption_56358_Content_5 = {
    Text = "Wenn sich Finger begegnen"
  },
  AvgVideoCaption_56358_Content_6 = {
    Text = "Ich werde dir einen Garten geben."
  },
  AvgVideoCaption_56358_Content_7 = {
    Text = "In unserem bescheidenen Königreich"
  },
  AvgVideoCaption_56358_Content_8 = {
    Text = "Ich werde alle Dornen für dich tragen."
  },
  AvgVideoCaption_56358_Content_9 = {
    Text = "Horla, ich bin der Garten, und du—"
  },
  AvgVideoCaption_60917_Content_1 = {
    Text = "Derjenige, der alles kontrolliert"
  },
  AvgVideoCaption_60917_Content_10 = {
    Text = "Die Darsteller haben alle die Bühne betreten."
  },
  AvgVideoCaption_60917_Content_11 = {
    Text = "Lasst die dissonanten Geräusche in die Stille verschwinden"
  },
  AvgVideoCaption_60917_Content_12 = {
    Text = "Lass alle Noten entlang des Pfades des Musikstocks tanzen."
  },
  AvgVideoCaption_60917_Content_13 = {
    Text = "Alle, für das perfekte Ensemble."
  },
  AvgVideoCaption_60917_Content_14 = {
    Text = "Jetzt lass dich davon berauschen."
  },
  AvgVideoCaption_60917_Content_15 = {
    Text = "Eingetaucht in diese großartige Symphonie—"
  },
  AvgVideoCaption_60917_Content_16 = {
    Text = "A-Moll: finale Symphonie"
  },
  AvgVideoCaption_60917_Content_17 = {
    Text = "Wenn der Applaus im Theater verklingt"
  },
  AvgVideoCaption_60917_Content_18 = {
    Text = "Die wahre Darbietung"
  },
  AvgVideoCaption_60917_Content_19 = {
    Text = "Es wird gleich beginnen."
  },
  AvgVideoCaption_60917_Content_2 = {
    Text = "Nur dann kannst du die Musik beherrschen"
  },
  AvgVideoCaption_60917_Content_3 = {
    Text = "Prälude, beginne"
  },
  AvgVideoCaption_60917_Content_4 = {
    Text = "Wo der Stock zeigt"
  },
  AvgVideoCaption_60917_Content_5 = {
    Text = "Alles hallt hier wider"
  },
  AvgVideoCaption_60917_Content_6 = {
    Text = "Streicher, die Protagonisten der tragischen Bühne"
  },
  AvgVideoCaption_60917_Content_7 = {
    Text = "Sink in die Vergessenheit, oder werde neu geboren"
  },
  AvgVideoCaption_60917_Content_8 = {
    Text = "Holzbläser, ein formidable Gegner, gefährliche Harmonien"
  },
  AvgVideoCaption_60917_Content_9 = {
    Text = "Schlaginstrumente, unerwartete Intervalle, überraschendes Konzert"
  },
  AvgVideoCaption_70276_Content_1 = {
    Text = "Wir sind namenlose Wesen"
  },
  AvgVideoCaption_70276_Content_10 = {
    Text = "Ruf meinen Namen, selbst wenn meine Stimmbänder austrocknen"
  },
  AvgVideoCaption_70276_Content_11 = {
    Text = "Immer noch auf der Suche nach Beweisen für die eigene Existenz"
  },
  AvgVideoCaption_70276_Content_12 = {
    Text = "Ruf meinen Namen, selbst wenn die Welt vergeht"
  },
  AvgVideoCaption_70276_Content_13 = {
    Text = "Das Licht des Augenblicks weiterhin festhalten"
  },
  AvgVideoCaption_70276_Content_14 = {
    Text = "Ruf meinen Namen, auch wenn die Trennung bevorsteht"
  },
  AvgVideoCaption_70276_Content_15 = {
    Text = "Immer noch fest davon überzeugt, dass der Weg der Suche und des Vorwärtsgehens einen Sinn hat"
  },
  AvgVideoCaption_70276_Content_16 = {
    Text = "Ruf meinen Namen, selbst wenn die Zeit stehen bleibt"
  },
  AvgVideoCaption_70276_Content_17 = {
    Text = "immer noch die unsterbliche Hoffnung wecken"
  },
  AvgVideoCaption_70276_Content_18 = {
    Text = "Darf ich deinen Namen rufen, selbst wenn die Welt vergeht"
  },
  AvgVideoCaption_70276_Content_19 = {
    Text = "Das strahlende Licht jenes Moments weiterhin festhalten"
  },
  AvgVideoCaption_70276_Content_2 = {
    Text = "Aus der Welt des Vergessenen"
  },
  AvgVideoCaption_70276_Content_20 = {
    Text = "Möge der Silberne Schlüssel uns leiten"
  },
  AvgVideoCaption_70276_Content_21 = {
    Text = "Möge der Silberne Schlüssel uns leiten"
  },
  AvgVideoCaption_70276_Content_3 = {
    Text = "mit stummen Rudern paddeln"
  },
  AvgVideoCaption_70276_Content_4 = {
    Text = "Blick in die unerreichbare Höhe"
  },
  AvgVideoCaption_70276_Content_5 = {
    Text = "Der silberne Morgenstern der Erleuchtung wird von der schwarzen Flut verschlungen"
  },
  AvgVideoCaption_70276_Content_6 = {
    Text = "Verschwommene Aufzeichnungen, vergessene Gesichter"
  },
  AvgVideoCaption_70276_Content_7 = {
    Text = "Verzweifelt bemüht, es zu erfassen, doch nicht halten können"
  },
  AvgVideoCaption_70276_Content_8 = {
    Text = "In der allmählich schmelzenden Polarnacht den letzten Wunsch äußern"
  },
  AvgVideoCaption_70276_Content_9 = {
    Text = "Vor der vergessenen Morgendämmerung"
  },
  AvgVideoCaption_72086_Content_1 = {
    Text = "Sieh nach oben"
  },
  AvgVideoCaption_72086_Content_10 = {
    Text = "Die Illusion war nicht ihre ursprüngliche Absicht."
  },
  AvgVideoCaption_72086_Content_11 = {
    Text = "Der Wahnsinn des Wissens treibt sie dazu, persönlich den Motor der Zerstörung zu aktivieren"
  },
  AvgVideoCaption_72086_Content_12 = {
    Text = "Sie ist der Führer durch den Wald des Verstandes"
  },
  AvgVideoCaption_72086_Content_13 = {
    Text = "Unter dem ständig schwingenden Pendel"
  },
  AvgVideoCaption_72086_Content_14 = {
    Text = "Die gequälten Seelen übergeben ihre schwarzgebrannten Eingeweide"
  },
  AvgVideoCaption_72086_Content_15 = {
    Text = "Die Ästhetik des Lebens ist verfalle"
  },
  AvgVideoCaption_72086_Content_16 = {
    Text = "Unter der schicksalhaften Klinge tanzt er mit den Abgeschiedenen"
  },
  AvgVideoCaption_72086_Content_17 = {
    Text = "Das Kind der Gottheit ist auch die Mutter der Gottheit"
  },
  AvgVideoCaption_72086_Content_18 = {
    Text = "An diejenigen, die den sich windenden Caro der göttlichen Geburt des Königs anbieten"
  },
  AvgVideoCaption_72086_Content_19 = {
    Text = "Wenn du in endloser Ehre schwelgst"
  },
  AvgVideoCaption_72086_Content_2 = {
    Text = "Der Moment der Ausrichtung der Sterne rückt näher"
  },
  AvgVideoCaption_72086_Content_20 = {
    Text = "Zahlreiche Gletscher, weite Schneefelder"
  },
  AvgVideoCaption_72086_Content_21 = {
    Text = "Sie ist der reinste Farbton von Weiß."
  },
  AvgVideoCaption_72086_Content_22 = {
    Text = "......Würdest du wirklich solchen Unsinn glauben?"
  },
  AvgVideoCaption_72086_Content_23 = {
    Text = "Gesang, Klage und weben Spinnennetze mit deiner Stimme."
  },
  AvgVideoCaption_72086_Content_24 = {
    Text = "Am Webstuhl"
  },
  AvgVideoCaption_72086_Content_25 = {
    Text = "Jeder Seidenfaden verbindet eine Person"
  },
  AvgVideoCaption_72086_Content_26 = {
    Text = "Wir sind alle Puppen des Schicksals."
  },
  AvgVideoCaption_72086_Content_27 = {
    Text = "Vollständig die Mission an diesem Ort"
  },
  AvgVideoCaption_72086_Content_28 = {
    Text = "Rückkehr in die ursprüngliche Welt"
  },
  AvgVideoCaption_72086_Content_29 = {
    Text = "Der grundlose Schlaf ist zu Ende gekommen"
  },
  AvgVideoCaption_72086_Content_3 = {
    Text = "Aus einer Welt, die ihr \"Ende\" angenommen hat"
  },
  AvgVideoCaption_72086_Content_30 = {
    Text = "Unter meiner Herrschaft wird Lemuria ein ewiges und unvergängliches Königreich sein"
  },
  AvgVideoCaption_72086_Content_31 = {
    Text = "Sieh nach oben"
  },
  AvgVideoCaption_72086_Content_32 = {
    Text = "Der Moment der Ausrichtung der Sterne ist gekommen"
  },
  AvgVideoCaption_72086_Content_4 = {
    Text = "Ah, der <Gast> aus der Ferne"
  },
  AvgVideoCaption_72086_Content_5 = {
    Text = "Die törichten Wesen sind bereits zu Staub zerfallen"
  },
  AvgVideoCaption_72086_Content_6 = {
    Text = "Es hängt von deiner Intelligenz ab."
  },
  AvgVideoCaption_72086_Content_7 = {
    Text = "Nähre den Weg des Überlebens"
  },
  AvgVideoCaption_72086_Content_8 = {
    Text = "Die Ankunft des wahren Gottkönigs"
  },
  AvgVideoCaption_72086_Content_9 = {
    Text = "Biete alle Spiritualität und Träume a"
  },
  AvgVideoCaption_76210_Content_1 = {
    Text = "Winkle, starte das Grammophon."
  },
  AvgVideoCaption_76210_Content_10 = {
    Text = "Die aktuelle optimale Strategie besteht darin, dass ich eine Operation an diesem Gehirngefäß durchführe, um seine Schnittstelle mit der Nährlösung zu modifizieren."
  },
  AvgVideoCaption_76210_Content_11 = {
    Text = "Zwanghaft die Gehirnaktivität steigern, um das Bewusstsein des Hüters zu wecken."
  },
  AvgVideoCaption_76210_Content_12 = {
    Text = "Lieber Welpe, hab keine Angst."
  },
  AvgVideoCaption_76210_Content_13 = {
    Text = "Alright, die Instrumente sind bereit. Kommt heraus."
  },
  AvgVideoCaption_76210_Content_14 = {
    Text = "Was für eine schöne Gehirnwindung"
  },
  AvgVideoCaption_76210_Content_15 = {
    Text = "Entferne die überschüssigen Verunreinigungen..."
  },
  AvgVideoCaption_76210_Content_16 = {
    Text = "Stelle die Reinheit des Großhirnkortex wieder her"
  },
  AvgVideoCaption_76210_Content_17 = {Text = "Hier..."},
  AvgVideoCaption_76210_Content_18 = {
    Text = "Schwanzkern"
  },
  AvgVideoCaption_76210_Content_19 = {
    Text = "Lentiformer Nukleus"
  },
  AvgVideoCaption_76210_Content_2 = {
    Text = "Ist sein Bewusstsein immer noch nicht in der Lage, richtig mit dem Gehirntank zu verbinden?"
  },
  AvgVideoCaption_76210_Content_20 = {Text = "Amygdala"},
  AvgVideoCaption_76210_Content_21 = {
    Text = "Claustrum..."
  },
  AvgVideoCaption_76210_Content_22 = {
    Text = "Alle Funktionen arbeiten normal."
  },
  AvgVideoCaption_76210_Content_23 = {
    Text = "Lieber Welpe, ich werde dein Gehirn sorgfältig schützen."
  },
  AvgVideoCaption_76210_Content_24 = {
    Text = "Es wäre bedauerlich, wenn Schäden am Hippocampus uns dazu bringen würden, die wertvollen Erinnerungen zwischen dir und mir zu verlieren."
  },
  AvgVideoCaption_76210_Content_25 = {
    Text = "Ich erinnere mich immer noch an den ersten Tag, an dem wir uns getroffen haben; du hast mich für eine Puppe gehalten."
  },
  AvgVideoCaption_76210_Content_26 = {
    Text = "Du schaust mich an und nennst mich zitternd „Professor Puppe“."
  },
  AvgVideoCaption_76210_Content_27 = {
    Text = "Ich dachte, ich sei würdevoll, aber es stellt sich heraus, dass du einfach Angst vor ihrer Zurechtweisung hast, weil du den Feldbericht nicht fertiggestellt hast."
  },
  AvgVideoCaption_76210_Content_28 = {
    Text = "In welchem Teil deines Gehirns ist dieses Erinnerungsstück gespeichert?"
  },
  AvgVideoCaption_76210_Content_29 = {
    Text = "Ist es hier?"
  },
  AvgVideoCaption_76210_Content_3 = {
    Text = "Ist es dir wirklich so schwer, über Dimensionen hinweg zu kommunizieren?"
  },
  AvgVideoCaption_76210_Content_30 = {
    Text = "...oder hier?"
  },
  AvgVideoCaption_76210_Content_31 = {
    Text = "Haha, das spielt keine Rolle. Irgendwo ist es in Ordnung."
  },
  AvgVideoCaption_76210_Content_32 = {
    Text = "Weil es wichtigere Dinge gibt."
  },
  AvgVideoCaption_76210_Content_33 = {
    Text = "Am Ende dieses Tages hast du zusammen mit dem Professor von Mythag mich persönlich in den dunklen, lichtlosen Tiefen versiegelt."
  },
  AvgVideoCaption_76210_Content_34 = {
    Text = "Alle vier Gliedmaßen sind durch Fesseln gebunden, der Bewegungsbereich so eingeschränkt, dass selbst das Umdrehen eng erscheint..."
  },
  AvgVideoCaption_76210_Content_35 = {
    Text = "Selbst wenn du vergisst..."
  },
  AvgVideoCaption_76210_Content_36 = {
    Text = "Ich werde niemals, niemals vergessen!"
  },
  AvgVideoCaption_76210_Content_37 = {
    Text = "Ewige Vernichtung in der Hölle der Rückkehrlosigkeit!"
  },
  AvgVideoCaption_76210_Content_38 = {
    Text = "Mach dir keine Sorgen, ich habe mich erholt."
  },
  AvgVideoCaption_76210_Content_39 = {
    Text = "Entschuldigung, Mythags Welpe."
  },
  AvgVideoCaption_76210_Content_4 = {
    Text = "Ich dachte, ▼▼Tech hätte sein ganzes Dasein der Forschung über das Bewusstseinsübertragung gewidmet; dieses kleine Problem sollte leicht zu bewältigen sein."
  },
  AvgVideoCaption_76210_Content_40 = {
    Text = "Ich hätte nicht so aufgeregt sein sollen."
  },
  AvgVideoCaption_76210_Content_41 = {
    Text = "Next, I will cut open your Gehirnstamm."
  },
  AvgVideoCaption_76210_Content_42 = {
    Text = "Erreiche dein Hypothalamus und passe dein Mittelhirn an..."
  },
  AvgVideoCaption_76210_Content_43 = {
    Text = "Oh, deine Nerven zucken."
  },
  AvgVideoCaption_76210_Content_44 = {
    Text = "So bedauernswert, soll ich etwas Anästhetikum injizieren?"
  },
  AvgVideoCaption_76210_Content_45 = {
    Text = "Leider ist es jetzt zu spät."
  },
  AvgVideoCaption_76210_Content_46 = {
    Text = "Halte noch ein wenig durch, sehr bald, sehr bald—"
  },
  AvgVideoCaption_76210_Content_47 = {
    Text = "Hmm, lass mich einen Blick darauf werfen."
  },
  AvgVideoCaption_76210_Content_48 = {Text = "Wo ist es?"},
  AvgVideoCaption_76210_Content_49 = {
    Text = "Ich habe es gefunden."
  },
  AvgVideoCaption_76210_Content_5 = {
    Text = "Es scheint, ich habe dich schließlich überschätzt."
  },
  AvgVideoCaption_76210_Content_50 = {
    Text = "Hmm, um die Aktivität wiederherzustellen, ist ein bisschen elektrische Stimulation erforderlich."
  },
  AvgVideoCaption_76210_Content_51 = {
    Text = "Ich werde die Betäubungspistole holen. Sei vorsichtig, okay?"
  },
  AvgVideoCaption_76210_Content_52 = {
    Text = "Ich habe dich warten lassen, armer kleiner Mensch."
  },
  AvgVideoCaption_76210_Content_53 = {
    Text = "Ich werde dich richtig fühlen lassen..."
  },
  AvgVideoCaption_76210_Content_54 = {
    Text = "Dunkel und schwer wie meine... so schwarz wie Tinte..."
  },
  AvgVideoCaption_76210_Content_55 = {
    Text = "Jetzt lasst uns von der niedrigsten Ebene aus starten."
  },
  AvgVideoCaption_76210_Content_56 = {
    Text = "Obwohl ich einen effizienten und sofortigen Tod bevorzuge"
  },
  AvgVideoCaption_76210_Content_57 = {
    Text = "Aber jetzt ist die Zeit, um dich \"zu erfreuen\". Ich werde diese Chance nicht verpassen."
  },
  AvgVideoCaption_76210_Content_58 = {
    Text = "Am ersten Tag, an dem ich die Tafel erhielt, dachte ich, sie sei nichts weiter als ein Bluff."
  },
  AvgVideoCaption_76210_Content_59 = {
    Text = "Aber, ich habe nur die erste Zeile gelesen."
  },
  AvgVideoCaption_76210_Content_6 = {
    Text = "Keine andere Möglichkeit. Ich werde es selbst tun."
  },
  AvgVideoCaption_76210_Content_60 = {
    Text = "Nein... eine halbe Zeile"
  },
  AvgVideoCaption_76210_Content_61 = {
    Text = "Ich erkannte es sofort—es war definitiv das Original."
  },
  AvgVideoCaption_76210_Content_62 = {
    Text = "Das Gefühl der Ekstase überwältigte mich"
  },
  AvgVideoCaption_76210_Content_63 = {
    Text = "Lass mich dir dieses Gefühl beschreiben. Es ist genau wie das, was du jetzt erlebst."
  },
  AvgVideoCaption_76210_Content_64 = {
    Text = "Eine fast unmerkliche, leichte Lähmung aus unbekannter Quelle."
  },
  AvgVideoCaption_76210_Content_65 = {
    Text = "Ich habe keine Anzeichen einer drohenden Gefahr bemerkt und fühlte mich sogar ein wenig wohl..."
  },
  AvgVideoCaption_76210_Content_66 = {
    Text = "Natürlich! Die Wahrheit der Welt, die ultimative Antwort, die ich suche, könnte direkt vor mir liegen."
  },
  AvgVideoCaption_76210_Content_67 = {
    Text = "Wie von Honig verlockt, habe ich unwissentlich und gierig weitergelesen, voller Eifer."
  },
  AvgVideoCaption_76210_Content_68 = {
    Text = "Schritt für Schritt in die ultimative Falle..."
  },
  AvgVideoCaption_76210_Content_69 = {
    Text = "Ich bin in eine Falle getappt"
  },
  AvgVideoCaption_76210_Content_7 = {
    Text = "Mythags Welpe, das ist deine Ehre."
  },
  AvgVideoCaption_76210_Content_70 = {
    Text = "Eine Falle, die ausschließlich für mich entworfen wurde, diesen arroganten und heuchlerischen Genie!"
  },
  AvgVideoCaption_76210_Content_71 = {
    Text = "Ja! Direkt in der Mitte dieser Tafel hat eine massive Falle lange auf ihre Gelegenheit gewartet!"
  },
  AvgVideoCaption_76210_Content_72 = {
    Text = "Schritt für Schritt kam ich näher, fast weinend vor Freude!"
  },
  AvgVideoCaption_76210_Content_73 = {
    Text = "Bis ich die Bedeutung dessen, was ich las, erkannte, war es schon zu spät!"
  },
  AvgVideoCaption_76210_Content_74 = {
    Text = "Ich weiß alles! Ich kenne die Antwort! Ich weiß ▼▼!!"
  },
  AvgVideoCaption_76210_Content_75 = {
    Text = "Kannst du es fühlen?"
  },
  AvgVideoCaption_76210_Content_76 = {
    Text = "Dieser unerträgliche, knochenkalte Schmerz, diese unerträgliche Verzweiflung!"
  },
  AvgVideoCaption_76210_Content_77 = {
    Text = "Wahnsinn erzeugende, pechschwarze Verzweiflung!"
  },
  AvgVideoCaption_76210_Content_78 = {
    Text = "Entschuldigung, Mythags Welpe. Ich habe wieder die Kontrolle über meine Emotionen verloren."
  },
  AvgVideoCaption_76210_Content_79 = {
    Text = "Aber seien Sie versichert, obwohl die Technik etwas grob war, entspricht das Aktivitätsniveau definitiv dem Standard."
  },
  AvgVideoCaption_76210_Content_8 = {
    Text = "Ein spezifisches Problem wurde festgestellt. Die von Ihnen gewählte Gehirngefäßaktivität reicht nicht aus, um das Bewusstsein des Hüters von Mythag zu erhalten."
  },
  AvgVideoCaption_76210_Content_80 = {
    Text = "Ich werde dir jetzt helfen, den Sensor zu verbinden."
  },
  AvgVideoCaption_76210_Content_81 = {
    Text = "Bald wirst du in diese Welt kommen."
  },
  AvgVideoCaption_76210_Content_82 = {
    Text = "Als nächstes, werden wir auf den Moment warten, an dem du erwachst. Wie wirst du dann deinem eigenen Erscheinungsbild gegenüberstehen?"
  },
  AvgVideoCaption_76210_Content_83 = {
    Text = "Ich freue mich auf das Kommen jenes Tages."
  },
  AvgVideoCaption_76210_Content_9 = {
    Text = "Aber eine weitere Übertragung birgt ein höheres Risiko des Bewusstseinsverlusts."
  },
  AvgVideoCaption_81062_Content_1 = {
    Text = "Mein Liebling, komm mit mir"
  },
  AvgVideoCaption_81062_Content_10 = {
    Text = "Die trockenen Blätter rascheln unter deinen Füßen."
  },
  AvgVideoCaption_81062_Content_11 = {
    Text = "Ist Ihr Atem leichter als vor drei Sekunden?"
  },
  AvgVideoCaption_81062_Content_12 = {
    Text = "Heben Sie den Kopf und schauen Sie... vor Ihnen erscheint eine kleine Waldhütte"
  },
  AvgVideoCaption_81062_Content_13 = {
    Text = "Jetzt betreten Sie die quietschende Treppe"
  },
  AvgVideoCaption_81062_Content_14 = {
    Text = "Die vertraute Holztür öffnen"
  },
  AvgVideoCaption_81062_Content_15 = {
    Text = "Hör dir das an, das Knistern des Kamins"
  },
  AvgVideoCaption_81062_Content_16 = {
    Text = "persischer Teppich"
  },
  AvgVideoCaption_81062_Content_17 = {
    Text = "dunkelrotes Samtsofa mit schwarzem Schimmer"
  },
  AvgVideoCaption_81062_Content_18 = {
    Text = "Umgekipptes Weinglas und verschütteter Rotwein"
  },
  AvgVideoCaption_81062_Content_19 = {
    Text = "Genau so, wie Sie sich erinnern"
  },
  AvgVideoCaption_81062_Content_2 = {
    Text = "Bitte setze dich auf das gegenüberliegende Sofa"
  },
  AvgVideoCaption_81062_Content_20 = {
    Text = "Lass uns noch einmal darüber nachdenken"
  },
  AvgVideoCaption_81062_Content_21 = {
    Text = "Liegt auf diesem Sofa wirklich nichts?"
  },
  AvgVideoCaption_81062_Content_22 = {
    Text = "Wurde der persische Teppich wirklich durch den vorherigen Rotwein gefärbt?"
  },
  AvgVideoCaption_81062_Content_23 = {
    Text = "Pssst... bleib ruhig und versuche nicht zu fliehen"
  },
  AvgVideoCaption_81062_Content_24 = {
    Text = "Eure Gliedmaßen sind bereits kraftlos und bewegungsunfähig."
  },
  AvgVideoCaption_81062_Content_25 = {
    Text = "Höre mir mit ganzem Herzen zu... spüre es intensiv"
  },
  AvgVideoCaption_81062_Content_26 = {
    Text = "Beginnt das dritte Gelenk der Wirbelsäule zu jucken?"
  },
  AvgVideoCaption_81062_Content_27 = {
    Text = "Scheinbar ist Ihr Speicher bereits wiedererwacht"
  },
  AvgVideoCaption_81062_Content_28 = {
    Text = "Die auf dem Sofa liegende verrottete Leiche"
  },
  AvgVideoCaption_81062_Content_29 = {
    Text = "Ist es nicht genau dein väterlicher und respektabler Vater?"
  },
  AvgVideoCaption_81062_Content_3 = {
    Text = "Ist die Kaminwärme angemessen?"
  },
  AvgVideoCaption_81062_Content_30 = {
    Text = "Haben Sie es vergessen? Könnten Sie es wirklich vergessen haben?"
  },
  AvgVideoCaption_81062_Content_31 = {
    Text = "Nein, Sie haben es überhaupt nicht vergessen..."
  },
  AvgVideoCaption_81062_Content_32 = {
    Text = "Nur, dass du hier eine geheime Kiste verwendest"
  },
  AvgVideoCaption_81062_Content_33 = {
    Text = "Es wurde in Vergessenheit gelegt"
  },
  AvgVideoCaption_81062_Content_34 = {
    Text = "Dieses treue Gehirn der vergangenen siebenundzwanzig Jahre"
  },
  AvgVideoCaption_81062_Content_35 = {
    Text = "Nicht die kleinste Andeutung deines wahren Aussehens ist nach außen gedrungen."
  },
  AvgVideoCaption_81062_Content_36 = {
    Text = "Wirklich lobenswert"
  },
  AvgVideoCaption_81062_Content_37 = {
    Text = "Womit sind Sie gefesselt?"
  },
  AvgVideoCaption_81062_Content_38 = {
    Text = "Schrei die Schreie deines Herzens heraus"
  },
  AvgVideoCaption_81062_Content_39 = {
    Text = "Schrei deine Sehnsucht und dein Verlangen heraus"
  },
  AvgVideoCaption_81062_Content_4 = {
    Text = "Diese Uhr und das rote Samtsofa kommen dir sehr vertraut vor?"
  },
  AvgVideoCaption_81062_Content_40 = {
    Text = "„Wir“ werden dich so akzeptieren, wie du bist..."
  },
  AvgVideoCaption_81062_Content_41 = {
    Text = "Moral ist nichts weiter als eine minderwertige Angelschnur, die zwischen den Synapsen der Menschen eingenäht wurde"
  },
  AvgVideoCaption_81062_Content_42 = {
    Text = "Lassen Sie uns den Haken nun sanft...aus dem Mandelkern...herausziehen..."
  },
  AvgVideoCaption_81062_Content_43 = {
    Text = "Sag es mir, lieber Freund..."
  },
  AvgVideoCaption_81062_Content_44 = {
    Text = "Für die Freiheit ... und für das Hochgefühl, das danach entfesselt wurde"
  },
  AvgVideoCaption_81062_Content_45 = {
    Text = "Was haben Sie getan?"
  },
  AvgVideoCaption_81062_Content_46 = {
    Text = "Die dreißig Sekunden, in denen du im Keller die Kerze löschtest, als du sieben Jahre alt warst"
  },
  AvgVideoCaption_81062_Content_47 = {
    Text = "Wovor hast du Angst?"
  },
  AvgVideoCaption_81062_Content_48 = {
    Text = "Sind das Schritte vor der Tür?"
  },
  AvgVideoCaption_81062_Content_49 = {
    Text = "Oder das Lächeln, das gleich erblühen wird?"
  },
  AvgVideoCaption_81062_Content_5 = {
    Text = "Natürlich ist es unser Grundsatz, die Patienten zu beruhigen"
  },
  AvgVideoCaption_81062_Content_50 = {
    Text = "Das Ertrinkungsereignis, das Sie als „Unfall“ bezeichneten..."
  },
  AvgVideoCaption_81062_Content_51 = {
    Text = "Im letzten Kampf des Ertrinkenden"
  },
  AvgVideoCaption_81062_Content_52 = {
    Text = "Widerspiegelt deinen Mund, der vor sich hin singt"
  },
  AvgVideoCaption_81062_Content_53 = {
    Text = "Widerstand ist zwecklos, bleib ruhig..."
  },
  AvgVideoCaption_81062_Content_54 = {
    Text = "Sie werden nicht wissen wollen, wohin der letzte um sein Leben kämpfende Mann gegangen ist"
  },
  AvgVideoCaption_81062_Content_55 = {
    Text = "Aber die Rosen im Hinterhof der Kirche blühen dieses Jahr besonders üppig, nicht wahr?"
  },
  AvgVideoCaption_81062_Content_56 = {
    Text = "Braves Kind"
  },
  AvgVideoCaption_81062_Content_57 = {
    Text = "Jetzt, gib mir deine Hand"
  },
  AvgVideoCaption_81062_Content_58 = {
    Text = "Auf meinen Handteller..."
  },
  AvgVideoCaption_81062_Content_59 = {
    Text = "Genau hinsehen"
  },
  AvgVideoCaption_81062_Content_6 = {
    Text = "Nun, schau über das Pendel hinweg in meine Augen"
  },
  AvgVideoCaption_81062_Content_60 = {
    Text = "Kann man das noch eine Hand nennen?"
  },
  AvgVideoCaption_81062_Content_61 = {
    Text = "Chitin wächst"
  },
  AvgVideoCaption_81062_Content_62 = {
    Text = "Der Panzer wird die schwache, weiche und hilflose Hülle bedecken..."
  },
  AvgVideoCaption_81062_Content_63 = {
    Text = "Kein Grund, Angst zu haben"
  },
  AvgVideoCaption_81062_Content_64 = {
    Text = "Bitte schonen Sie Ihre Stimmbänder schonend"
  },
  AvgVideoCaption_81062_Content_65 = {
    Text = "Es ist noch nicht vollständig verwandelt..."
  },
  AvgVideoCaption_81062_Content_66 = {
    Text = "Die moralischen Fesseln, mit denen sich die Menschheit selbst gefangen hält"
  },
  AvgVideoCaption_81062_Content_67 = {
    Text = "Es löst sich gerade Stück für Stück, oder?"
  },
  AvgVideoCaption_81062_Content_68 = {
    Text = "Wie eine Schlangenhaut, die ihre alte, nutzlose Haut abstreift..."
  },
  AvgVideoCaption_81062_Content_69 = {
    Text = "Ich werde dich freilassen..."
  },
  AvgVideoCaption_81062_Content_7 = {
    Text = "Tiefen Atemzug"
  },
  AvgVideoCaption_81062_Content_70 = {
    Text = "Genau so... lässt die Iris sich in eine perfekte sechseckige Matrix aufspalten"
  },
  AvgVideoCaption_81062_Content_71 = {
    Text = "Lasset uns diesen uralten Behälter preisen, der bald erwachen wird..."
  },
  AvgVideoCaption_81062_Content_72 = {
    Text = "Um endgültig mit der verrotteten Vergangenheit abzuschließen"
  },
  AvgVideoCaption_81062_Content_73 = {
    Text = "Lass uns unsere sozialen Masken in konzentrierte Schwefelsäure tauchen..."
  },
  AvgVideoCaption_81062_Content_74 = {
    Text = "Zusammen mit Ihrem lächerlichen Bankkonto und Ihrem Abschlusszeugnis"
  },
  AvgVideoCaption_81062_Content_75 = {
    Text = "Sieh, wie sie verfaulen und sich auflösen wie Humus im Insektennest"
  },
  AvgVideoCaption_81062_Content_76 = {
    Text = "Gut, gut..."
  },
  AvgVideoCaption_81062_Content_77 = {
    Text = "Tiefer Atem..."
  },
  AvgVideoCaption_81062_Content_78 = {
    Text = "Jetzt sprich mit mir"
  },
  AvgVideoCaption_81062_Content_79 = {
    Text = "Ich entferne freiwillig die schlechten Genstränge des Homo sapiens"
  },
  AvgVideoCaption_81062_Content_8 = {
    Text = "Die Wärme des Kamins steigt langsam an deinen Knöcheln auf"
  },
  AvgVideoCaption_81062_Content_80 = {
    Text = "Neuronale Synapsen mit dem Nest-Cloud-System verbinden"
  },
  AvgVideoCaption_81062_Content_81 = {
    Text = "Was man als Menschlichkeit bezeichnet, ist nur eine lächerliche Nachahmung"
  },
  AvgVideoCaption_81062_Content_82 = {
    Text = "Wie ein Schmetterling, der kurzzeitig die Gestalt eines Blattes annimmt"
  },
  AvgVideoCaption_81062_Content_83 = {
    Text = "Jetzt ist es an der Zeit, zum ewigen Nest der Kolonie zurückzukehren"
  },
  AvgVideoCaption_81062_Content_84 = {
    Text = "Kannst du den Herzschlag schon nicht mehr hören?"
  },
  AvgVideoCaption_81062_Content_85 = {
    Text = "Die Flügelschlagfrequenz des Insektenrudels hatte den erbärmlichen Herzschlag bereits ersetzt ..."
  },
  AvgVideoCaption_81062_Content_86 = {
    Text = "Verabschiede dich von diesem alten Körper, der gerade zu Kohle wird"
  },
  AvgVideoCaption_81062_Content_87 = {
    Text = "Sie, die im rechtlichen Sinne „tot“ sind"
  },
  AvgVideoCaption_81062_Content_88 = {
    Text = "Die erste Nestkapsel wird in zehn Minuten erhalten"
  },
  AvgVideoCaption_81062_Content_89 = {
    Text = "Schließen Sie Ihre Augen"
  },
  AvgVideoCaption_81062_Content_9 = {
    Text = "Stellen Sie sich vor, wie Sie nun auf einem Pfad im Hyde Park spazieren gehen"
  },
  AvgVideoCaption_81062_Content_90 = {
    Text = "Akzeptiere die Dunkelheit vor dir..."
  },
  AvgVideoCaption_81062_Content_91 = {
    Text = "Dann öffne deine wahren Augen erneut..."
  },
  AvgVideoCaption_81062_Content_92 = {
    Text = "Glückwunsch... Sie sind nun näher an den Göttern als jeder andere Mensch"
  },
  AvgVideoCaption_81062_Content_93 = {
    Text = "Die universelle Wahrheit, die durch ein 360-Grad-Komplexauge gesehen wird..."
  },
  AvgVideoCaption_81062_Content_94 = {
    Text = "Willkommen in der Resonanz der Billionen Herzen in den Tiefen der Erdadern..."
  },
  AvgVideoCaption_81062_Content_95 = {
    Text = "Willkommen als sein perfekter Behälter..."
  },
  AvgVideoCaption_81062_Content_96 = {
    Text = "Willkommen zu Hause"
  },
  AvgVideoCaption_81283_Content_1 = {
    Text = "Ich fühle mit dir den Schmerz"
  },
  AvgVideoCaption_81283_Content_10 = {
    Text = "Lass mich deine Seele berühren"
  },
  AvgVideoCaption_81283_Content_11 = {
    Text = "Berühre all deinen tief verborgenen Schmerz und dein Verlangen"
  },
  AvgVideoCaption_81283_Content_12 = {
    Text = "Ah, genau so..."
  },
  AvgVideoCaption_81283_Content_13 = {
    Text = "Die psychologische Beratung ist endlich bei meinem Lieblingsteil angelangt"
  },
  AvgVideoCaption_81283_Content_14 = {
    Text = "Traurigkeit, Angst, Hilflosigkeit"
  },
  AvgVideoCaption_81283_Content_15 = {
    Text = "Neurotransmitter enthüllte mir deine wahre Wahrheit"
  },
  AvgVideoCaption_81283_Content_16 = {
    Text = "Aber noch nicht genug, bei weitem noch nicht genug"
  },
  AvgVideoCaption_81283_Content_17 = {
    Text = "Zeig mir noch mehr!"
  },
  AvgVideoCaption_81283_Content_18 = {
    Text = "Schicht für Schicht wird dein Herz und deine Seele enthüllt"
  },
  AvgVideoCaption_81283_Content_19 = {
    Text = "Zeige mir deine tiefste Verzweiflung, deinen Kampf"
  },
  AvgVideoCaption_81283_Content_2 = {
    Text = "Vollständig nachempfinden"
  },
  AvgVideoCaption_81283_Content_20 = {
    Text = "Zum Verkosten für mich..."
  },
  AvgVideoCaption_81283_Content_21 = {
    Text = "Ah... Entschuldigung"
  },
  AvgVideoCaption_81283_Content_22 = {
    Text = "Zu viel Spaß beim Reden mit dem höheren Patienten"
  },
  AvgVideoCaption_81283_Content_23 = {
    Text = "Lange gewartet! Bitte treten Sie ein."
  },
  AvgVideoCaption_81283_Content_24 = {
    Text = "Lass uns gemeinsam eine Seelenreise beginnen"
  },
  AvgVideoCaption_81283_Content_3 = {
    Text = "und verstehe auch, wie sehr du ein neues Leben ersehnst"
  },
  AvgVideoCaption_81283_Content_4 = {
    Text = "Kein Problem, überlass alles mir"
  },
  AvgVideoCaption_81283_Content_5 = {
    Text = "Ich werde dich heilen"
  },
  AvgVideoCaption_81283_Content_6 = {
    Text = "Die wahre Selbsterkenntnis"
  },
  AvgVideoCaption_81283_Content_7 = {
    Text = "Jetzt, entspann dich..."
  },
  AvgVideoCaption_81283_Content_8 = {
    Text = "Zeig mir dein Inneres"
  },
  AvgVideoCaption_81283_Content_9 = {
    Text = "Öffne mir dein Unterbewusstsein und deine Spiritualität"
  },
  AvgVideoCaption_84327_Content_1 = {
    Text = "Das Schiff sinkt! Öffne schnell die Tür!"
  },
  AvgVideoCaption_84327_Content_10 = {
    Text = "Er ist der einzige „Passagier“ auf der Nautilus."
  },
  AvgVideoCaption_84327_Content_100 = {
    Text = "Aber in diesem Moment bin ich kein Mensch mehr"
  },
  AvgVideoCaption_84327_Content_101 = {
    Text = "Daher das Wesen, das uns gerufen hat"
  },
  AvgVideoCaption_84327_Content_102 = {
    Text = "führten mich, versprachen mir"
  },
  AvgVideoCaption_84327_Content_103 = {
    Text = "Das versunkene Reich erzählt in den Strömungen der Tiefsee von seiner Vergangenheit"
  },
  AvgVideoCaption_84327_Content_104 = {
    Text = "Und das bereits gebrochene Elfenbein-Kopfrelief enthüllte mir auch den wahren Gott"
  },
  AvgVideoCaption_84327_Content_105 = {
    Text = "In diesem Moment spielen Realität und Halluzination keine Rolle mehr"
  },
  AvgVideoCaption_84327_Content_106 = {
    Text = "Für einen Gott ist alles Nichts, alles ist sinnlos"
  },
  AvgVideoCaption_84327_Content_107 = {
    Text = "Das Meerwasser umarmt, umhüllt und verschlingt mich nach wie vor"
  },
  AvgVideoCaption_84327_Content_108 = {
    Text = "Und hinter dem großen Tor liegen die unendlichen Dimensionen und die Leere"
  },
  AvgVideoCaption_84327_Content_109 = {
    Text = "Mein oberflächliches Gehirn ist vollständig von der tiefen See durchdrungen worden"
  },
  AvgVideoCaption_84327_Content_11 = {
    Text = "Ja, du warst es, die mich gerettet hat?"
  },
  AvgVideoCaption_84327_Content_110 = {
    Text = "Kann nicht mehr denken, nicht einmal im Geringsten"
  },
  AvgVideoCaption_84327_Content_111 = {
    Text = "Und mein Körper unterwarf sich diesem Meer"
  },
  AvgVideoCaption_84327_Content_112 = {
    Text = "Jene endlosen Dimensionen und das Meer der Leere"
  },
  AvgVideoCaption_84327_Content_113 = {
    Text = "Wird meine neue Richtung sein"
  },
  AvgVideoCaption_84327_Content_12 = {
    Text = "Willkommen an Bord der Nautilus"
  },
  AvgVideoCaption_84327_Content_13 = {
    Text = "Ich bin die Navigatorin dieses Schiffes, Kupferspange"
  },
  AvgVideoCaption_84327_Content_14 = {
    Text = "Bitte schützen Sie das Schiff und halten Sie die Ordnung ein"
  },
  AvgVideoCaption_84327_Content_15 = {
    Text = "und merken Sie sich die Nummer des Rettungsboots, die normalerweise auf der Rückseite Ihrer Zimmertürkarte steht"
  },
  AvgVideoCaption_84327_Content_16 = {
    Text = "Aber laut den Regeln können Piraten keine Zimmerschlüsselkarte erhalten"
  },
  AvgVideoCaption_84327_Content_17 = {
    Text = "Es tut mir sehr leid"
  },
  AvgVideoCaption_84327_Content_18 = {
    Text = "Hä? Das hat überhaupt nichts mit der Zimmerschlüsselkarte zu tun!"
  },
  AvgVideoCaption_84327_Content_19 = {
    Text = "Hier, hier ist die Tiefsee"
  },
  AvgVideoCaption_84327_Content_2 = {
    Text = "Rette... mich... rette mich..."
  },
  AvgVideoCaption_84327_Content_20 = {
    Text = "Ich atme unter Wasser! Ich lebe!"
  },
  AvgVideoCaption_84327_Content_21 = {
    Text = "Ah, ich muss wahnsinnig sein"
  },
  AvgVideoCaption_84327_Content_22 = {
    Text = "Wie man so sagt, bin ich von dem Moment an verrückt gewesen, als ich das seltsame Elfenbein-Kopfrelief erhalten habe"
  },
  AvgVideoCaption_84327_Content_23 = {
    Text = "Was Elfenbeinkopf, was Lemuria – alles Halluzinationen, alles nur Träume!"
  },
  AvgVideoCaption_84327_Content_24 = {
    Text = "Der Traum ist vorbei, ich gehe nach Hause"
  },
  AvgVideoCaption_84327_Content_25 = {
    Text = "Ja, nach Hause, nach Hause..."
  },
  AvgVideoCaption_84327_Content_26 = {
    Text = "Nun, da sollten Sie wohl Ihre Lage verstanden haben"
  },
  AvgVideoCaption_84327_Content_27 = {
    Text = "Hier ist die gesunkene Nautilus – und hier ist auch die Tiefsee."
  },
  AvgVideoCaption_84327_Content_28 = {
    Text = "Bald werden wir auf den Meeresgrund sinken"
  },
  AvgVideoCaption_84327_Content_29 = {
    Text = "Ich werde alles tun, um Ihr Leben zu verlängern"
  },
  AvgVideoCaption_84327_Content_3 = {
    Text = "Dieser Tag war der 12. September"
  },
  AvgVideoCaption_84327_Content_30 = {
    Text = "Aber als Navigator und einziger Matrose"
  },
  AvgVideoCaption_84327_Content_31 = {
    Text = "Ich muss den Passagieren gegenüber eingestehen, dass meine Fähigkeiten begrenzt sind."
  },
  AvgVideoCaption_84327_Content_32 = {
    Text = "Seit jenem Tag schwieg der Pirat"
  },
  AvgVideoCaption_84327_Content_33 = {
    Text = "Er versuchte nicht mehr zu entkommen, sondern blieb am Fenster der mit Wasser gefüllten Schiffskabine stehen"
  },
  AvgVideoCaption_84327_Content_34 = {
    Text = "Durch das Fenster in die Tiefsee blicken und leise vor sich hin murmeln"
  },
  AvgVideoCaption_84327_Content_35 = {
    Text = "Er lacht manchmal laut"
  },
  AvgVideoCaption_84327_Content_36 = {
    Text = "Manchmal Wahnsinn"
  },
  AvgVideoCaption_84327_Content_37 = {
    Text = "Manchmal rufend nach Lemuria"
  },
  AvgVideoCaption_84327_Content_38 = {
    Text = "Lemuria ruft mich"
  },
  AvgVideoCaption_84327_Content_39 = {
    Text = "manchmal rief sie „Mama“, „nach Hause“"
  },
  AvgVideoCaption_84327_Content_4 = {
    Text = "Am 791. Tag seitdem die Nautilus zu einem Geisterschiff wurde"
  },
  AvgVideoCaption_84327_Content_40 = {
    Text = "Lemuria, geh nach Hause..."
  },
  AvgVideoCaption_84327_Content_41 = {
    Text = "Ich muss nach Lemuria zurück..."
  },
  AvgVideoCaption_84327_Content_42 = {
    Text = "Ich habe viele Orte bereist, aber noch nie von “Lemuria“ gehört."
  },
  AvgVideoCaption_84327_Content_43 = {
    Text = "Wahrscheinlich der einzige Passagier auf der Nautilus"
  },
  AvgVideoCaption_84327_Content_44 = {
    Text = "Am Seefahrtdelirium erkrankt"
  },
  AvgVideoCaption_84327_Content_45 = {
    Text = "Es ist eine häufige Erkrankung während der Seefahrt"
  },
  AvgVideoCaption_84327_Content_46 = {
    Text = "Laut dem Schiffsarzt Ralph"
  },
  AvgVideoCaption_84327_Content_47 = {
    Text = "Dies ist das oberflächliche Gehirn der Menschen"
  },
  AvgVideoCaption_84327_Content_48 = {
    Text = "Symptome, die durch das Unvermögen entstehen, die Tiefe des Meeres vollständig zu erfassen"
  },
  AvgVideoCaption_84327_Content_49 = {
    Text = "In diesem Moment sind wir nicht auf dem Meer unterwegs"
  },
  AvgVideoCaption_84327_Content_5 = {
    Text = "Die Flucht des Piraten, der von seinen Gefährten verlassen wurde, ist gescheitert"
  },
  AvgVideoCaption_84327_Content_50 = {
    Text = "sondern im Meer und mit der Nautilus immer tiefer in die Tiefsee zu sinken"
  },
  AvgVideoCaption_84327_Content_51 = {
    Text = "Ein solcher Zustand könnte jeden in den Wahnsinn treiben"
  },
  AvgVideoCaption_84327_Content_52 = {
    Text = "Selbst ich..."
  },
  AvgVideoCaption_84327_Content_53 = {
    Text = "Bereits tot, das Bewusstsein aus unbekannten Gründen an die Nautilus gebunden"
  },
  AvgVideoCaption_84327_Content_54 = {
    Text = "Ich, die den jungen Piraten gerettet habe, habe auch Halluzinationen erlebt"
  },
  AvgVideoCaption_84327_Content_55 = {
    Text = "Ich sehe die Nautilus zurückkehren..."
  },
  AvgVideoCaption_84327_Content_56 = {
    Text = "Ich habe auch gesehen, wie die Nautilus unterging..."
  },
  AvgVideoCaption_84327_Content_57 = {
    Text = "Am Anfang hatte ich noch meinen Verstand."
  },
  AvgVideoCaption_84327_Content_58 = {
    Text = "Unterscheiden können, was Halluzination und was real ist"
  },
  AvgVideoCaption_84327_Content_59 = {
    Text = "Aber später..."
  },
  AvgVideoCaption_84327_Content_6 = {
    Text = "Mit dem Untergang der Nautilus im Meer"
  },
  AvgVideoCaption_84327_Content_60 = {
    Text = "Ich habe es gehört, ich habe es gehört"
  },
  AvgVideoCaption_84327_Content_61 = {
    Text = "Er ruft uns!"
  },
  AvgVideoCaption_84327_Content_62 = {
    Text = "Wer den Weg verloren hat, den wird mein Herr führen"
  },
  AvgVideoCaption_84327_Content_63 = {
    Text = "Wer wünscht, dem wird mein Herr gewähren."
  },
  AvgVideoCaption_84327_Content_64 = {
    Text = "Ja... ja, führe mich, versprich mir!"
  },
  AvgVideoCaption_84327_Content_65 = {
    Text = "Großer Herr, führe mich nach Lemuria und lass mich in dein Gottes Reich eintreten!"
  },
  AvgVideoCaption_84327_Content_66 = {
    Text = "Göttliches Reich! Im Göttlichen Reich werde ich Glückseligkeit erfahren und Unsterblichkeit erlangen."
  },
  AvgVideoCaption_84327_Content_67 = {
    Text = "Wird nach Hause kommen! Nach Hause! Nach Hause!"
  },
  AvgVideoCaption_84327_Content_68 = {
    Text = "Ralph hat recht"
  },
  AvgVideoCaption_84327_Content_69 = {
    Text = "Das oberflächliche menschliche Denken kann die Weite und Tiefe des Meeres nicht vollständig erfassen"
  },
  AvgVideoCaption_84327_Content_7 = {
    Text = "Ehrlich gesagt, hasse ich Piraten"
  },
  AvgVideoCaption_84327_Content_70 = {
    Text = "Daher, als die majestätische Stadt vor mir erschien"
  },
  AvgVideoCaption_84327_Content_71 = {
    Text = "Ich hielt es für eine Halluzination, die durch das Seefahrtdelirium verursacht wurde"
  },
  AvgVideoCaption_84327_Content_72 = {
    Text = "Das war eine Stadt, die sich nicht in Worte fassen ließ, unbeschreiblich."
  },
  AvgVideoCaption_84327_Content_73 = {
    Text = "mit einem antiken Glimmer schimmernd, gleichmäßig am Meeresboden verteilt"
  },
  AvgVideoCaption_84327_Content_74 = {
    Text = "In dieser pechschwarzen Tiefsee, stumm schlafend und stehend"
  },
  AvgVideoCaption_84327_Content_75 = {
    Text = "Stille Wartezeit"
  },
  AvgVideoCaption_84327_Content_76 = {
    Text = "Wir Besucher sind in das Netz geraten"
  },
  AvgVideoCaption_84327_Content_77 = {Text = "Lemuria!"},
  AvgVideoCaption_84327_Content_78 = {
    Text = "Es ist... Lemuria!"
  },
  AvgVideoCaption_84327_Content_79 = {
    Text = "Er ruft nach uns, ER ruft nach uns!"
  },
  AvgVideoCaption_84327_Content_8 = {
    Text = "Ich hasse alle Existenz, die die sichere Schifffahrt behindert"
  },
  AvgVideoCaption_84327_Content_80 = {
    Text = "Gefahr, komm nicht näher!"
  },
  AvgVideoCaption_84327_Content_81 = {
    Text = "So starb der einzige Passagier der Nautilus vor meinen Augen."
  },
  AvgVideoCaption_84327_Content_82 = {
    Text = "Es bleibt nur der seltsame Elfenbeinkopf"
  },
  AvgVideoCaption_84327_Content_83 = {
    Text = "Ich weiß, was in diesem Moment die vernünftigste Wahl wäre"
  },
  AvgVideoCaption_84327_Content_84 = {Text = "Aber..."},
  AvgVideoCaption_84327_Content_85 = {
    Text = "Ich bin eine Navigatorin – es ist meine Aufgabe, das Meer genau zu kennen."
  },
  AvgVideoCaption_84327_Content_86 = {
    Text = "Wenn die Bewusstseinskarte fehlerhaft ist"
  },
  AvgVideoCaption_84327_Content_87 = {
    Text = "Was ich tun muss, ist nicht fliehen, sondern korrigieren"
  },
  AvgVideoCaption_84327_Content_88 = {
    Text = "<Red:Also, nähere dich ihm>"
  },
  AvgVideoCaption_84327_Content_89 = {
    Text = "Und um Fehler zu korrigieren, braucht man..."
  },
  AvgVideoCaption_84327_Content_9 = {Text = "Aber..."},
  AvgVideoCaption_84327_Content_90 = {
    Text = "Muss das Problem tiefgehend verstehen und wahrnehmen"
  },
  AvgVideoCaption_84327_Content_91 = {
    Text = "Erkunde dieses Land der schlafenden Götter"
  },
  AvgVideoCaption_84327_Content_92 = {
    Text = "<Red:Also reagieren Sie darauf>"
  },
  AvgVideoCaption_84327_Content_93 = {
    Text = "Die Seefahrt der Menschenwelt kann nicht zum Glück führen"
  },
  AvgVideoCaption_84327_Content_94 = {
    Text = "Nur diejenigen, die alles geopfert haben, haben das Recht, einen Blick in das Göttliche Reich zu werfen."
  },
  AvgVideoCaption_84327_Content_95 = {
    Text = "<Red:Also, bekehre dich zu ihm!>"
  },
  AvgVideoCaption_84327_Content_96 = {
    Text = "<Red:Opfere alles!>"
  },
  AvgVideoCaption_84327_Content_97 = {
    Text = "Endlich, nachdem ich alles geopfert habe, sah ich es ..."
  },
  AvgVideoCaption_84327_Content_98 = {
    Text = "Jenes unermessliche, erhabene, grenzenlose, namenlose Wesen..."
  },
  AvgVideoCaption_84327_Content_99 = {
    Text = "Das oberflächliche menschliche Denken kann die Weite der Tiefsee nicht vollständig erfassen"
  },
  AvgVideoCaption_90244_Content_1 = {Text = "Ha..."},
  AvgVideoCaption_90244_Content_10 = {
    Text = "Gut gepackt... Die Federn sind bereits mit Blut verklebt"
  },
  AvgVideoCaption_90244_Content_100 = {
    Text = "In dem Manuskript gibt es so viele Orte, die wir noch nicht besucht haben – ich hätte wirklich Lust, sie alle zu besuchen."
  },
  AvgVideoCaption_90244_Content_101 = {
    Text = "Es wird passieren, ganz sicher"
  },
  AvgVideoCaption_90244_Content_102 = {
    Text = "Endlich brachte der Ritter die Prinzessin in sein Land zurück"
  },
  AvgVideoCaption_90244_Content_103 = {
    Text = "Unzählige Blumen wurden auf die Straße gestreut, um sie willkommen zu heißen"
  },
  AvgVideoCaption_90244_Content_104 = {
    Text = "Der gute Ruf des Ritters verbreitete sich nun im ganzen Land."
  },
  AvgVideoCaption_90244_Content_105 = {
    Text = "Ah, es ist vorbei"
  },
  AvgVideoCaption_90244_Content_106 = {
    Text = "Ich frage mich jedes Mal, was nach dem Ende der Geschichte geschehen wird."
  },
  AvgVideoCaption_90244_Content_107 = {
    Text = "Bruder, was ist später mit dem Ritter geschehen?"
  },
  AvgVideoCaption_90244_Content_108 = {
    Text = "Wird er Ruhm, Reichtum und die Liebe der Prinzessin erhalten?"
  },
  AvgVideoCaption_90244_Content_109 = {
    Text = "Ich weiß nicht..."
  },
  AvgVideoCaption_90244_Content_11 = {
    Text = "Ich räume zuerst diese schmutzigen Dinge auf"
  },
  AvgVideoCaption_90244_Content_110 = {
    Text = "Aber zumindest hat er bereits Ruhm erlangt, oder?"
  },
  AvgVideoCaption_90244_Content_111 = {
    Text = "Dann hat er die Prinzessin über tausend Meilen zurückgerettet"
  },
  AvgVideoCaption_90244_Content_112 = {
    Text = "Wird der König ihn belohnen?"
  },
  AvgVideoCaption_90244_Content_113 = {
    Text = "Stimmt, der König ist bestimmt kein geiziger Mensch"
  },
  AvgVideoCaption_90244_Content_114 = {
    Text = "Er floh mit der Prinzessin aus dem Schloss und durchquerte danach zahlreiche verschiedene Orte"
  },
  AvgVideoCaption_90244_Content_115 = {
    Text = "Die Prinzessin könnte ihn vielleicht auch lieben?"
  },
  AvgVideoCaption_90244_Content_116 = {
    Text = "Mmh... Das klingt vernünftig"
  },
  AvgVideoCaption_90244_Content_117 = {
    Text = "Obwohl der Ritter sagte, dass er nichts brauchte"
  },
  AvgVideoCaption_90244_Content_118 = {
    Text = "Aber man erhält trotzdem alles"
  },
  AvgVideoCaption_90244_Content_119 = {
    Text = "Wie erwartet erhält am Ende der Tapfere... alles..."
  },
  AvgVideoCaption_90244_Content_12 = {
    Text = "...es tut weh, oder? Entschuldigung, ich werde sanfter sein"
  },
  AvgVideoCaption_90244_Content_120 = {
    Text = "(Schläft schon... Die Flucht der letzten Tage war wirklich anstrengend)"
  },
  AvgVideoCaption_90244_Content_121 = {
    Text = "(Verlor viele Federn, schade... Hmm? Dieses Stück ist immer noch intakt)"
  },
  AvgVideoCaption_90244_Content_122 = {
    Text = "(Zuerst wegpacken, später für Pollux eine Kette anfertigen)"
  },
  AvgVideoCaption_90244_Content_123 = {
    Text = "(Der Mond ist so rund und der Sternenhimmel so schön)"
  },
  AvgVideoCaption_90244_Content_124 = {
    Text = "(Genau wie in dem Buch... Wer mutig ist, bekommt wirklich alles?)"
  },
  AvgVideoCaption_90244_Content_125 = {
    Text = "(Die Geschichte im Buch... sie wird mich schon nicht belügen...)"
  },
  AvgVideoCaption_90244_Content_126 = {
    Text = "(Gute Nacht, Ritter Pollux)"
  },
  AvgVideoCaption_90244_Content_13 = {Text = "Na, so gut"},
  AvgVideoCaption_90244_Content_14 = {
    Text = "Als bei der Verwandlungszeremonie meine Brust geöffnet und Schritt für Schritt Zaubersprüche in meine Organe eingeritzt wurden"
  },
  AvgVideoCaption_90244_Content_15 = {
    Text = "Dieser Schmerz zählt nicht."
  },
  AvgVideoCaption_90244_Content_16 = {
    Text = "... auch wieder wahr, du hast immer mehr Schmerzen ertragen als wir anderen"
  },
  AvgVideoCaption_90244_Content_17 = {
    Text = "(Ach, verdammt, das falsche Wort benutzt...)"
  },
  AvgVideoCaption_90244_Content_18 = {
    Text = "Es ist vorbei, Bruder"
  },
  AvgVideoCaption_90244_Content_19 = {
    Text = "Früher konnten wir nichts entscheiden, aber ab jetzt werden wir frei sein!"
  },
  AvgVideoCaption_90244_Content_2 = {
    Text = "Bis hierher geflohen, sollte das Monster uns nicht mehr verfolgen"
  },
  AvgVideoCaption_90244_Content_20 = {
    Text = "Lass mich noch einmal die Geschichte vom Manuskript vorlesen"
  },
  AvgVideoCaption_90244_Content_21 = {
    Text = "Genau wie nach jeder Verwandlungszeremonie zuvor: Ich hörte der Geschichte zu, und die Wunde tat nicht mehr weh"
  },
  AvgVideoCaption_90244_Content_22 = {Text = "Gut"},
  AvgVideoCaption_90244_Content_23 = {
    Text = "Dann... erzähle ich noch eine Geschichte – die Abenteuer des legendären Ritters"
  },
  AvgVideoCaption_90244_Content_24 = {
    Text = "Endlich angekommene Ritter finden das Monster im Schatten"
  },
  AvgVideoCaption_90244_Content_25 = {
    Text = "Fragen Sie es nach dem Verbleib der Prinzessin"
  },
  AvgVideoCaption_90244_Content_26 = {
    Text = "Das dunkelgrüne Monster ist so riesig wie ein Riese"
  },
  AvgVideoCaption_90244_Content_27 = {
    Text = "Ein unheimlicher, furchterregender Schrei drang aus den Tiefen seines zitternden Körpers"
  },
  AvgVideoCaption_90244_Content_28 = {
    Text = "Es hob die Axt hoch in die Luft"
  },
  AvgVideoCaption_90244_Content_29 = {
    Text = "Ein kaltes Licht wie ein Neumond durchbricht die stille Halle"
  },
  AvgVideoCaption_90244_Content_3 = {
    Text = "Ruh dich aus, Zisch..."
  },
  AvgVideoCaption_90244_Content_30 = {
    Text = "Tapferer Ritter, der still steht"
  },
  AvgVideoCaption_90244_Content_31 = {
    Text = "Nur eine goldene Mähne bewegte sich leicht im Wind"
  },
  AvgVideoCaption_90244_Content_32 = {
    Text = "Die Axt sauste herab, hielt jedoch kurz vor dem Hals des Ritters abrupt inne."
  },
  AvgVideoCaption_90244_Content_33 = {
    Text = "“Dies ist ein Schlag gegen dein Versprechen, treu zu bleiben.“"
  },
  AvgVideoCaption_90244_Content_34 = {
    Text = "Das Monster flüsterte mit zusammengebissenen Zähnen, und das Summen klang wie rostige Eisenplatten, die gegeneinanderrieben."
  },
  AvgVideoCaption_90244_Content_35 = {
    Text = "“Du hast dich dem heutigen Duell nicht entzogen und bist somit würdig, den Titel eines Ritters zu tragen.“"
  },
  AvgVideoCaption_90244_Content_36 = {
    Text = "Genau wie wir nicht von den heutigen Monstern besiegt wurden!"
  },
  AvgVideoCaption_90244_Content_37 = {
    Text = "Der zweite Hieb schlägt erneut zu"
  },
  AvgVideoCaption_90244_Content_38 = {
    Text = "Immer noch um einen Hauch vom Ziel entfernt, nur die Haut des Ritters verletzt..."
  },
  AvgVideoCaption_90244_Content_39 = {
    Text = "Pollux, sogar die größte Schwungfeder ist gebrochen"
  },
  AvgVideoCaption_90244_Content_4 = {
    Text = "Pollux! Deine Flügel sind schwer verletzt"
  },
  AvgVideoCaption_90244_Content_40 = {
    Text = "Du kümmertest dich doch sonst immer so sehr um sie..."
  },
  AvgVideoCaption_90244_Content_41 = {
    Text = "Schon gut, die Federn wachsen schon wieder nach – das ist doch das Abzeichen der Freiheit!"
  },
  AvgVideoCaption_90244_Content_42 = {
    Text = "Genau wie ein Ritter, oder?"
  },
  AvgVideoCaption_90244_Content_43 = {
    Text = "Mmh... Der Bereich um die Wunde ist sauber abgewischt"
  },
  AvgVideoCaption_90244_Content_44 = {
    Text = "Deine Federn sind ganz durcheinander – ich helfe dir, sie zu glätten"
  },
  AvgVideoCaption_90244_Content_45 = {
    Text = "Danke, Ritter Castor"
  },
  AvgVideoCaption_90244_Content_46 = {
    Text = "Erzähl weiter die Abenteuergeschichte!"
  },
  AvgVideoCaption_90244_Content_47 = {
    Text = "Gut, ich verstehe"
  },
  AvgVideoCaption_90244_Content_48 = {
    Text = "In den Augen des Monsters schimmerte Dankbarkeit"
  },
  AvgVideoCaption_90244_Content_49 = {
    Text = "“Dies ist die Strafe dafür, dass du meinen Nachkommen gerettet hast, ihr aber den Schlüssel gestohlen und dich damit in die Burg geschlichen hast.“"
  },
  AvgVideoCaption_90244_Content_5 = {
    Text = "Verdammnis, eben habe ich es nicht aufhalten können, wenn ich nur..."
  },
  AvgVideoCaption_90244_Content_50 = {
    Text = "Der Ritter hatte plötzlich eine Erleuchtung"
  },
  AvgVideoCaption_90244_Content_51 = {
    Text = "“Das Mädchen, das ins Wasser fiel, ist deine Tochter!“"
  },
  AvgVideoCaption_90244_Content_52 = {
    Text = "Das Monster nickte"
  },
  AvgVideoCaption_90244_Content_53 = {
    Text = "\"Stimmt, der nächste letzte Schlag wird unser eigentlicher Kampf sein.\""
  },
  AvgVideoCaption_90244_Content_54 = {
    Text = "Der Ritter hob sein Schwert und begrüßte das Monster mit der Klingenspitze nach oben."
  },
  AvgVideoCaption_90244_Content_55 = {
    Text = "In diesem Moment verschwand das Monster plötzlich"
  },
  AvgVideoCaption_90244_Content_56 = {
    Text = "Der Ritter bewegt sich vorsichtig vorwärts"
  },
  AvgVideoCaption_90244_Content_57 = {
    Text = "Die menschenleere Burg ist von verzerrten dunklen Schatten umgeben"
  },
  AvgVideoCaption_90244_Content_58 = {
    Text = "Nur das illusorische Geräusch des Monsters drang an sein Ohr"
  },
  AvgVideoCaption_90244_Content_59 = {
    Text = "„Tapferer Ritter, wofür kämpfst du eigentlich?“"
  },
  AvgVideoCaption_90244_Content_6 = {
    Text = "Gut, sag so etwas nicht, schließlich ist es unser erstes Mal, dass wir zusammen ausgehen"
  },
  AvgVideoCaption_90244_Content_60 = {
    Text = "“Ist es um Ruhm und Verehrung zu erlangen?“"
  },
  AvgVideoCaption_90244_Content_61 = {
    Text = "Eine Gruppe von Bürgern tauchte plötzlich auf und umzingelte die Ritter schichtweise."
  },
  AvgVideoCaption_90244_Content_62 = {
    Text = "Vor vielen lachenden Gesichtern wurde immer wieder sein Ruhm gepriesen."
  },
  AvgVideoCaption_90244_Content_63 = {
    Text = "Der Ritter bemerkte das seltsame Verhalten der Phantasma"
  },
  AvgVideoCaption_90244_Content_64 = {
    Text = "Sein Ausdruck blieb unerschütterlich und zerschmetterte augenblicklich die falschen Schatten."
  },
  AvgVideoCaption_90244_Content_65 = {
    Text = "“Also geht es um Belohnung und Reichtum?“"
  },
  AvgVideoCaption_90244_Content_66 = {
    Text = "Ein demütiger Diener tritt vor den Ritter."
  },
  AvgVideoCaption_90244_Content_67 = {
    Text = "Er hält die golden glänzenden Münzen und die kostbare Krone, in die ein blutroter Edelstein eingelassen ist"
  },
  AvgVideoCaption_90244_Content_68 = {
    Text = "Dem Ritter kriechend anbieten"
  },
  AvgVideoCaption_90244_Content_69 = {
    Text = "Der Ritter blickte nicht auf die Krone, welche unermesslichen Reichtum und Macht symbolisierte"
  },
  AvgVideoCaption_90244_Content_7 = {
    Text = "Schon gut, wir sind doch erfolgreich entkommen, oder? Sei froh, wir haben es wirklich gut gemacht!"
  },
  AvgVideoCaption_90244_Content_70 = {
    Text = "Er schlug mit dem Schwert und zerstreute das Phantasma des Dieners."
  },
  AvgVideoCaption_90244_Content_71 = {
    Text = "Die schrille Stimme des Monsters fuhr fort: „Oh? Vielleicht, um die Liebe der Prinzessin zu gewinnen?“"
  },
  AvgVideoCaption_90244_Content_72 = {
    Text = "Die schöne Gestalt der Prinzessin erscheint vor dem Ritter"
  },
  AvgVideoCaption_90244_Content_73 = {
    Text = "Ihre langen Wimpern flatterten, und mit verwirrtem Blick lehnte sie sich an den Ritter."
  },
  AvgVideoCaption_90244_Content_74 = {
    Text = "Der Ritter schlägt mit seinem Schwert gegen das Phantasma der Prinzessin,"
  },
  AvgVideoCaption_90244_Content_75 = {
    Text = "\"Nein, das ist es nicht. Ich kämpfe nur, um Leiden zu beenden, damit andere nicht mehr kämpfen müssen!\""
  },
  AvgVideoCaption_90244_Content_76 = {
    Text = "Im Moment, als der Ritter seine Worte beendete"
  },
  AvgVideoCaption_90244_Content_77 = {
    Text = "All die unzähligen, tentakelartig wogenden Schatten und die scheinbar realen Illusionen verschwanden."
  },
  AvgVideoCaption_90244_Content_78 = {
    Text = "Kling! Der Ritter parierte mit seinem Schwert die Axt des Ungeheuers und schlug sie zur Seite."
  },
  AvgVideoCaption_90244_Content_79 = {
    Text = "“Du hast deine Güte, Loyalität und Reinheit bewiesen“"
  },
  AvgVideoCaption_90244_Content_8 = {
    Text = "...Du hast recht, ich helfe dir zuerst, deine Wunde zu versorgen"
  },
  AvgVideoCaption_90244_Content_80 = {
    Text = "“Jetzt kannst du die Prinzessin mitnehmen.“"
  },
  AvgVideoCaption_90244_Content_81 = {
    Text = "Der schreckliche Geist verwandelte sich in einen Rauchfaden und verwehte langsam."
  },
  AvgVideoCaption_90244_Content_82 = {
    Text = "Zurückgeblieben ist nur eine uralte Rüstung, die mit grünem Rost bedeckt ist"
  },
  AvgVideoCaption_90244_Content_83 = {
    Text = "Der Ritter verbeugte sich tief vor der Rüstung."
  },
  AvgVideoCaption_90244_Content_84 = {
    Text = "Er stieg Schritt für Schritt die rotierenden Stufen hinauf"
  },
  AvgVideoCaption_90244_Content_85 = {
    Text = "Endlich habe ich die Prinzessin auf der Burgspitze gefunden"
  },
  AvgVideoCaption_90244_Content_86 = {
    Text = "Die in der Burg gefangene Prinzessin ähnelt wirklich unserer früheren Selbst"
  },
  AvgVideoCaption_90244_Content_87 = {
    Text = "Aber es kommt kein Ritter, um uns zu retten ..."
  },
  AvgVideoCaption_90244_Content_88 = {
    Text = "Wir haben uns selbst gerettet"
  },
  AvgVideoCaption_90244_Content_89 = {
    Text = "Wir sind unsere eigenen Ritter"
  },
  AvgVideoCaption_90244_Content_9 = {Text = "...Okay!"},
  AvgVideoCaption_90244_Content_90 = {
    Text = "Stimmt! Hahaha!"
  },
  AvgVideoCaption_90244_Content_91 = {
    Text = "Wenn man es so betrachtet, muss die mutige Prinzessin nur ihr Schwert erheben"
  },
  AvgVideoCaption_90244_Content_92 = {
    Text = "Diese Geschichte handelt nicht von Rittern"
  },
  AvgVideoCaption_90244_Content_93 = {
    Text = "Ja, aber der Ritter hat die Prinzessin immer noch gerettet"
  },
  AvgVideoCaption_90244_Content_94 = {
    Text = "Er nahm die Prinzessin auf sein Pferd und ritt unter dem weiten Sternenhimmel und dem runden Mond davon."
  },
  AvgVideoCaption_90244_Content_95 = {
    Text = "Sie durchqueren weite Grasländer und klare Bäche"
  },
  AvgVideoCaption_90244_Content_96 = {
    Text = "Durchquere majestätische Gebirge und üppige Wälder"
  },
  AvgVideoCaption_90244_Content_97 = {
    Text = "Steppe, hohe Berge..."
  },
  AvgVideoCaption_90244_Content_98 = {
    Text = "Überlege, wohin wir gehen sollen?"
  },
  AvgVideoCaption_90244_Content_99 = {
    Text = "Und das Meer, die Wüste, das Land und die Weiden"
  },
  AvgVideoCaption_96010_Content_1 = {
    Text = "Willkommen in meinem Schloss, Mr. Pickman"
  },
  AvgVideoCaption_96010_Content_10 = {Text = "Aber..."},
  AvgVideoCaption_96010_Content_100 = {Text = "Natürlich"},
  AvgVideoCaption_96010_Content_101 = {
    Text = "Iss weiter, Mr. Pickman, iss alles"
  },
  AvgVideoCaption_96010_Content_102 = {
    Text = "Seine Knochen und Muskeln zerfetzen, sein Herz herausschneiden"
  },
  AvgVideoCaption_96010_Content_103 = {
    Text = "Höre die Bitten der Seelen, die dir ins Ohr flüstern"
  },
  AvgVideoCaption_96010_Content_104 = {
    Text = "Wahrheitsgetreue Aufzeichnung jedes Bildes, das du siehst"
  },
  AvgVideoCaption_96010_Content_105 = {
    Text = "Genieße die Ehre, ein Ghul zu sein"
  },
  AvgVideoCaption_96010_Content_106 = {
    Text = "Jeder Bürger meines Königreichs"
  },
  AvgVideoCaption_96010_Content_107 = {
    Text = "damit sie für diese grausame Ewigkeit leben"
  },
  AvgVideoCaption_96010_Content_108 = {
    Text = "Nun, das angenehme Abendessen ist hiermit beendet"
  },
  AvgVideoCaption_96010_Content_109 = {
    Text = "Bei diesem Jahr's Fest der Geister werden wir mit Sicherheit ein Meisterwerk zu sehen bekommen"
  },
  AvgVideoCaption_96010_Content_11 = {
    Text = "Wenn ich das sagen darf, Mr. Pickman"
  },
  AvgVideoCaption_96010_Content_110 = {
    Text = "Willkommen in der Stadt der Skelette, zukünftiger Meister"
  },
  AvgVideoCaption_96010_Content_111 = {
    Text = "Herr Pickman"
  },
  AvgVideoCaption_96010_Content_12 = {
    Text = "Dein vergangenes Bild"
  },
  AvgVideoCaption_96010_Content_13 = {
    Text = "Allesamt nur banale Werke, die in den dummen Vorstellungen der Menschen gefangen sind"
  },
  AvgVideoCaption_96010_Content_14 = {
    Text = "Und das ist auch der Grund dafür, warum ich dich hierher eingeladen habe"
  },
  AvgVideoCaption_96010_Content_15 = {
    Text = "Wir benötigen ein Meisterwerk für unser großes Fest"
  },
  AvgVideoCaption_96010_Content_16 = {
    Text = "Und du musst die wahre Kunst sehen"
  },
  AvgVideoCaption_96010_Content_17 = {
    Text = "Ein menschlicher Leichnam?"
  },
  AvgVideoCaption_96010_Content_18 = {Text = "Das ist..."},
  AvgVideoCaption_96010_Content_19 = {
    Text = "Kannst du es riechen?"
  },
  AvgVideoCaption_96010_Content_2 = {
    Text = "Bitte setzen Sie sich"
  },
  AvgVideoCaption_96010_Content_20 = {
    Text = "Eiche, Zedernholz und Vetiver verleihen einen frischen Duft"
  },
  AvgVideoCaption_96010_Content_21 = {
    Text = "Drei Jahrhunderte lang hat er in diesem Sarg verbracht."
  },
  AvgVideoCaption_96010_Content_22 = {
    Text = "Damit erhielt ich die Ehre, heute Abend am Festmahl teilzunehmen"
  },
  AvgVideoCaption_96010_Content_23 = {
    Text = "Einige notwendige Vorbereitungen vor dem Essen"
  },
  AvgVideoCaption_96010_Content_24 = {
    Text = "0,5 Zoll tiefe Schnittwunde"
  },
  AvgVideoCaption_96010_Content_25 = {
    Text = "Entlang der Halswirbelsäule und der Rippen, Knochen und Fleisch voneinander trennen"
  },
  AvgVideoCaption_96010_Content_26 = {
    Text = "Was machst du... mit seinen Eingeweiden..."
  },
  AvgVideoCaption_96010_Content_27 = {
    Text = "Verdammter Mist, ich muss hier raus"
  },
  AvgVideoCaption_96010_Content_28 = {
    Text = "Was macht ihr... lasst mich los"
  },
  AvgVideoCaption_96010_Content_29 = {
    Text = "Bitte seien Sie ruhig, Herr Maler"
  },
  AvgVideoCaption_96010_Content_3 = {
    Text = "Ich habe gehört, dass man im Königshaus der Ghule die wahre Kunst bewundern kann..."
  },
  AvgVideoCaption_96010_Content_30 = {
    Text = "Du hast die Seele dieses Zutats gestört und auch meine künstlerische Arbeit unterbrochen"
  },
  AvgVideoCaption_96010_Content_31 = {
    Text = "Ich habe eigens befohlen, seine Innereien zu schonen"
  },
  AvgVideoCaption_96010_Content_32 = {
    Text = "Eingeweide sind komplex und schmutzig"
  },
  AvgVideoCaption_96010_Content_33 = {
    Text = "Doch nach dem Kochen werden sie sich in die edelsten und faszinierendsten Bestandteile verwandeln"
  },
  AvgVideoCaption_96010_Content_34 = {
    Text = "Bitte, Mr. Pickman"
  },
  AvgVideoCaption_96010_Content_35 = {
    Text = "Dieses halbe Herz gehört dir"
  },
  AvgVideoCaption_96010_Content_36 = {
    Text = "Nein... ich... ich habe dieses Hobby nicht..."
  },
  AvgVideoCaption_96010_Content_37 = {
    Text = "Ich bin hier, um Inspiration zu suchen..."
  },
  AvgVideoCaption_96010_Content_38 = {
    Text = "Was hat das Verschlingen einer Leiche mit Kunst zu tun?"
  },
  AvgVideoCaption_96010_Content_39 = {
    Text = "Das wird dir helfen, in deine Schöpfung einzutreten"
  },
  AvgVideoCaption_96010_Content_4 = {
    Text = "Ich habe alles im menschlichen Reich zurückgelassen und bin hierher gekommen"
  },
  AvgVideoCaption_96010_Content_40 = {
    Text = "Verstehe den Ghul, werde zum Ghul"
  },
  AvgVideoCaption_96010_Content_41 = {
    Text = "Erst danach kann dein Pinsel die wahre Schönheit berühren"
  },
  AvgVideoCaption_96010_Content_42 = {
    Text = "Die Wahrheit der Schöpfung, du hast sie immer verstanden"
  },
  AvgVideoCaption_96010_Content_43 = {
    Text = "Deswegen hast du die Welt der Menschen verlassen und bist in meine Königsstadt gekommen"
  },
  AvgVideoCaption_96010_Content_44 = {
    Text = "Das stimmt, aber..."
  },
  AvgVideoCaption_96010_Content_45 = {
    Text = "Probiere es, Mr. Pickman"
  },
  AvgVideoCaption_96010_Content_46 = {
    Text = "Für die Kunst"
  },
  AvgVideoCaption_96010_Content_47 = {Text = "Das ist..."},
  AvgVideoCaption_96010_Content_48 = {
    Text = "Stimmt, Mr. Pickman"
  },
  AvgVideoCaption_96010_Content_49 = {
    Text = "Das dir ins Ohr flüstert"
  },
  AvgVideoCaption_96010_Content_5 = {
    Text = "Aber dieses kitschige Restaurant"
  },
  AvgVideoCaption_96010_Content_50 = {
    Text = "Es ist die Seele des Verschlingenen"
  },
  AvgVideoCaption_96010_Content_51 = {
    Text = "Seele... Seele?"
  },
  AvgVideoCaption_96010_Content_52 = {
    Text = "Menschen beschreiben uns oft als eine Gruppe minderwertiger Aasfresser"
  },
  AvgVideoCaption_96010_Content_53 = {
    Text = "Aber Ghule sehnen sich nicht nach verfaultem Fleisch"
  },
  AvgVideoCaption_96010_Content_54 = {
    Text = "Was uns wirklich beunruhigt, ist die Seele unter dem verrotteten Fleisch"
  },
  AvgVideoCaption_96010_Content_55 = {
    Text = "Es sind die wertvollen Erinnerungen, die in den Gräbern begraben wurden"
  },
  AvgVideoCaption_96010_Content_56 = {
    Text = "Mr. Pickman, Ihre zitternden Fingerspitzen"
  },
  AvgVideoCaption_96010_Content_57 = {
    Text = "Deine Angst und Erregung wurden enthüllt"
  },
  AvgVideoCaption_96010_Content_58 = {
    Text = "Komm, schluck dieses Herz herunter"
  },
  AvgVideoCaption_96010_Content_59 = {
    Text = "Sag mir, was du gesehen hast!"
  },
  AvgVideoCaption_96010_Content_6 = {
    Text = "Ein wahrer Inspirationsschrein"
  },
  AvgVideoCaption_96010_Content_60 = {
    Text = "Ich habe es gesehen..."
  },
  AvgVideoCaption_96010_Content_61 = {
    Text = "Es ist das Reich der Menschheit, das dem König nachjagt, der Unsterblichkeit sucht..."
  },
  AvgVideoCaption_96010_Content_62 = {
    Text = "Gefunden..."
  },
  AvgVideoCaption_96010_Content_63 = {
    Text = "Er betrat mit der menschlichen Armee die Königsstadt"
  },
  AvgVideoCaption_96010_Content_64 = {Text = "Blut..."},
  AvgVideoCaption_96010_Content_65 = {
    Text = "Verstümmelung..."
  },
  AvgVideoCaption_96010_Content_66 = {
    Text = "Massaker..."
  },
  AvgVideoCaption_96010_Content_67 = {
    Text = "Es ist tatsächlich Sie, Herr Doresain..."
  },
  AvgVideoCaption_96010_Content_68 = {
    Text = "Sie umarmten seine Leiche..."
  },
  AvgVideoCaption_96010_Content_69 = {
    Text = "Ihr tanzt im Mondlicht..."
  },
  AvgVideoCaption_96010_Content_7 = {
    Text = "Ich habe bereits eines deiner Gemälde gesehen"
  },
  AvgVideoCaption_96010_Content_70 = {
    Text = "...so hell wie das Mondlicht heute Abend"
  },
  AvgVideoCaption_96010_Content_71 = {
    Text = "Ghouls... fressen ihre eigenen Tanzpartner!"
  },
  AvgVideoCaption_96010_Content_72 = {
    Text = "Dieser tapfere Held"
  },
  AvgVideoCaption_96010_Content_73 = {
    Text = "Mit seiner Armee eroberte er alles, was er begehrte"
  },
  AvgVideoCaption_96010_Content_74 = {
    Text = "<Yellow:Unzufrieden>"
  },
  AvgVideoCaption_96010_Content_75 = {
    Text = "Er will die Unsterblichkeit aus meiner königlichen Stadt rauben"
  },
  AvgVideoCaption_96010_Content_76 = {
    Text = "Doch er versteht es nie, so dumm wie er ist"
  },
  AvgVideoCaption_96010_Content_77 = {
    Text = "Die Unsterblichkeit des Ghuls besteht darin, seinen eigenen Körper auf den Speisetisch zu legen."
  },
  AvgVideoCaption_96010_Content_78 = {
    Text = "um die Erinnerung für immer zu bewahren"
  },
  AvgVideoCaption_96010_Content_79 = {
    Text = "Wir schneiden die Leichen unserer Angehörigen und beißen in die Seelen unserer Lieben"
  },
  AvgVideoCaption_96010_Content_8 = {
    Text = "Das verborgene Talent und die Leidenschaft in den Linien des Wahnsinns"
  },
  AvgVideoCaption_96010_Content_80 = {
    Text = "Speicher ihrer Erinnerungen im Fleisch"
  },
  AvgVideoCaption_96010_Content_81 = {
    Text = "Warten auf den nächsten Menschen, der verschlungen wird..."
  },
  AvgVideoCaption_96010_Content_82 = {
    Text = "Einmal zu essen, wie kurz doch das ist"
  },
  AvgVideoCaption_96010_Content_83 = {
    Text = "Gerade in dieser kurzen Freude"
  },
  AvgVideoCaption_96010_Content_84 = {
    Text = "Wir haben die wahre Ewigkeit erlangt..."
  },
  AvgVideoCaption_96010_Content_85 = {
    Text = "Flucht ist keine elegante Option"
  },
  AvgVideoCaption_96010_Content_86 = {
    Text = "Großer menschlicher König"
  },
  AvgVideoCaption_96010_Content_87 = {
    Text = "Hast du das gehört, Mr. Pickman?"
  },
  AvgVideoCaption_96010_Content_88 = {
    Text = "Sein schmerzerfülltes, lustvolles Stöhnen..."
  },
  AvgVideoCaption_96010_Content_89 = {
    Text = "Das ist der Ruf des Königs in die Ewigkeit"
  },
  AvgVideoCaption_96010_Content_9 = {
    Text = "Selbst ich bin davon berührt"
  },
  AvgVideoCaption_96010_Content_90 = {
    Text = "Das ist der Ruf des Essens an den Feinschmecker"
  },
  AvgVideoCaption_96010_Content_91 = {
    Text = "Stimmt, er sehnt sich nach uns"
  },
  AvgVideoCaption_96010_Content_92 = {
    Text = "Genau wie wir sehnen sie sich nach ihm..."
  },
  AvgVideoCaption_96010_Content_93 = {
    Text = "Er ist für die Ewigkeit gekommen, also werde ich sie ihm gewähren!"
  },
  AvgVideoCaption_96010_Content_94 = {
    Text = "Dieses blaugraue Seelenlicht..."
  },
  AvgVideoCaption_96010_Content_95 = {
    Text = "Dieses strömende, lebendige Blut..."
  },
  AvgVideoCaption_96010_Content_96 = {
    Text = "Welche Farben braucht man, um dieses einzigartige Bild zu schaffen?"
  },
  AvgVideoCaption_96010_Content_97 = {
    Text = "Mein Stift... Wo ist meine Farbe?!"
  },
  AvgVideoCaption_96010_Content_98 = {
    Text = "Lass mich bleiben, Herr Doresain!"
  },
  AvgVideoCaption_96010_Content_99 = {
    Text = "Ich werde ein einzigartiges Meisterwerk erschaffen...!"
  },
  AvgVideoCaption_96789_Content_1 = {
    Text = "Das Essen ist das Erste, was wir gelernt haben"
  },
  AvgVideoCaption_96789_Content_10 = {
    Text = "Warte auf dein Wachstum"
  },
  AvgVideoCaption_96789_Content_11 = {Text = "Reif"},
  AvgVideoCaption_96789_Content_12 = {Text = "Blühen"},
  AvgVideoCaption_96789_Content_13 = {
    Text = "Halte meine Hand"
  },
  AvgVideoCaption_96789_Content_14 = {
    Text = "Meine Delikatesse, meine Geliebte"
  },
  AvgVideoCaption_96789_Content_15 = {
    Text = "In dieser sanften Streichlung"
  },
  AvgVideoCaption_96789_Content_16 = {
    Text = "Der vorherbestimmte Moment wird schließlich reifen"
  },
  AvgVideoCaption_96789_Content_17 = {
    Text = "Lass mich für dich opfern..."
  },
  AvgVideoCaption_96789_Content_18 = {
    Text = "Deinen duftenden Körper darbringen"
  },
  AvgVideoCaption_96789_Content_19 = {
    Text = "Bring dein duftendes Fleisch dar!"
  },
  AvgVideoCaption_96789_Content_2 = {
    Text = "Pssst... spüre es in Ruhe"
  },
  AvgVideoCaption_96789_Content_20 = {
    Text = "Werde Essen, das ist das Letzte, was du lernen musst"
  },
  AvgVideoCaption_96789_Content_21 = {
    Text = "Kannst du es riechen?"
  },
  AvgVideoCaption_96789_Content_22 = {
    Text = "Die nächste Mahlzeit..."
  },
  AvgVideoCaption_96789_Content_23 = {
    Text = "Ist das dein Duft?"
  },
  AvgVideoCaption_96789_Content_3 = {
    Text = "Fühle, wie die Flamme dich zärtlich leckt"
  },
  AvgVideoCaption_96789_Content_4 = {
    Text = "Spür meine Lippen und meine Zähne"
  },
  AvgVideoCaption_96789_Content_5 = {
    Text = "über deine Haut und Organe gleiten"
  },
  AvgVideoCaption_96789_Content_6 = {
    Text = "Im Mondlicht"
  },
  AvgVideoCaption_96789_Content_7 = {
    Text = "Ich habe deinen Atem der Angst gehört"
  },
  AvgVideoCaption_96789_Content_8 = {
    Text = "Ah, keine Angst"
  },
  AvgVideoCaption_96789_Content_9 = {
    Text = "Ich werde geduldig warten"
  },
  AvgVideoCaption_98516_Content_1 = {
    Text = "Hmm, hier ist es so feucht... wie in einem schwül-heißen Kessel..."
  },
  AvgVideoCaption_98516_Content_10 = {Text = "Angekommen"},
  AvgVideoCaption_98516_Content_11 = {
    Text = "Ritual-Geisterbannplatz – En-I-Heiligtum"
  },
  AvgVideoCaption_98516_Content_12 = {
    Text = "wie immer der Geruch von Blut"
  },
  AvgVideoCaption_98516_Content_13 = {
    Text = "Lass mich sehen, was es gibt"
  },
  AvgVideoCaption_98516_Content_14 = {
    Text = "Wachsfigur, die ihren gesamten Honig entleert"
  },
  AvgVideoCaption_98516_Content_15 = {
    Text = "Gesichtsloser"
  },
  AvgVideoCaption_98516_Content_16 = {
    Text = "Chimären aus zusammengesetzten menschlichen Körpern"
  },
  AvgVideoCaption_98516_Content_17 = {
    Text = "Knochen treten nach außen..."
  },
  AvgVideoCaption_98516_Content_18 = {
    Text = "Blumentopf?"
  },
  AvgVideoCaption_98516_Content_19 = {
    Text = "von Muskeln umhüllte Kugel"
  },
  AvgVideoCaption_98516_Content_2 = {
    Text = "<Yellow:unwohl>"
  },
  AvgVideoCaption_98516_Content_20 = {
    Text = "Ist es dadurch entstanden, dass die Haut abgezogen und die Muskeln mit einem Schweißgerät zusammengefügt wurden?"
  },
  AvgVideoCaption_98516_Content_21 = {
    Text = "Die Stimmbänder der Sphäre sind zerstört"
  },
  AvgVideoCaption_98516_Content_22 = {
    Text = "Anscheinend vertritt man hier nicht die Ansicht, dass der schmerzhafte Schrei des Opfers die beste Opferung ist"
  },
  AvgVideoCaption_98516_Content_23 = {Text = "Oh?"},
  AvgVideoCaption_98516_Content_24 = {
    Text = "Dieser Beutel..."
  },
  AvgVideoCaption_98516_Content_25 = {
    Text = "Zerquetsche die harten Bestandteile des Materials"
  },
  AvgVideoCaption_98516_Content_26 = {
    Text = "Flüssigkeit unter die Haut injizieren, um die inneren Organe zu schützen, und sie am Ende in einen Sack füllen?"
  },
  AvgVideoCaption_98516_Content_27 = {
    Text = "Material für die 32. Ritualfüllung: LT-13"
  },
  AvgVideoCaption_98516_Content_28 = {
    Text = "Dieses Ritual folgt einem neuen Ablauf – begleitende Materialien: DT-13 wird ausgewählt..."
  },
  AvgVideoCaption_98516_Content_29 = {
    Text = "Drei minderjährige Nachkommen von LT-13..."
  },
  AvgVideoCaption_98516_Content_3 = {
    Text = "Hehe, das zeigt doch nur, wie weit deine Berühmtheit als große Schwester verbreitet ist."
  },
  AvgVideoCaption_98516_Content_30 = {
    Text = "Sie sind immer noch so ekelerregend"
  },
  AvgVideoCaption_98516_Content_31 = {
    Text = "Sehr gut, sehr gut ... Es scheint, dass ich dieses Mal nicht mit leeren Händen zurückkehren werde."
  },
  AvgVideoCaption_98516_Content_32 = {
    Text = "Wache kommt etwas schnell"
  },
  AvgVideoCaption_98516_Content_33 = {
    Text = "Damit ist die Besuchszeit beendet."
  },
  AvgVideoCaption_98516_Content_34 = {
    Text = "Es gab viel mehr Menschen als erwartet, aber ..."
  },
  AvgVideoCaption_98516_Content_35 = {
    Text = "Ich habe gerade die richtige Stimmung, um euer Wehklagen anzusehen!"
  },
  AvgVideoCaption_98516_Content_36 = {
    Text = "Es ist etwas zu heiß hergegangen"
  },
  AvgVideoCaption_98516_Content_37 = {
    Text = "Lass einen am Leben, damit er uns den Weg weisen kann"
  },
  AvgVideoCaption_98516_Content_38 = {
    Text = "... Vergiss es, niemand kann jetzt hier entkommen, also spielt es keine Rolle, ob wir uns beeilen"
  },
  AvgVideoCaption_98516_Content_39 = {
    Text = "Hmm? Schon so schnell zurück..."
  },
  AvgVideoCaption_98516_Content_4 = {
    Text = "Zwing sie dazu, sich an solchen Orten verstecken zu müssen"
  },
  AvgVideoCaption_98516_Content_40 = {
    Text = "Was hast du erlebt?"
  },
  AvgVideoCaption_98516_Content_41 = {
    Text = "In diese Richtung?"
  },
  AvgVideoCaption_98516_Content_42 = {
    Text = "Ich verstehe"
  },
  AvgVideoCaption_98516_Content_43 = {
    Text = "Niemand wird dein Opfer vergessen"
  },
  AvgVideoCaption_98516_Content_44 = {
    Text = "So viel reden, wozu?"
  },
  AvgVideoCaption_98516_Content_45 = {
    Text = "Ich sage, du hast dich geopfert, und damit ist es so."
  },
  AvgVideoCaption_98516_Content_46 = {
    Text = "Beim nächsten Treffen werde ich dich als Grund nennen, um dich zu betrauern"
  },
  AvgVideoCaption_98516_Content_47 = {
    Text = "Stellt sicher, dass ihr schwarz-weiße Fotos zum Aufstellen bereit habt"
  },
  AvgVideoCaption_98516_Content_48 = {
    Text = "Verdammter Kerl, Loxx, wo bist du!"
  },
  AvgVideoCaption_98516_Content_49 = {
    Text = "Das letzte Signal von Locks verschwand hier..."
  },
  AvgVideoCaption_98516_Content_5 = {
    Text = "Warum warst du früher nicht so geschwätzig?"
  },
  AvgVideoCaption_98516_Content_50 = {
    Text = "... keine Antwort"
  },
  AvgVideoCaption_98516_Content_51 = {
    Text = "Jetzt muss ich mich allein verlassen"
  },
  AvgVideoCaption_98516_Content_52 = {
    Text = "Komm schon, Keli"
  },
  AvgVideoCaption_98516_Content_53 = {
    Text = "Glaube an dich selbst..."
  },
  AvgVideoCaption_98516_Content_54 = {Text = "Was?!"},
  AvgVideoCaption_98516_Content_55 = {
    Text = "Widerständler, die dem Erscheinen der neuen Welt trotzen"
  },
  AvgVideoCaption_98516_Content_56 = {
    Text = "Werde das neue Opfer meines Herrn!"
  },
  AvgVideoCaption_98516_Content_57 = {
    Text = "Verdammter Ketzer... Loxx und Krii..."
  },
  AvgVideoCaption_98516_Content_58 = {
    Text = "Ich werde eure Leichen mit dem gotteslästerlichsten Ritual schänden"
  },
  AvgVideoCaption_98516_Content_59 = {
    Text = "Eure Seelen sollen für immer in Schmerzen leben!"
  },
  AvgVideoCaption_98516_Content_6 = {
    Text = "Ich hätte dich gleich den alten Herren überlassen sollen."
  },
  AvgVideoCaption_98516_Content_60 = {Text = "Wirklich?"},
  AvgVideoCaption_98516_Content_61 = {
    Text = "Das ist wirklich schade"
  },
  AvgVideoCaption_98516_Content_62 = {
    Text = "Denn die Seele dieses Jungen ist bereits zu mir zurückgekehrt"
  },
  AvgVideoCaption_98516_Content_63 = {
    Text = "Außerdem heißt er nicht Locks"
  },
  AvgVideoCaption_98516_Content_64 = {
    Text = "Ich heiße nicht Klei"
  },
  AvgVideoCaption_98516_Content_65 = {
    Text = "Nein, unmöglich!"
  },
  AvgVideoCaption_98516_Content_66 = {
    Text = "Wie kommst du dazu, noch am Leben zu sein!"
  },
  AvgVideoCaption_98516_Content_67 = {
    Text = "Da du eine solche Kraft besitzt, warum dann ...?"
  },
  AvgVideoCaption_98516_Content_68 = {
    Text = "Natürlich ist es, eure Vorlieben zu befriedigen"
  },
  AvgVideoCaption_98516_Content_69 = {
    Text = "Seid ihr nicht am liebsten?"
  },
  AvgVideoCaption_98516_Content_7 = {
    Text = "<Del:Nein, nein, nein, große Schwester>"
  },
  AvgVideoCaption_98516_Content_70 = {
    Text = "Mag es, das Gesicht der Beute zu sehen"
  },
  AvgVideoCaption_98516_Content_71 = {
    Text = "Zeig jetzt diesen verzweifelten Gesichtsausdruck"
  },
  AvgVideoCaption_98516_Content_72 = {Text = "Aaaaaaah!"},
  AvgVideoCaption_98516_Content_73 = {
    Text = "Sei froh, mir geht es gerade ziemlich gut"
  },
  AvgVideoCaption_98516_Content_74 = {
    Text = "Denn es bereitet mir stets Vergnügen, euch abscheulichen Schurken, die das Menschliche mit Füßen tretet, zu foltern"
  },
  AvgVideoCaption_98516_Content_75 = {
    Text = "Als Belohnung darfst du es genießen"
  },
  AvgVideoCaption_98516_Content_76 = {
    Text = "Schmerz, der vor Hass und Verlangen überquillt!"
  },
  AvgVideoCaption_98516_Content_77 = {
    Text = "Alle Knochen vollständig zu Brei zerquetschen und die Hälfte des entstandenen Knochenschlamms aus dem Körper entfernen"
  },
  AvgVideoCaption_98516_Content_78 = {
    Text = "Die Knochenreste in die Augenhöhlen geben und mit dem Augapfel gemeinsam so lange mahlen, bis die Struktur vollständig zerstört ist."
  },
  AvgVideoCaption_98516_Content_79 = {
    Text = "Die Haut aufreißen, um die bloßgelegten Nerven zu finden"
  },
  AvgVideoCaption_98516_Content_8 = {
    Text = "Ich wollte nur etwas für eine bessere Stimmung tun"
  },
  AvgVideoCaption_98516_Content_80 = {
    Text = "Nach dem Reiben den gesamten Abschnitt herausziehen"
  },
  AvgVideoCaption_98516_Content_81 = {
    Text = "Dann mit dem glühenden Lauf die Wunde ausbrennen, um die Blutung zu stoppen"
  },
  AvgVideoCaption_98516_Content_82 = {
    Text = "Stellt sicher, dass der Gefolterte nicht zu viel Blut verliert und austrocknet"
  },
  AvgVideoCaption_98516_Content_83 = {
    Text = "Die gesammelten Körperflüssigkeiten in die Atemwege injizieren"
  },
  AvgVideoCaption_98516_Content_84 = {
    Text = "Den Gefolterten in einem Zustand teilweiser Erstickung halten"
  },
  AvgVideoCaption_98516_Content_85 = {
    Text = "Gehirn öffnen und kontinuierliche Stimulation durchführen, um zu verhindern, dass das Ziel ohnmächtig wird"
  },
  AvgVideoCaption_98516_Content_86 = {
    Text = "Zum Schluss schau aus der Ferne..."
  },
  AvgVideoCaption_98516_Content_87 = {
    Text = "Ein gutes Erscheinungsbild, das perfekt zu Leuten wie euch passt"
  },
  AvgVideoCaption_98516_Content_88 = {
    Text = "Diesmal reicht es hier"
  },
  AvgVideoCaption_98516_Content_89 = {
    Text = "Ich habe etwas genug gespielt"
  },
  AvgVideoCaption_98516_Content_9 = {
    Text = "Und ich bevorzuge es, wenn du sagst: “Diese finsteren, niederträchtigen Menschen bevorzugen solche Orte einfach von Natur aus.“"
  },
  AvgVideoCaption_98516_Content_90 = {
    Text = "Verschwinde, du schmutziger Abschaum"
  },
  AvgVideoCaption_98516_Content_91 = {
    Text = "Lass mich als Nächstes suchen, wo das Ding ist"
  },
  AvgVideoCaption_98516_Content_92 = {
    Text = "Gefunden: das Antlitz des namenlosen Chaos"
  },
  AvgVideoCaption_98516_Content_93 = {
    Text = "Ich sagte bereits: Egal, wo du dich versteckst, ich werde dich finden"
  },
  AvgVideoCaption_98516_Content_94 = {
    Text = "Na gut, auf Wiedersehen, Glückwünsche"
  },
  AvgVideoCaption_98516_Content_95 = {
    Text = "Verabschiede dich von diesem Bewusstseinsfaden, du schmutzige Freude!"
  },
  AvgVideoCaption_98516_Content_96 = {
    Text = "Haa, was für ein schöner Tag"
  },
  AvgVideoCaption_98516_Content_97 = {
    Text = "Es ist Zeit, sich zu bewegen und alles in Flammen zu setzen!"
  },
  AvgVideoCaption_98516_Content_98 = {
    Text = "Zerstöre all das Böse!"
  }
})
return Text_AvgVideoCaption
